(async () => {
  const TESTS = [{"name": "SOA-C02 Practice Test 1", "cid": 7305503, "duration": 130, "pass_percent": 72, "questions": [{"assessment_type": "multiple-choice", "question_plain": "A company wants to automatically stop EC2 instances tagged Environment=Dev outside business hours (6 PM–8 AM) with zero manual intervention, and requires an audit trail of every remediation action taken. Which solution BEST meets these requirements?", "prompt": {"question": "<p>A company wants to automatically stop EC2 instances tagged Environment=Dev outside business hours (6 PM–8 AM) with zero manual intervention, and requires an audit trail of every remediation action taken. Which solution BEST meets these requirements?</p>", "answers": ["<p>Create a CloudWatch alarm on CPUUtilization that sends an SNS notification prompting an on-call engineer to stop the instances manually</p>", "<p>Create an EventBridge scheduled rule that invokes an SSM Automation runbook (AWS-StopEC2Instance) targeting instances tagged Environment=Dev, with CloudTrail enabled to log the automation's API calls</p>", "<p>Create an AWS Config rule that evaluates EC2 instance state and flags non-compliant instances for manual remediation by the operations team</p>", "<p>Create a Lambda function invoked by a CloudWatch Logs subscription filter that parses instance state-change log events and stops matching instances</p>"], "feedbacks": ["<p>Requires a human to stop the instance, failing the 'zero manual intervention' requirement, and a CPU alarm has no relationship to a time-based schedule</p>", "<p>An EventBridge scheduled (cron) rule triggering an SSM Automation runbook fully automates the stop action on a fixed schedule with no human involvement, and CloudTrail natively logs every API call the Automation makes, satisfying the audit requirement.</p>", "<p>AWS Config can flag non-compliance but this option explicitly routes to manual remediation by staff, which does not meet the automation requirement</p>", "<p>Log subscription filters react to log events, not to a time schedule; this over-engineers a scheduled task and introduces unnecessary complexity and log-parsing dependencies</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A SysOps administrator needs to run an ad-hoc query directly against an application's CloudWatch Logs group to find all ERROR entries with a response time greater than 5000ms in the last hour, and compute average latency grouped by API endpoint, without exporting the logs to any other service. Which tool should be used?", "prompt": {"question": "<p>A SysOps administrator needs to run an ad-hoc query directly against an application's CloudWatch Logs group to find all ERROR entries with a response time greater than 5000ms in the last hour, and compute average latency grouped by API endpoint, without exporting the logs to any other service. Which tool should be used?</p>", "answers": ["<p>Amazon Athena querying logs exported to S3</p>", "<p>AWS CloudTrail Lake</p>", "<p>CloudWatch metric math on the log group's metric filters</p>", "<p>Amazon CloudWatch Logs Insights</p>"], "feedbacks": ["<p>Athena requires the logs to first be exported to S3 and cataloged, which violates the 'without exporting to a separate service' requirement and adds latency</p>", "<p>CloudTrail Lake queries CloudTrail management/data events, not arbitrary application log content, so it cannot parse custom application error/latency fields</p>", "<p>Metric filters convert log patterns into numeric CloudWatch metrics but cannot perform ad-hoc field extraction or grouped averages across raw log content the way Logs Insights can</p>", "<p>CloudWatch Logs Insights provides a purpose-built query language (filter, parse, stats) that runs directly against log groups in place, supporting field-based filtering and aggregation like average latency per endpoint with no export step required.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A CloudWatch alarm monitors a custom metric that is published only when application errors occur, so many evaluation periods have no data point at all. The admin wants the alarm to remain in the OK state whenever no data is published, since missing data represents 'no errors occurred.' Which missing data treatment setting should be applied to the alarm?", "prompt": {"question": "<p>A CloudWatch alarm monitors a custom metric that is published only when application errors occur, so many evaluation periods have no data point at all. The admin wants the alarm to remain in the OK state whenever no data is published, since missing data represents 'no errors occurred.' Which missing data treatment setting should be applied to the alarm?</p>", "answers": ["<p>Treat missing data as ignore (maintain the alarm's previous state)</p>", "<p>Treat missing data as breaching threshold</p>", "<p>Treat missing data as missing (default behavior)</p>", "<p>Treat missing data as not breaching threshold</p>"], "feedbacks": ["<p>'Ignore/maintain state' keeps whatever the alarm's last state was, which could leave it stuck in ALARM after the last real error datapoint rather than guaranteeing OK</p>", "<p>'Breaching' would force the alarm into ALARM during periods with no data, the opposite of the desired outcome, since no data means no errors occurred</p>", "<p>The default 'missing' setting drives the alarm to INSUFFICIENT_DATA rather than OK, which does not satisfy the requirement to remain in a healthy state during quiet periods</p>", "<p>The 'notBreaching' setting causes every evaluation period with no data point to be treated as if the metric were within the threshold, driving the alarm to OK, which is exactly the desired behavior for a sparse error metric.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Which metric is NOT collected by Amazon EC2's default (hypervisor-level) CloudWatch monitoring, and instead requires installing the CloudWatch agent on the instance?", "prompt": {"question": "<p>Which metric is NOT collected by Amazon EC2's default (hypervisor-level) CloudWatch monitoring, and instead requires installing the CloudWatch agent on the instance?</p>", "answers": ["<p>CPUUtilization</p>", "<p>MemoryUtilization</p>", "<p>NetworkIn / NetworkOut</p>", "<p>DiskReadOps / DiskWriteOps</p>"], "feedbacks": ["<p>CPUUtilization is a standard host-level metric published automatically by EC2 without any agent installation</p>", "<p>Memory utilization is an OS-level metric that AWS's hypervisor cannot observe; it is only available after installing and configuring the CloudWatch agent on the instance, which publishes it as a custom metric.</p>", "<p>Network throughput metrics are captured at the hypervisor level and published by default for every EC2 instance</p>", "<p>Disk operation metrics (Read/Write Ops and bytes) for EBS-backed volumes are also default host-level metrics available without the agent</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An AWS Config rule, s3-bucket-server-side-encryption-enabled, flags non-compliant S3 buckets. The company wants non-compliant buckets to automatically have default encryption enabled with no human involvement, while limiting how many remediation attempts run concurrently to avoid throttling. Which approach achieves this with the least custom code?", "prompt": {"question": "<p>An AWS Config rule, s3-bucket-server-side-encryption-enabled, flags non-compliant S3 buckets. The company wants non-compliant buckets to automatically have default encryption enabled with no human involvement, while limiting how many remediation attempts run concurrently to avoid throttling. Which approach achieves this with the least custom code?</p>", "answers": ["<p>Attach the AWS-managed remediation action AWS-EnableS3BucketEncryption to the Config rule, enable automatic remediation, and configure the retry attempts and remediation execution rate limit in the remediation configuration</p>", "<p>Create an EventBridge rule that triggers on Config compliance-change events and invokes a custom Lambda function that loops through and re-encrypts every S3 bucket in the account</p>", "<p>Enable the Config rule and have an operations engineer review the AWS Config compliance dashboard daily, manually enabling encryption on any flagged buckets</p>", "<p>Associate AWS-EnableS3BucketEncryption as the rule's remediation action but leave automatic remediation disabled, remediating manually when convenient</p>"], "feedbacks": ["<p>AWS Config natively supports associating an SSM Automation document as a remediation action with automatic remediation enabled, including built-in configuration for retry limits and execution rate limiting — meeting every stated requirement without custom code.</p>", "<p>Building a custom Lambda duplicates functionality Config already provides natively, lacks built-in retry/rate-limit controls, and incorrectly targets every bucket in the account instead of only the non-compliant resource</p>", "<p>Manual daily review does not satisfy the 'no human involvement' requirement and introduces remediation delay</p>", "<p>Leaving automatic remediation disabled means remediation only happens when a person acts, which directly fails the automation requirement</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A SysOps administrator publishes a custom CloudWatch metric using PutMetricData and wants to create an alarm that evaluates the metric on a 10-second period for near real-time detection. What must be true of the metric publication and the alarm configuration?", "prompt": {"question": "<p>A SysOps administrator publishes a custom CloudWatch metric using PutMetricData and wants to create an alarm that evaluates the metric on a 10-second period for near real-time detection. What must be true of the metric publication and the alarm configuration?</p>", "answers": ["<p>The metric must be published with StorageResolution set to 60, and the alarm period set to 10 seconds</p>", "<p>The metric must be published with StorageResolution set to 1, but the alarm period must still be set to 60 seconds</p>", "<p>The metric must be published with StorageResolution set to 1, and the alarm period set to 10 or 30 seconds</p>", "<p>High-resolution alarms are not supported by CloudWatch; the minimum alarm period for any metric is always 60 seconds</p>"], "feedbacks": ["<p>StorageResolution=60 publishes the metric at standard (1-minute) resolution, which is incompatible with a 10-second alarm evaluation period</p>", "<p>Publishing at high resolution but then setting the alarm period to 60 seconds discards the sub-minute granularity and defeats the purpose of high-resolution metrics</p>", "<p>To get sub-minute granularity, the custom metric must be published as high-resolution using StorageResolution=1 (1-second granularity), and CloudWatch alarms on high-resolution metrics support periods of exactly 10 or 30 seconds, enabling near real-time alerting.</p>", "<p>This is factually incorrect: CloudWatch does support high-resolution alarms with 10- or 30-second periods when the underlying metric is published at 1-second resolution</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company uses AWS Config to track compliance of S3 buckets across 40 accounts in an AWS Organization. The security team wants any S3 bucket found without default encryption to be automatically remediated within minutes, without manual intervention, using native AWS services and minimal custom code. Which solution BEST meets these requirements?", "prompt": {"question": "<p>A company uses AWS Config to track compliance of S3 buckets across 40 accounts in an AWS Organization. The security team wants any S3 bucket found without default encryption to be automatically remediated within minutes, without manual intervention, using native AWS services and minimal custom code. Which solution BEST meets these requirements?</p>", "answers": ["<p>Create an EventBridge rule that matches CloudTrail S3 API calls and invokes a Lambda function to check and enable encryption on the bucket</p>", "<p>Create a CloudWatch alarm on S3 PutBucket API activity that sends an SNS notification to the security team for manual review</p>", "<p>Configure a Systems Manager State Manager association that runs an inventory collection document against all S3 buckets once daily</p>", "<p>Enable the AWS Config managed rule s3-bucket-server-side-encryption-enabled and attach automatic remediation using the AWSConfigRemediation-EnableS3BucketEncryption SSM Automation document</p>"], "feedbacks": ["<p>This requires building and maintaining custom Lambda logic and doesn't leverage the built-in AWS Config remediation workflow, adding unnecessary complexity</p>", "<p>This only notifies a human and does not remediate anything automatically, failing the 'within minutes, no manual intervention' requirement</p>", "<p>State Manager inventory collection gathers metadata about instances/resources; it does not detect encryption compliance or remediate S3 buckets</p>", "<p>AWS Config managed rules can be paired directly with an auto-remediation action pointing to an SSM Automation document. AWSConfigRemediation-EnableS3BucketEncryption is a pre-built AWS-owned document specifically designed to remediate this exact compliance finding automatically and quickly, with no custom code required.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A SysOps administrator needs to determine how many HTTP 500 errors occurred per 5-minute interval over the last 24 hours, aggregated across three separate application log groups in CloudWatch Logs. The analysis is a one-time investigation and must not require provisioning any new infrastructure. Which approach BEST meets these requirements?", "prompt": {"question": "<p>A SysOps administrator needs to determine how many HTTP 500 errors occurred per 5-minute interval over the last 24 hours, aggregated across three separate application log groups in CloudWatch Logs. The analysis is a one-time investigation and must not require provisioning any new infrastructure. Which approach BEST meets these requirements?</p>", "answers": ["<p>Run a CloudWatch Logs Insights query using stats count() by bin(5m) against all three log groups simultaneously</p>", "<p>Export all three log groups to Amazon S3 and query the exported logs using Amazon Athena</p>", "<p>Create a metric filter matching the string \"500\" on each of the three log groups and then view the resulting metric on a CloudWatch dashboard</p>", "<p>Enable CloudWatch cross-account observability and analyze the request flow using AWS X-Ray trace maps</p>"], "feedbacks": ["<p>CloudWatch Logs Insights supports querying across multiple log groups in a single query and includes a stats command with bin() for time-bucketed aggregation, giving an immediate one-time historical answer with no infrastructure to provision.</p>", "<p>Exporting to S3 and using Athena requires setting up an export job, a table/crawler, and query infrastructure — far more setup than needed for a one-time check</p>", "<p>Metric filters only generate data points from log events ingested after the filter is created; they cannot retroactively analyze the prior 24 hours of already-existing log data</p>", "<p>X-Ray traces show service call latency and dependency maps, not error string counts from application log text</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A SysOps administrator installed the CloudWatch agent on an Amazon Linux EC2 instance to monitor memory utilization, since memory usage is not part of EC2 basic monitoring. The instance's IAM role already includes the CloudWatchAgentServerPolicy, and the agent starts successfully with no errors. However, the mem_used_percent metric never appears in CloudWatch under the expected namespace. Which configuration change is MOST likely needed to resolve this?", "prompt": {"question": "<p>A SysOps administrator installed the CloudWatch agent on an Amazon Linux EC2 instance to monitor memory utilization, since memory usage is not part of EC2 basic monitoring. The instance's IAM role already includes the CloudWatchAgentServerPolicy, and the agent starts successfully with no errors. However, the mem_used_percent metric never appears in CloudWatch under the expected namespace. Which configuration change is MOST likely needed to resolve this?</p>", "answers": ["<p>Add a \"mem\" measurement block under the \"metrics_collected\" section of the CloudWatch agent JSON configuration file</p>", "<p>Attach the CloudWatchAgentAdminPolicy to the instance role in addition to the CloudWatchAgentServerPolicy</p>", "<p>Add a \"logs\" section to the CloudWatch agent configuration file so metrics collection is enabled</p>", "<p>Open outbound HTTPS traffic (port 443) from the instance's security group to the CloudWatch endpoint</p>"], "feedbacks": ["<p>The CloudWatch agent only publishes metrics that are explicitly defined under metrics_collected in its JSON configuration file. If mem_used_percent is missing, the most likely cause is that the \"mem\" measurement block was never added to that section, so the agent simply isn't configured to collect it.</p>", "<p>CloudWatchAgentServerPolicy already grants cloudwatch:PutMetricData; the Admin policy is only needed for managing agent configs in Systems Manager Parameter Store, not for publishing metrics</p>", "<p>The logs section configures log file collection and is unrelated to whether metrics are published; metrics and logs are independent sections in the same config file</p>", "<p>If outbound HTTPS were fully blocked, no metrics or logs at all would reach CloudWatch, not just the memory metric — the scenario states the agent starts with no errors, which points to a config content issue instead</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services company runs a critical Amazon RDS for MySQL database. The application team requires near-zero RPO and automatic failover during an Availability Zone outage, with no changes to the application's database connection string. Which solution BEST meets these requirements?", "prompt": {"question": "<p>A financial services company runs a critical Amazon RDS for MySQL database. The application team requires near-zero RPO and automatic failover during an Availability Zone outage, with no changes to the application's database connection string. Which solution BEST meets these requirements?</p>", "answers": ["<p>Create a same-Region Read Replica and manually promote it during an outage</p>", "<p>Take manual DB snapshots every hour and restore from the latest snapshot during an outage</p>", "<p>Enable Multi-AZ deployment for the RDS instance</p>", "<p>Create a cross-Region Read Replica and update the application connection string during failover</p>"], "feedbacks": ["<p>Read Replicas use asynchronous replication and require a manual promotion, introducing both data loss risk and an application endpoint change.</p>", "<p>Hourly snapshots can lose up to an hour of data (RPO of up to 60 minutes) and require a manual, time-consuming restore process.</p>", "<p>Multi-AZ synchronously replicates data to a standby in another AZ and automatically fails over using the same DNS endpoint, delivering near-zero RPO and no application changes.</p>", "<p>Cross-Region Read Replicas add replication lag and require updating the connection string, violating the 'no application changes' requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "An Auto Scaling group backs a web tier whose average CPU utilization must be maintained at approximately 50% regardless of load fluctuations, without manual threshold tuning. Which Auto Scaling policy type should be used?", "prompt": {"question": "<p>An Auto Scaling group backs a web tier whose average CPU utilization must be maintained at approximately 50% regardless of load fluctuations, without manual threshold tuning. Which Auto Scaling policy type should be used?</p>", "answers": ["<p>Scheduled scaling</p>", "<p>Target tracking scaling</p>", "<p>Simple scaling</p>", "<p>Step scaling</p>"], "feedbacks": ["<p>Scheduled scaling only changes capacity at predefined times and cannot react to actual, unpredictable CPU load.</p>", "<p>Target tracking scaling automatically adjusts capacity to keep a specified metric, such as average CPU utilization, at a chosen target value, adding or removing instances as needed without manual threshold management.</p>", "<p>Simple scaling triggers one scaling action per alarm and enters a cooldown period, requiring manual threshold and step configuration to approximate a target value.</p>", "<p>Step scaling scales in defined increments based on the magnitude of the alarm breach but still requires manually defined thresholds rather than automatically maintaining a target.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs an active-passive architecture across two AWS Regions. If the primary Region's application becomes unhealthy, DNS queries must automatically route to the secondary Region without manual intervention. Which Route 53 configuration should be used?", "prompt": {"question": "<p>A company runs an active-passive architecture across two AWS Regions. If the primary Region's application becomes unhealthy, DNS queries must automatically route to the secondary Region without manual intervention. Which Route 53 configuration should be used?</p>", "answers": ["<p>Weighted routing policy with equal weights on both records</p>", "<p>Geolocation routing policy</p>", "<p>Failover routing policy with health checks on the primary record</p>", "<p>Latency-based routing policy</p>"], "feedbacks": ["<p>Weighted routing distributes traffic by assigned proportions for active-active use cases and does not provide automatic failover based on health.</p>", "<p>Geolocation routing routes based on the geographic location of the requester, not on the health of an endpoint, so it will not fail over automatically.</p>", "<p>Failover routing policy is designed for active-passive configurations: Route 53 monitors the primary record's health check and automatically routes traffic to the secondary record when the primary is unhealthy.</p>", "<p>Latency-based routing selects the Region with the lowest latency for active-active setups; it does not enforce a primary/secondary failover relationship.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A SysOps administrator must implement automated daily backups for a fleet of EC2 instances' EBS volumes, retaining each snapshot for 7 days, with the least ongoing management overhead and no need to back up other AWS services.", "prompt": {"question": "<p>A SysOps administrator must implement automated daily backups for a fleet of EC2 instances' EBS volumes, retaining each snapshot for 7 days, with the least ongoing management overhead and no need to back up other AWS services.</p>", "answers": ["<p>Write a Lambda function triggered by an hourly CloudWatch Events rule to call CreateSnapshot and DeleteSnapshot manually</p>", "<p>Enable S3 Lifecycle policies to expire objects containing snapshot metadata after 7 days</p>", "<p>Create an Amazon Data Lifecycle Manager (DLM) policy targeting the volumes with a daily schedule and 7-day retention</p>", "<p>Create an AWS Backup plan with a backup vault covering EC2, RDS, and DynamoDB resources on a daily schedule</p>"], "feedbacks": ["<p>A custom Lambda function requires writing and maintaining code for scheduling, error handling, and cleanup, which is far more overhead than a managed native feature.</p>", "<p>S3 Lifecycle policies manage object expiration in S3 buckets; they do not create or manage EBS snapshots at all.</p>", "<p>Amazon Data Lifecycle Manager natively automates EBS snapshot creation, retention, and deletion on a schedule with minimal setup, and is purpose-built for exactly this single-service use case.</p>", "<p>AWS Backup adds cross-service backup plan complexity for RDS and DynamoDB that isn't needed here, increasing configuration overhead versus DLM for an EBS-only requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A media company stores critical design documents in an S3 bucket in us-east-1 and needs an automated, ongoing copy of every new and updated object stored in a bucket in eu-west-1 for disaster recovery, preserving all object versions.", "prompt": {"question": "<p>A media company stores critical design documents in an S3 bucket in us-east-1 and needs an automated, ongoing copy of every new and updated object stored in a bucket in eu-west-1 for disaster recovery, preserving all object versions.</p>", "answers": ["<p>Enable S3 Transfer Acceleration on the source bucket</p>", "<p>Enable versioning on both buckets and configure S3 Cross-Region Replication (CRR) between them</p>", "<p>Configure an S3 Lifecycle policy to transition objects to the S3 Glacier storage class</p>", "<p>Schedule a nightly EBS snapshot copy job between the two Regions</p>"], "feedbacks": ["<p>Transfer Acceleration speeds up uploads to S3 over long distances using CloudFront edge locations; it does not replicate data to another Region.</p>", "<p>S3 Cross-Region Replication requires versioning enabled on source and destination buckets and automatically copies new and updated objects to the destination Region, meeting the ongoing DR replication requirement.</p>", "<p>A Lifecycle policy to Glacier changes the storage class within the same bucket/Region and does not create a cross-Region copy.</p>", "<p>EBS snapshots apply to block storage volumes attached to EC2 instances, not to objects stored in S3 buckets.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "Which statement correctly distinguishes Recovery Time Objective (RTO) from Recovery Point Objective (RPO) in an AWS disaster recovery design?", "prompt": {"question": "<p>Which statement correctly distinguishes Recovery Time Objective (RTO) from Recovery Point Objective (RPO) in an AWS disaster recovery design?</p>", "answers": ["<p>RTO defines the maximum acceptable downtime after a disaster, while RPO defines the maximum acceptable amount of data loss measured in time</p>", "<p>RTO defines the maximum acceptable amount of data loss measured in time, while RPO defines the maximum acceptable downtime after a disaster</p>", "<p>RTO and RPO both refer to the same metric but are used by different AWS services</p>", "<p>RTO is measured in dollars of lost revenue, while RPO is measured in minutes of downtime</p>"], "feedbacks": ["<p>RTO is the target duration within which a system must be restored after an outage, while RPO is the maximum tolerable period in which data might be lost due to an incident, measured back from the failure point.</p>", "<p>This swaps the two definitions: it incorrectly assigns data loss to RTO and downtime to RPO.</p>", "<p>RTO and RPO are distinct metrics addressing different aspects of continuity (downtime vs. data loss) and are not interchangeable.</p>", "<p>Neither metric is measured in dollars; RTO is a time-based downtime target and RPO is a time-based data-loss tolerance, not a monetary or purely downtime figure for RPO.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs a production Amazon RDS for MySQL database with Multi-AZ enabled in us-east-1. The business requires that if the entire us-east-1 Region becomes unavailable, the database must be recovered with an RPO of 5 minutes and an RTO of 15 minutes in another Region. Which solution meets these requirements with the LEAST operational complexity during a failover event?", "prompt": {"question": "<p>A company runs a production Amazon RDS for MySQL database with Multi-AZ enabled in us-east-1. The business requires that if the entire us-east-1 Region becomes unavailable, the database must be recovered with an RPO of 5 minutes and an RTO of 15 minutes in another Region. Which solution meets these requirements with the LEAST operational complexity during a failover event?</p>", "answers": ["<p>Rely on the existing Multi-AZ standby instance and configure automatic failover only within us-east-1</p>", "<p>Take manual RDS snapshots every 24 hours and copy them to us-west-2 using the AWS CLI, restoring a new instance from the latest snapshot when needed</p>", "<p>Configure AWS Backup with a daily backup plan for the RDS instance and copy backups to us-west-2, restoring the database from the most recent backup during an outage</p>", "<p>Create a cross-Region read replica of the RDS instance in us-west-2, and configure a Route 53 failover routing policy with health checks so the application can be redirected to a promoted replica during a Regional outage</p>"], "feedbacks": ["<p>Multi-AZ only protects against AZ-level failures within a single Region; it provides no protection if the entire Region becomes unavailable, so it cannot meet the cross-Region requirement at all.</p>", "<p>Daily manual snapshots copied to another Region create a worst-case RPO of up to 24 hours, far exceeding the 5-minute requirement, and manual snapshot copy processes add unpredictable delay.</p>", "<p>AWS Backup with a daily plan also results in up to a 24-hour RPO, and restoring a full RDS instance from a backup can take well over 15 minutes depending on database size, failing the RTO target.</p>", "<p>A cross-Region read replica continuously streams changes asynchronously, typically keeping replication lag to seconds, which satisfies a 5-minute RPO. Promoting the replica to a standalone writable instance takes only a few minutes, and Route 53 health checks with failover routing automatically detect the primary Region's unavailability and redirect traffic, meeting the 15-minute RTO with minimal manual intervention.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company uses AWS Organizations with dozens of member accounts across three Regions. The SysOps team must automatically deploy a standard S3 bucket and IAM role into every existing and future member account in all three Regions, without accounts having to individually assume a deployment role. Which solution meets this requirement with the LEAST ongoing operational effort?", "prompt": {"question": "<p>A company uses AWS Organizations with dozens of member accounts across three Regions. The SysOps team must automatically deploy a standard S3 bucket and IAM role into every existing and future member account in all three Regions, without accounts having to individually assume a deployment role. Which solution meets this requirement with the LEAST ongoing operational effort?</p>", "answers": ["<p>Write a Lambda function triggered by AWS Config that deploys a CloudFormation stack in each account when drift is detected</p>", "<p>Manually create a CloudFormation stack in each account and Region using self-managed permissions and cross-account IAM roles</p>", "<p>Package the resources into an AWS Elastic Beanstalk application and deploy a new environment in each account</p>", "<p>Create an AWS CloudFormation StackSet with service-managed permissions and automatic deployment enabled for the organization</p>"], "feedbacks": ["<p>AWS Config drift detection doesn't provision resources; it evaluates compliance of existing resources, not automated cross-account deployment.</p>", "<p>Self-managed permissions require manually creating and maintaining IAM roles (AWSCloudFormationStackSetAdministrationRole/ExecutionRole) in every account, which is significantly higher operational overhead than service-managed permissions with Organizations.</p>", "<p>Elastic Beanstalk is an application deployment platform for compute workloads, not a mechanism for provisioning standard resources across an AWS Organization's accounts.</p>", "<p>StackSets with service-managed permissions integrates directly with AWS Organizations, automatically deploying and updating stack instances in existing and new member accounts across specified Regions without manual role setup in each account.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A SysOps administrator manages a fleet of 500 EC2 instances running a mix of Amazon Linux 2, Windows Server, and Ubuntu. Security requires monthly OS patching on a defined schedule with a compliance report showing which instances are missing critical patches. Which AWS service should be used?", "prompt": {"question": "<p>A SysOps administrator manages a fleet of 500 EC2 instances running a mix of Amazon Linux 2, Windows Server, and Ubuntu. Security requires monthly OS patching on a defined schedule with a compliance report showing which instances are missing critical patches. Which AWS service should be used?</p>", "answers": ["<p>Amazon Inspector with a network reachability assessment</p>", "<p>AWS Config with a managed rule for encrypted-volumes</p>", "<p>Custom shell scripts executed manually over SSH to each instance</p>", "<p>AWS Systems Manager Patch Manager with a patch baseline and maintenance window</p>"], "feedbacks": ["<p>Amazon Inspector assesses vulnerabilities and network exposure but does not install patches or manage patch baselines/schedules.</p>", "<p>AWS Config's encrypted-volumes rule checks EBS encryption compliance and has nothing to do with OS patch management.</p>", "<p>Manual SSH scripting does not scale to 500 instances across three OS families and provides no centralized compliance reporting, failing the requirement.</p>", "<p>Patch Manager automates patch scanning and installation across multiple operating systems using patch baselines, and integrates with Maintenance Windows for scheduling plus patch compliance reporting in the Systems Manager console.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "An Elastic Beanstalk environment runs a production web application. The team requires zero downtime during deployments and wants the deployment to launch an entirely new set of instances, verify their health, and only then terminate the original instances, even though this temporarily doubles compute cost during the deployment. Which deployment policy should be configured?", "prompt": {"question": "<p>An Elastic Beanstalk environment runs a production web application. The team requires zero downtime during deployments and wants the deployment to launch an entirely new set of instances, verify their health, and only then terminate the original instances, even though this temporarily doubles compute cost during the deployment. Which deployment policy should be configured?</p>", "answers": ["<p>All at once</p>", "<p>Rolling with additional batch</p>", "<p>Immutable</p>", "<p>Rolling</p>"], "feedbacks": ["<p>All at once terminates and replaces instances simultaneously in-place, causing downtime and no safety verification before impact.</p>", "<p>Rolling with additional batch launches one extra batch to maintain capacity but updates instances within the same Auto Scaling group in batches, which is less isolated and less safe than a fully separate immutable deployment.</p>", "<p>Immutable deployments launch a full set of new instances in a temporary Auto Scaling group alongside the existing environment, run health checks, and only shift traffic and terminate old instances after the new set passes checks — providing zero downtime and the safest rollback at the cost of temporarily doubled capacity.</p>", "<p>Rolling updates instances in batches without launching an entirely new instance set first, so capacity is reduced during the update and it doesn't match the 'new set then terminate old' requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company wants to automatically build an updated, patched 'golden' AMI every night from a base Amazon Linux 2 image, without any manual console steps, and use it for future instance launches. Which approach BEST achieves this?", "prompt": {"question": "<p>A company wants to automatically build an updated, patched 'golden' AMI every night from a base Amazon Linux 2 image, without any manual console steps, and use it for future instance launches. Which approach BEST achieves this?</p>", "answers": ["<p>Manually launch an instance, install updates, and create an AMI from the EC2 console each night</p>", "<p>Use AWS Backup to take a nightly EBS snapshot and manually register it as an AMI</p>", "<p>Use AWS Systems Manager Automation with a runbook such as AWS-UpdateLinuxAmi, triggered nightly via a Maintenance Window or Amazon EventBridge rule</p>", "<p>Redeploy a CloudFormation stack nightly that references a hardcoded AMI ID</p>"], "feedbacks": ["<p>Manually creating the AMI each night requires human intervention every day, which fails the 'without any manual console steps' requirement.</p>", "<p>AWS Backup snapshots capture EBS volume data but do not automatically register a bootable AMI with the correct metadata; this still requires manual registration steps.</p>", "<p>Systems Manager Automation runbooks like AWS-UpdateLinuxAmi automate the full workflow of launching a source instance, applying updates, creating a new AMI, and terminating the temporary instance, and can be invoked on a schedule via Maintenance Windows or EventBridge — fully eliminating manual steps.</p>", "<p>Referencing a hardcoded, unchanging AMI ID in CloudFormation does not create a new patched AMI at all — it just redeploys the same stale image.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "Which statement correctly distinguishes an AWS CloudFormation change set from CloudFormation drift detection?", "prompt": {"question": "<p>Which statement correctly distinguishes an AWS CloudFormation change set from CloudFormation drift detection?</p>", "answers": ["<p>A change set previews the proposed changes to stack resources before an update is executed, while drift detection identifies whether the actual configuration of deployed resources has diverged from the stack's expected configuration</p>", "<p>Drift detection previews proposed changes before a stack update, while change sets identify out-of-band manual modifications made after deployment</p>", "<p>Both change sets and drift detection automatically revert resources to match the CloudFormation template</p>", "<p>Change sets are only available for CloudFormation StackSets, while drift detection is only available for individual, non-StackSet stacks</p>"], "feedbacks": ["<p>A change set is generated before you execute a stack update and shows exactly what will be added, modified, or replaced. Drift detection is run against an already-deployed stack to compare live resource state to the template, revealing manual out-of-band changes.</p>", "<p>This reverses the definitions — drift detection does not preview future updates, and change sets do not detect manual out-of-band changes.</p>", "<p>Neither feature automatically remediates or reverts resources; both are read-only/informational until a human takes action.</p>", "<p>Change sets work with both individual stacks and StackSets, and drift detection is also supported for StackSets (at the stack instance level), so this restriction is incorrect.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A SysOps team must ensure that every EC2 instance in a fleet continuously has the CloudWatch agent installed and its configuration file kept in sync with a centrally managed version, automatically remediating any instance found out of compliance, without requiring instances to be relaunched. Which Systems Manager capability should be used?", "prompt": {"question": "<p>A SysOps team must ensure that every EC2 instance in a fleet continuously has the CloudWatch agent installed and its configuration file kept in sync with a centrally managed version, automatically remediating any instance found out of compliance, without requiring instances to be relaunched. Which Systems Manager capability should be used?</p>", "answers": ["<p>Systems Manager Session Manager</p>", "<p>Systems Manager Inventory</p>", "<p>Systems Manager Parameter Store with a SecureString parameter</p>", "<p>Systems Manager State Manager with an association applied on a recurring schedule</p>"], "feedbacks": ["<p>Session Manager provides interactive shell access to instances; it does not enforce or maintain configuration state.</p>", "<p>Inventory collects metadata about installed software and configuration for visibility and reporting, but it does not remediate or enforce a desired state on its own.</p>", "<p>Parameter Store simply stores configuration values and secrets; it has no mechanism to detect drift or apply configuration to instances by itself.</p>", "<p>State Manager associations define a desired state (such as ensuring an agent is installed and configured) and apply it to targeted instances on a recurring schedule, automatically re-applying the configuration to bring non-compliant instances back into compliance without relaunching them.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A SysOps administrator manages an AWS CloudFormation stack that provisions an Auto Scaling group, a security group, and an RDS instance. Another engineer manually modified the security group rules directly in the console during an incident, bypassing CloudFormation. Before applying a planned template update, the administrator must identify exactly which resources and properties have diverged from the stack's defined configuration. Which action should the administrator take?", "prompt": {"question": "<p>A SysOps administrator manages an AWS CloudFormation stack that provisions an Auto Scaling group, a security group, and an RDS instance. Another engineer manually modified the security group rules directly in the console during an incident, bypassing CloudFormation. Before applying a planned template update, the administrator must identify exactly which resources and properties have diverged from the stack's defined configuration. Which action should the administrator take?</p>", "answers": ["<p>Run aws cloudformation detect-stack-drift on the stack and review the resulting stack and resource drift status</p>", "<p>Enable AWS Config and create a custom rule to compare the security group against a known-good configuration</p>", "<p>Delete and recreate the stack to guarantee the resources match the template exactly</p>", "<p>Create a change set against the stack and inspect the proposed resource modifications before executing it</p>"], "feedbacks": ["<p>CloudFormation drift detection is purpose-built to compare the actual configuration of stack resources against the stack's expected (template-defined) configuration and reports per-resource and per-property drift status (IN_SYNC, MODIFIED, DELETED). This is the direct mechanism for detecting out-of-band manual changes like the security group edit described.</p>", "<p>AWS Config can track configuration history and evaluate compliance rules, but it is not the native CloudFormation mechanism for detecting drift against a stack's template and requires significant custom rule-building to replicate this specific capability</p>", "<p>Deleting and recreating the stack is destructive, causes downtime for the RDS instance and Auto Scaling group, and is unnecessary just to detect what changed</p>", "<p>A change set only shows the difference between the current stack and a proposed template update — it does not detect or report drift caused by manual out-of-band changes to existing resources</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs EC2 instances tagged Environment=Production across multiple accounts. Security policy requires that patches classified as Critical be automatically approved for installation 3 days after release, applied only to instances with the Environment=Production tag, and installed during a recurring weekly maintenance window. Which combination of actions meets these requirements with the least operational overhead?", "prompt": {"question": "<p>A company runs EC2 instances tagged Environment=Production across multiple accounts. Security policy requires that patches classified as Critical be automatically approved for installation 3 days after release, applied only to instances with the Environment=Production tag, and installed during a recurring weekly maintenance window. Which combination of actions meets these requirements with the least operational overhead?</p>", "answers": ["<p>Use the Patch Manager AWS-provided default baseline as-is and schedule an EventBridge rule to invoke the AWS-RunPatchBaseline document nightly against all instances</p>", "<p>Create a custom Patch Manager patch baseline with an auto-approval rule for Critical severity patches with a 3-day approval delay, set it as the default baseline for the OS, create a Maintenance Window targeting instances by the Environment=Production tag, and register a Run Command task using the AWS-RunPatchBaseline document</p>", "<p>Create an AWS Config custom rule that invokes a Lambda function to SSH into tagged instances and run the OS package manager update command every night</p>", "<p>Use a Systems Manager Automation runbook (AWS-InstallWindowsUpdates) triggered by an EventBridge scheduled rule to install all available updates weekly</p>"], "feedbacks": ["<p>The AWS-provided default baseline does not support the specific 3-day/Critical-only auto-approval rule required, and it patches all applicable updates rather than following the custom approval policy</p>", "<p>A custom Patch Manager baseline lets you define auto-approval rules by severity (Critical) and approval delay (3 days), exactly matching the requirement. Combining this baseline with a Maintenance Window scoped to the Environment=Production tag and the AWS-RunPatchBaseline Run Command document is the standard, low-overhead Patch Manager pattern for scheduled, targeted, policy-driven patching.</p>", "<p>AWS Config is a configuration compliance and change-tracking service, not a patch deployment mechanism; using Lambda to SSH into instances nightly is high operational overhead, insecure, and does not use native patch approval or maintenance window scheduling</p>", "<p>AWS-InstallWindowsUpdates only applies to Windows instances, installs all available updates rather than honoring a severity-based auto-approval policy, and does not natively provide the 3-day approval delay or tag-based Maintenance Window targeting described</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has an application running on EC2 instances in Account A that needs to read objects from an S3 bucket in Account B. Which approach BEST grants this access following least privilege?", "prompt": {"question": "<p>A company has an application running on EC2 instances in Account A that needs to read objects from an S3 bucket in Account B. Which approach BEST grants this access following least privilege?</p>", "answers": ["<p>Create an IAM user in Account B, generate access keys, and store them in the EC2 instance's user data script</p>", "<p>Make the S3 bucket public and use a bucket policy to restrict access by source IP address</p>", "<p>Create an IAM role in Account B with a trust policy allowing Account A's EC2 instance role to assume it, then have the application assume the role using AWS STS</p>", "<p>Copy the IAM policy from Account A to a new IAM user in Account B and share the credentials via Secrets Manager</p>"], "feedbacks": ["<p>Hardcoding long-term access keys in user data is insecure, violates least privilege, and creates a credential rotation burden.</p>", "<p>Making the bucket public exposes data broadly; EC2 instance IPs are dynamic, making IP-based restriction unreliable and less secure than role-based access.</p>", "<p>A cross-account IAM role with a trust policy lets the Account A EC2 instance role assume temporary credentials via STS, providing least-privilege, time-limited access without any long-term credentials.</p>", "<p>Sharing IAM user credentials, even via Secrets Manager, still relies on long-term credentials rather than temporary STS tokens, and is more complex and less secure than assuming a role.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services company must encrypt data at rest in Amazon S3 using keys for which they fully control the rotation schedule (rotating manually every 90 days) and require a complete audit trail of every key usage event. Which KMS key type should they use?", "prompt": {"question": "<p>A financial services company must encrypt data at rest in Amazon S3 using keys for which they fully control the rotation schedule (rotating manually every 90 days) and require a complete audit trail of every key usage event. Which KMS key type should they use?</p>", "answers": ["<p>Customer managed keys (CMK) with imported key material and manual rotation</p>", "<p>AWS managed keys (aws/s3)</p>", "<p>S3 managed keys (SSE-S3)</p>", "<p>AWS owned keys</p>"], "feedbacks": ["<p>Customer managed CMKs with imported key material give the customer full control over the rotation schedule (rotation must be done manually by creating and swapping key material) and every use of the key is logged in AWS CloudTrail.</p>", "<p>AWS managed keys rotate automatically once per year on AWS's schedule, giving the customer no control over a custom 90-day cadence.</p>", "<p>SSE-S3 keys are fully managed by AWS with no customer control over rotation and no per-key CloudTrail visibility into key policy or usage.</p>", "<p>AWS owned keys are not visible in the customer's account at all, are shared across many AWS accounts, and provide no dedicated audit trail for that customer.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An S3 bucket has 'Block all public access' enabled at the bucket level, but a bucket policy grants s3:GetObject to principal '*' for public compliance document downloads. Public access is still denied. What is the correct action to allow public read access to these objects while keeping security best practices intact for the rest of the account?", "prompt": {"question": "<p>An S3 bucket has 'Block all public access' enabled at the bucket level, but a bucket policy grants s3:GetObject to principal '*' for public compliance document downloads. Public access is still denied. What is the correct action to allow public read access to these objects while keeping security best practices intact for the rest of the account?</p>", "answers": ["<p>On this specific bucket, disable only the two Block Public Access settings that block public and cross-account access granted through bucket or access point policies</p>", "<p>Disable 'Block all public access' at the account level</p>", "<p>Delete the bucket policy and use ACLs instead to grant public-read</p>", "<p>Attach an IAM policy to all IAM users that denies s3:GetObject except for this specific bucket</p>"], "feedbacks": ["<p>S3 Block Public Access has four independently configurable settings per bucket. Disabling only the two policy-related settings on this single bucket allows the existing bucket policy to grant public access while leaving ACL-based blocking and all other buckets/the account unaffected.</p>", "<p>Disabling Block Public Access at the account level affects every bucket in the account, far broader than required and against least privilege.</p>", "<p>ACLs are a legacy access-control mechanism that AWS recommends avoiding, and switching to ACLs doesn't address the fact that BPA is blocking the policy-based grant.</p>", "<p>IAM policies attached to IAM users don't affect anonymous/public access, and this approach doesn't address the Block Public Access setting causing the denial at all.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company uses Amazon RDS for MySQL and stores database credentials in AWS Secrets Manager. Compliance requires the password to be rotated every 30 days with zero application downtime and no manual intervention. Which configuration meets this requirement?", "prompt": {"question": "<p>A company uses Amazon RDS for MySQL and stores database credentials in AWS Secrets Manager. Compliance requires the password to be rotated every 30 days with zero application downtime and no manual intervention. Which configuration meets this requirement?</p>", "answers": ["<p>Manually update the secret value every 30 days using the AWS CLI and restart the RDS instance</p>", "<p>Store the password in an AWS Systems Manager Parameter Store SecureString parameter and update it manually every 30 days</p>", "<p>Enable automatic rotation with the single-user rotation strategy and manually restart the application after each rotation</p>", "<p>Enable automatic rotation on the secret with a 30-day schedule, using the AWS-provided Lambda rotation function for RDS MySQL with the alternating users rotation strategy</p>"], "feedbacks": ["<p>Manually updating the secret and restarting RDS is a manual process that also causes application downtime during the restart.</p>", "<p>Parameter Store does not provide built-in automatic rotation integration with RDS the way Secrets Manager does, and updating manually fails the 'no manual intervention' requirement.</p>", "<p>The single-user rotation strategy briefly invalidates the previous credential during the update, and requiring a manual application restart introduces both downtime and manual intervention.</p>", "<p>Secrets Manager's native automatic rotation with the AWS-provided RDS Lambda function using the alternating users strategy creates and validates a second database user during rotation, so the original credentials keep working until the switch completes, achieving zero downtime with no manual steps.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company wants to continuously monitor whether all Amazon EBS volumes are encrypted, automatically remediate any that are found non-compliant, and maintain a historical record of compliance status changes over time. Which AWS service should be used?", "prompt": {"question": "<p>A company wants to continuously monitor whether all Amazon EBS volumes are encrypted, automatically remediate any that are found non-compliant, and maintain a historical record of compliance status changes over time. Which AWS service should be used?</p>", "answers": ["<p>AWS Config with a managed rule and an associated remediation action</p>", "<p>Amazon GuardDuty with EBS protection enabled</p>", "<p>AWS Trusted Advisor security checks</p>", "<p>AWS CloudTrail with EventBridge rules triggering a Lambda function</p>"], "feedbacks": ["<p>AWS Config continuously evaluates resource configurations (such as EBS encryption status) against rules, maintains a historical compliance timeline, and can trigger automatic remediation using SSM Automation documents.</p>", "<p>GuardDuty is a threat detection service focused on malicious or anomalous activity, not on evaluating resource configuration compliance like encryption settings.</p>", "<p>Trusted Advisor provides periodic recommendations but does not maintain a continuous historical compliance timeline or offer configurable automated remediation actions tied to specific rules.</p>", "<p>CloudTrail records API activity, not resource configuration state; building a custom EventBridge/Lambda solution is possible but far more complex than Config's purpose-built compliance tracking and remediation.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "What is the PRIMARY difference between Amazon GuardDuty and AWS Security Hub?", "prompt": {"question": "<p>What is the PRIMARY difference between Amazon GuardDuty and AWS Security Hub?</p>", "answers": ["<p>GuardDuty aggregates findings from multiple security services and provides a single compliance score, while Security Hub is a threat detection service using machine learning</p>", "<p>GuardDuty is a threat detection service that analyzes sources like VPC Flow Logs, DNS logs, and CloudTrail for malicious activity, while Security Hub aggregates and prioritizes findings from GuardDuty and other security services into a single dashboard with compliance standards checks</p>", "<p>GuardDuty only works with AWS Organizations multi-account setups, while Security Hub only works with single standalone accounts</p>", "<p>GuardDuty is used for encryption key management, while Security Hub is used for identity and access management</p>"], "feedbacks": ["<p>This reverses the actual roles of the two services; GuardDuty does not provide a compliance score and Security Hub is not a threat-detection engine itself.</p>", "<p>GuardDuty detects threats by analyzing log sources for malicious or anomalous activity, while Security Hub aggregates findings from GuardDuty and other services (Inspector, Macie, third-party tools) into a centralized dashboard and runs compliance standard checks (e.g., CIS, PCI DSS).</p>", "<p>Both services support both single-account and AWS Organizations multi-account deployments; this distinction is fabricated.</p>", "<p>Neither service manages encryption keys or IAM; those functions belong to AWS KMS and AWS IAM respectively.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company stores database credentials for an Amazon RDS for MySQL instance and needs them automatically rotated every 30 days without any custom code, while application servers retrieve the credentials at runtime. Which solution BEST meets these requirements?", "prompt": {"question": "<p>A company stores database credentials for an Amazon RDS for MySQL instance and needs them automatically rotated every 30 days without any custom code, while application servers retrieve the credentials at runtime. Which solution BEST meets these requirements?</p>", "answers": ["<p>Store the credentials in AWS Secrets Manager and enable automatic rotation using the built-in Lambda rotation function for RDS with a 30-day rotation schedule</p>", "<p>Store the credentials as SecureString parameters in AWS Systems Manager Parameter Store and schedule an EventBridge rule to invoke a script that changes the password every 30 days</p>", "<p>Store the credentials in AWS Secrets Manager and enable an AWS Config rule to flag secrets older than 30 days for manual rotation</p>", "<p>Store the credentials in an encrypted Amazon S3 object using SSE-KMS and configure S3 Lifecycle rules to expire the object after 30 days</p>"], "feedbacks": ["<p>AWS Secrets Manager provides native, built-in Lambda rotation functions for RDS, Redshift, and DocumentDB that handle the entire rotation workflow (create new credentials, update the database, update the secret) on a defined schedule with zero custom rotation logic required.</p>", "<p>Parameter Store SecureString does not offer native automatic rotation — you would need to write and maintain custom Lambda code and scheduling logic yourself, increasing operational overhead.</p>", "<p>AWS Config can only detect and report non-compliant resources; it cannot rotate credentials, so this fails the 'automatic rotation' requirement and still requires manual intervention.</p>", "<p>S3 with Lifecycle rules can only expire (delete) objects on a schedule — it cannot generate new credentials, update the database password, or manage secret versions, making it unsuitable for credential rotation.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An application running on EC2 instances in a private subnet (no NAT Gateway, no internet access) needs to read and write objects to an S3 bucket in the same Region. The company wants to avoid any data transfer charges for NAT Gateway processing and keep traffic off the public internet. Which solution meets these requirements with the LOWEST cost?", "prompt": {"question": "<p>An application running on EC2 instances in a private subnet (no NAT Gateway, no internet access) needs to read and write objects to an S3 bucket in the same Region. The company wants to avoid any data transfer charges for NAT Gateway processing and keep traffic off the public internet. Which solution meets these requirements with the LOWEST cost?</p>", "answers": ["<p>Deploy a NAT Gateway in a public subnet and route S3 traffic through it</p>", "<p>Create an Interface VPC endpoint (AWS PrivateLink) for S3 in the private subnet</p>", "<p>Create a Gateway VPC endpoint for S3 and add a route in the private subnet's route table</p>", "<p>Set up VPC peering with a management VPC that has internet access, then route traffic through it</p>"], "feedbacks": ["<p>A NAT Gateway incurs hourly charges plus per-GB data processing fees, and still sends traffic out to the public S3 endpoint over the internet gateway path — more expensive and not private.</p>", "<p>Interface endpoints use PrivateLink ENIs that incur hourly charges per AZ plus data processing charges — S3 supports the free Gateway endpoint type, making the Interface endpoint an unnecessary cost.</p>", "<p>A Gateway VPC endpoint for S3 has no hourly or per-GB processing charge, works entirely within the AWS network, and is configured simply by adding a route table entry pointing to the endpoint's prefix list — the standard low-cost solution for private S3 access.</p>", "<p>VPC peering does not solve the underlying problem and adds complexity, latency, and another VPC to manage — it does not provide S3 access on its own.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs the same web application behind Application Load Balancers in us-east-1 and eu-west-1. They want Route 53 to send each user to whichever Region gives the fastest response time, and to automatically stop sending traffic to a Region if its ALB becomes unhealthy. Which Route 53 configuration meets these requirements?", "prompt": {"question": "<p>A company runs the same web application behind Application Load Balancers in us-east-1 and eu-west-1. They want Route 53 to send each user to whichever Region gives the fastest response time, and to automatically stop sending traffic to a Region if its ALB becomes unhealthy. Which Route 53 configuration meets these requirements?</p>", "answers": ["<p>Weighted routing policy with equal weights assigned to both ALB records</p>", "<p>Latency-based routing policy with a health check associated with each record</p>", "<p>Geolocation routing policy mapping continents to the nearest Region's ALB</p>", "<p>Simple routing policy with both ALB IP addresses returned in round-robin fashion</p>"], "feedbacks": ["<p>Weighted routing distributes traffic by a fixed ratio regardless of round-trip latency, so it does not route users to the fastest Region.</p>", "<p>Latency-based routing directs users to the Region with the lowest measured latency, and attaching a health check to each latency record lets Route 53 automatically exclude an unhealthy Region's record from answers, failing traffic over to the next-best-latency healthy Region.</p>", "<p>Geolocation routing maps users to a Region based on their geographic location, not measured network latency, so it can send a user to a farther but 'assigned' Region even if another Region is faster.</p>", "<p>Simple routing with round-robin has no latency awareness and no health-check-based failover — a client could still receive the IP of a downed Region.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services company needs a dedicated, low-latency, high-bandwidth connection between its data center and its AWS VPC for consistent network performance running mission-critical batch jobs. The design must also include a redundant path that keeps the environment reachable if the primary connection fails, at a reasonable cost. Which solution BEST meets these requirements?", "prompt": {"question": "<p>A financial services company needs a dedicated, low-latency, high-bandwidth connection between its data center and its AWS VPC for consistent network performance running mission-critical batch jobs. The design must also include a redundant path that keeps the environment reachable if the primary connection fails, at a reasonable cost. Which solution BEST meets these requirements?</p>", "answers": ["<p>Two independent Site-to-Site VPN connections over separate ISPs as the only connectivity</p>", "<p>VPC peering configured between the data center's simulated VPC and the production VPC</p>", "<p>A single Direct Connect connection with no backup, relying on the carrier's 99.9% uptime SLA</p>", "<p>AWS Direct Connect as the primary connection with a Site-to-Site VPN as a backup path</p>"], "feedbacks": ["<p>VPN-only connections traverse the public internet and cannot guarantee the consistent low latency and dedicated bandwidth the workload requires.</p>", "<p>VPC peering only connects VPC-to-VPC within AWS; it cannot be used to connect an on-premises data center to a VPC.</p>", "<p>A single Direct Connect connection with no backup is a single point of failure — Direct Connect does not carry an AWS SLA guarantee on its own without a resilient architecture, and the exam expects redundancy to be designed in.</p>", "<p>Direct Connect provides the dedicated, consistent, high-bandwidth, low-latency link required for the workload, and pairing it with a Site-to-Site VPN as a backup (using BGP failover) gives redundancy over the public internet at a much lower cost than a second Direct Connect circuit.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "An EC2 instance in a private subnet cannot be reached via SSH (port 22) from a bastion host in the same VPC. The security group on the private instance allows inbound TCP 22 from the bastion's security group, and the route tables are correctly configured between the subnets. The network ACL on the private subnet allows inbound TCP port 22 but has no explicit outbound rule permitting the ephemeral port range. What is the MOST likely cause of the failed connection?", "prompt": {"question": "<p>An EC2 instance in a private subnet cannot be reached via SSH (port 22) from a bastion host in the same VPC. The security group on the private instance allows inbound TCP 22 from the bastion's security group, and the route tables are correctly configured between the subnets. The network ACL on the private subnet allows inbound TCP port 22 but has no explicit outbound rule permitting the ephemeral port range. What is the MOST likely cause of the failed connection?</p>", "answers": ["<p>The security group is stateless and is blocking the SSH response packets</p>", "<p>The instance's local firewall (such as iptables) is blocking inbound connections</p>", "<p>The bastion host's security group does not allow outbound traffic on port 22</p>", "<p>The network ACL is stateless and the missing outbound rule for ephemeral ports (1024-65535) is blocking the return traffic</p>"], "feedbacks": ["<p>Security groups are stateful by design — if inbound traffic is allowed, the response is automatically allowed regardless of outbound rules, so this cannot be the cause.</p>", "<p>An OS-level firewall is possible in general, but the question gives specific NACL configuration details pointing directly to the ephemeral port issue, making this the more likely and intended answer.</p>", "<p>Outbound rules on the bastion's security group are irrelevant here because security groups are stateful, and the question states the bastion's SG only needs to allow the outbound SSH request, which is implied to already work — the failure described is on the return path, governed by the NACL.</p>", "<p>Network ACLs are stateless, so return traffic must be explicitly permitted by a separate rule. Allowing inbound port 22 is not enough — the subnet's NACL must also allow outbound traffic on the ephemeral port range used by the client (typically 1024-65535), or the response packets will be dropped.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company wants to serve private video content stored in an S3 bucket through Amazon CloudFront. The requirement is that the S3 bucket must NOT be publicly accessible, and only the specific CloudFront distribution should be able to retrieve objects from the bucket. Which configuration meets this requirement?", "prompt": {"question": "<p>A company wants to serve private video content stored in an S3 bucket through Amazon CloudFront. The requirement is that the S3 bucket must NOT be publicly accessible, and only the specific CloudFront distribution should be able to retrieve objects from the bucket. Which configuration meets this requirement?</p>", "answers": ["<p>Configure CloudFront with Origin Access Control (OAC) and update the S3 bucket policy to allow access only from that distribution</p>", "<p>Enable S3 static website hosting and make the bucket publicly readable</p>", "<p>Generate CloudFront signed URLs for clients while leaving the bucket policy set to allow public read access</p>", "<p>Use an S3 bucket policy that allows access from any AWS account's CloudFront distribution</p>"], "feedbacks": ["<p>Origin Access Control (OAC) is the current AWS-recommended method for CloudFront to securely access a private S3 origin; combined with a bucket policy that restricts access to that specific distribution's service principal and ARN, the bucket stays fully private while CloudFront can still fetch objects, including with SSE-KMS-encrypted objects.</p>", "<p>Static website hosting with a public bucket directly violates the requirement that the bucket must not be publicly accessible.</p>", "<p>Signed URLs control client access to CloudFront but do nothing to restrict who can access the S3 bucket directly — leaving the bucket publicly readable means anyone can bypass CloudFront and pull objects straight from S3.</p>", "<p>A policy allowing any CloudFront distribution (including ones outside the account) is overly permissive and does not restrict access to only the intended distribution.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A gaming company runs a UDP-based multiplayer game server deployed across Network Load Balancers in three AWS Regions. They need to route players to the closest healthy endpoint with the lowest possible latency, using static IP addresses that do not change, along with automatic failover away from an unhealthy Region. Which AWS service should they use?", "prompt": {"question": "<p>A gaming company runs a UDP-based multiplayer game server deployed across Network Load Balancers in three AWS Regions. They need to route players to the closest healthy endpoint with the lowest possible latency, using static IP addresses that do not change, along with automatic failover away from an unhealthy Region. Which AWS service should they use?</p>", "answers": ["<p>Amazon CloudFront</p>", "<p>Amazon Route 53 with latency-based routing</p>", "<p>AWS Global Accelerator</p>", "<p>An Application Load Balancer with cross-zone load balancing enabled</p>"], "feedbacks": ["<p>CloudFront is designed for HTTP/HTTPS content delivery and caching; it does not support arbitrary UDP traffic for game servers.</p>", "<p>Route 53 latency-based routing is DNS-based, so IP addresses returned can vary and are subject to client-side DNS caching/TTLs — it does not provide static anycast IPs and failover can be delayed by TTL expiration.</p>", "<p>AWS Global Accelerator supports both TCP and UDP traffic, provides two static anycast IP addresses that never change, and uses the AWS global network to route users to the closest healthy endpoint across Regions with automatic health-check-based failover — exactly matching the UDP and static-IP requirements.</p>", "<p>An Application Load Balancer operates at Layer 7 for HTTP/HTTPS only, does not support UDP, and does not provide cross-Region static IP routing on its own.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs a critical web application with a primary deployment in us-east-1 and a fully provisioned standby deployment in us-west-2. The SysOps administrator must configure Amazon Route 53 so that DNS queries are automatically directed to the standby deployment only when the primary deployment becomes unhealthy, with no manual intervention required. Which configuration BEST meets this requirement?", "prompt": {"question": "<p>A company runs a critical web application with a primary deployment in us-east-1 and a fully provisioned standby deployment in us-west-2. The SysOps administrator must configure Amazon Route 53 so that DNS queries are automatically directed to the standby deployment only when the primary deployment becomes unhealthy, with no manual intervention required. Which configuration BEST meets this requirement?</p>", "answers": ["<p>Configure a weighted routing policy with a 100/0 weight split between the primary and secondary records</p>", "<p>Configure a latency-based routing policy pointing to both the primary and secondary endpoints</p>", "<p>Configure a failover routing policy with a Route 53 health check attached to the primary record</p>", "<p>Configure a simple routing policy using only the primary record, and update it manually during an outage</p>"], "feedbacks": ["<p>A 100/0 weighted split does not automatically shift traffic on health failure unless combined with health checks and even then it is not the designed mechanism for primary/secondary failover; weights must typically be adjusted manually to fully redirect traffic.</p>", "<p>Latency-based routing selects the record with the lowest latency to the requester; it is designed for performance optimization across active regions, not for detecting an unhealthy primary and failing over to a standby.</p>", "<p>Route 53 failover routing policy is purpose-built for active-passive DR: it uses health checks on the primary record to detect failure and automatically returns the secondary record's endpoint when the primary is unhealthy, with zero manual steps.</p>", "<p>A simple routing policy with manual updates during an outage requires human intervention and does not satisfy the 'no manual intervention required' requirement, and it does not use health checks at all.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "EC2 instances running in a private subnet with no internet gateway or NAT gateway attached need to read and write objects in Amazon S3 without any traffic traversing the public internet. The solution must avoid ongoing hourly charges for the connectivity mechanism itself. Which solution BEST meets these requirements?", "prompt": {"question": "<p>EC2 instances running in a private subnet with no internet gateway or NAT gateway attached need to read and write objects in Amazon S3 without any traffic traversing the public internet. The solution must avoid ongoing hourly charges for the connectivity mechanism itself. Which solution BEST meets these requirements?</p>", "answers": ["<p>Create an Interface VPC endpoint for Amazon S3 using AWS PrivateLink</p>", "<p>Create a Gateway VPC endpoint for Amazon S3 and add a route to it in the private subnet's route table</p>", "<p>Deploy a NAT Gateway in a public subnet and route all S3 traffic through it</p>", "<p>Establish an AWS Direct Connect connection to the nearest AWS Direct Connect location</p>"], "feedbacks": ["<p>An Interface VPC endpoint (PrivateLink) also keeps traffic off the public internet but incurs an hourly charge per AZ plus data processing charges, which is unnecessary for S3 when a free Gateway endpoint is available.</p>", "<p>A Gateway VPC endpoint supports Amazon S3 and Amazon DynamoDB, keeps traffic entirely on the AWS network, requires only a route table entry to configure, and incurs no hourly or per-GB charge, making it the most cost-effective private connectivity option for S3.</p>", "<p>A NAT Gateway routes traffic out to the internet (S3's public endpoint) and incurs hourly plus data processing charges, and it does not keep traffic strictly on the AWS private network the way a VPC endpoint does.</p>", "<p>AWS Direct Connect is a hybrid connectivity solution linking on-premises networks to AWS; it is unrelated to enabling private-subnet-to-S3 connectivity within a single VPC and involves significant cost and setup overhead for this use case.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs a fault-tolerant, flexible batch data processing job on EC2 that can be interrupted and restarted at any point without data loss. The job runs for approximately 10 hours per day, and there is no requirement for guaranteed capacity. The company wants to minimize compute costs. Which purchasing option is MOST cost-effective for this workload?", "prompt": {"question": "<p>A company runs a fault-tolerant, flexible batch data processing job on EC2 that can be interrupted and restarted at any point without data loss. The job runs for approximately 10 hours per day, and there is no requirement for guaranteed capacity. The company wants to minimize compute costs. Which purchasing option is MOST cost-effective for this workload?</p>", "answers": ["<p>On-Demand Instances</p>", "<p>Spot Instances</p>", "<p>Standard Reserved Instances with a 1-year term</p>", "<p>Compute Savings Plans with a 3-year term</p>"], "feedbacks": ["<p>On-Demand Instances carry no discount and are the most expensive option for this workload.</p>", "<p>Spot Instances offer discounts of up to 90% off On-Demand pricing and are ideal for fault-tolerant, interruptible workloads like this batch job, which can tolerate interruption and restart.</p>", "<p>Standard Reserved Instances require a 1-year commitment and are best suited for steady-state, predictable usage; they offer a smaller discount than Spot and don't fit an interruptible, non-continuous workload.</p>", "<p>Compute Savings Plans require a consistent hourly spend commitment over 1 or 3 years and offer less discount than Spot Instances; they are better suited to predictable, continuous compute usage rather than an interruptible batch job.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company stores compliance log archives that must be retained for 7 years. The logs are almost never accessed after the first 30 days, but a few times per year auditors request retrieval, and the company must be able to retrieve the requested files within 12 hours. Which S3 storage configuration meets these requirements at the LOWEST cost?", "prompt": {"question": "<p>A company stores compliance log archives that must be retained for 7 years. The logs are almost never accessed after the first 30 days, but a few times per year auditors request retrieval, and the company must be able to retrieve the requested files within 12 hours. Which S3 storage configuration meets these requirements at the LOWEST cost?</p>", "answers": ["<p>Store in S3 Standard for 30 days, then transition to S3 Glacier Flexible Retrieval via a lifecycle policy</p>", "<p>Store in S3 Standard for 30 days, then transition to S3 Glacier Deep Archive via a lifecycle policy</p>", "<p>Store in S3 Standard-IA for the entire 7 years</p>", "<p>Store in S3 One Zone-IA for the entire 7 years</p>"], "feedbacks": ["<p>S3 Glacier Flexible Retrieval meets the retrieval time requirement (3-5 hours standard) but costs more per GB than Deep Archive, making it unnecessary given the 12-hour window is acceptable.</p>", "<p>S3 Glacier Deep Archive is the lowest-cost storage class (about $0.00099/GB-month) and its standard retrieval tier completes within 12 hours, exactly meeting the stated retrieval requirement at the lowest possible cost for 7-year retention.</p>", "<p>S3 Standard-IA has no long-term archival discount and costs significantly more per GB than Glacier storage classes for data retained 7 years with rare access.</p>", "<p>S3 One Zone-IA stores data in a single Availability Zone, reducing durability guarantees, which is inappropriate for compliance records, and it still costs more than Glacier Deep Archive.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A SysOps administrator wants automated, prioritized EC2 right-sizing recommendations, including specific recommended instance types, based on utilization metrics collected over the past 14 days. Which AWS service should the administrator use?", "prompt": {"question": "<p>A SysOps administrator wants automated, prioritized EC2 right-sizing recommendations, including specific recommended instance types, based on utilization metrics collected over the past 14 days. Which AWS service should the administrator use?</p>", "answers": ["<p>AWS Trusted Advisor</p>", "<p>AWS Compute Optimizer</p>", "<p>AWS Cost and Usage Report</p>", "<p>Amazon Cost Explorer</p>"], "feedbacks": ["<p>Trusted Advisor provides basic low-utilization EC2 checks (available with Business/Enterprise support) but does not provide detailed ML-based instance type recommendations like Compute Optimizer.</p>", "<p>AWS Compute Optimizer uses machine learning to analyze CloudWatch utilization metrics (with a default 14-day lookback period) and provides specific, prioritized instance type right-sizing recommendations for EC2, EBS, Lambda, and Auto Scaling groups.</p>", "<p>The Cost and Usage Report is a raw, detailed billing data export used for custom cost analysis; it does not generate right-sizing recommendations on its own.</p>", "<p>Cost Explorer's rightsizing feature focuses primarily on cost-based EC2 recommendations for Reserved Instance/Savings Plans purchasing, not the detailed ML-driven utilization analysis across compute services that Compute Optimizer provides.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company applied tags such as 'Department' and 'Project' to its EC2, RDS, and S3 resources to track costs, but the tags do not appear as filterable dimensions in Cost Explorer or in the Cost and Usage Report. What should the administrator do to resolve this?", "prompt": {"question": "<p>A company applied tags such as 'Department' and 'Project' to its EC2, RDS, and S3 resources to track costs, but the tags do not appear as filterable dimensions in Cost Explorer or in the Cost and Usage Report. What should the administrator do to resolve this?</p>", "answers": ["<p>Recreate the resources with the tags applied at launch time</p>", "<p>Enable AWS Config to track the tags</p>", "<p>Activate the tags as cost allocation tags in the Billing and Cost Management console</p>", "<p>Enable Cost Explorer in the Billing and Cost Management console</p>"], "feedbacks": ["<p>Resources do not need to be recreated; tag activation is a billing console setting applied after tags already exist.</p>", "<p>AWS Config tracks resource configuration compliance and change history, not cost allocation or billing dimensions.</p>", "<p>User-defined tags must be explicitly activated as cost allocation tags in the Billing and Cost Management console before they appear as filterable/groupable dimensions in Cost Explorer and the Cost and Usage Report; activation can take up to 24 hours to take effect.</p>", "<p>Enabling Cost Explorer allows access to cost analysis but does not by itself make existing tags filterable; tag activation is a separate required step.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "Which statement correctly differentiates AWS Reserved Instances (RIs) from Savings Plans?", "prompt": {"question": "<p>Which statement correctly differentiates AWS Reserved Instances (RIs) from Savings Plans?</p>", "answers": ["<p>Reserved Instances can be applied to AWS Lambda and Fargate usage, while Savings Plans apply only to EC2</p>", "<p>Both RIs and Savings Plans require identical upfront payment options and provide identical discount percentages</p>", "<p>Reserved Instances offer discounts on EC2 usage regardless of instance family or region, while Savings Plans apply only to a specific instance type</p>", "<p>Savings Plans commit to a consistent amount of compute usage measured in dollars per hour, offering flexibility to change instance family, size, OS, and region for Compute Savings Plans, while Standard RIs are tied to a specific instance family and region</p>"], "feedbacks": ["<p>This is reversed — it is Savings Plans (Compute Savings Plans specifically), not Reserved Instances, that can apply to Lambda and Fargate usage in addition to EC2.</p>", "<p>Payment options are similar (all upfront, partial upfront, no upfront) between RIs and Savings Plans, but discount percentages and flexibility differ significantly between RI types and Savings Plan types, so they are not identical.</p>", "<p>This is reversed — Standard RIs are tied to a specific instance family and region, while Compute Savings Plans are the flexible option that can span instance families and regions.</p>", "<p>Compute Savings Plans commit to a dollar-per-hour spend and apply flexibly across instance family, size, OS, tenancy, and region (and even to Fargate/Lambda), whereas Standard Reserved Instances are locked to a specific instance family and region (with limited size flexibility within the same family).</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}]}, {"name": "SOA-C02 Practice Test 2", "cid": 7305503, "duration": 130, "pass_percent": 72, "questions": [{"assessment_type": "multiple-choice", "question_plain": "A SysOps administrator wants to create a CloudWatch alarm that automatically adapts to the normal traffic pattern of an application and triggers only when metric values fall outside an expected range that accounts for time-of-day and day-of-week seasonality. Which alarm configuration should the administrator use?", "prompt": {"question": "<p>A SysOps administrator wants to create a CloudWatch alarm that automatically adapts to the normal traffic pattern of an application and triggers only when metric values fall outside an expected range that accounts for time-of-day and day-of-week seasonality. Which alarm configuration should the administrator use?</p>", "answers": ["<p>Create a static threshold alarm using the metric's average statistic with a period of 300 seconds</p>", "<p>Create a composite alarm that combines two static threshold alarms using AND logic</p>", "<p>Create an alarm based on the ANOMALY_DETECTION_BAND metric math expression, and set the alarm condition to trigger when the metric is 'Outside the band'</p>", "<p>Enable the AWS Config configuration recorder and use metric filters to detect anomalies</p>"], "feedbacks": ["<p>A static threshold does not adjust for seasonal or time-of-day traffic patterns, causing false alarms during expected peaks and troughs.</p>", "<p>Composite alarms combine the ALARM/OK/INSUFFICIENT_DATA states of existing alarms; they do not perform anomaly detection themselves.</p>", "<p>ANOMALY_DETECTION_BAND(m1, stdev) is a CloudWatch metric math function that builds a machine-learning-derived expected range accounting for hourly, daily, and weekly seasonality; the alarm is then configured to trigger when the metric value is outside that band.</p>", "<p>AWS Config records resource configuration state and metric filters extract numeric values from log data — neither performs statistical anomaly detection on a metric's time series.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization must ensure the CloudWatch agent is installed and running with a specific configuration on every EC2 instance in a large fleet, including instances launched in the future, with compliance checked and enforced every 30 minutes without any manual intervention. Which Systems Manager capability should be used?", "prompt": {"question": "<p>An organization must ensure the CloudWatch agent is installed and running with a specific configuration on every EC2 instance in a large fleet, including instances launched in the future, with compliance checked and enforced every 30 minutes without any manual intervention. Which Systems Manager capability should be used?</p>", "answers": ["<p>AWS Systems Manager State Manager association targeting instances by tag, with a rate(30 minutes) schedule expression for continuous compliance enforcement</p>", "<p>AWS Systems Manager Run Command, executed manually whenever a new instance launches</p>", "<p>AWS Systems Manager Automation runbook triggered by an EventBridge scheduled rule every 30 minutes</p>", "<p>An AWS Config conformance pack with a periodic rule evaluation frequency of 30 minutes</p>"], "feedbacks": ["<p>State Manager associations are purpose-built for continuous, fleet-wide state enforcement: they target instances by tag (so newly launched matching instances are automatically included), run on a defined schedule such as rate(30 minutes), and re-apply the desired configuration without manual steps.</p>", "<p>Manual execution of Run Command contradicts the 'without manual intervention' requirement and does not automatically cover future instances.</p>", "<p>Automation runbooks are designed for one-time or triggered procedural workflows (e.g., a remediation action), not for continuously enforcing configuration state across an entire fleet — using EventBridge to schedule it duplicates functionality State Manager already provides natively.</p>", "<p>AWS Config evaluates and reports on resource configuration compliance; it does not install or configure agent software on instances by itself.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A SysOps administrator configures an AWS Config rule named s3-bucket-versioning-enabled to detect S3 buckets without versioning enabled. Non-compliant buckets must be automatically remediated using the AWS-ConfigureS3BucketVersioning SSM Automation document, with up to 3 attempts spaced 60 seconds apart if an attempt fails. Which remediation configuration satisfies this requirement?", "prompt": {"question": "<p>A SysOps administrator configures an AWS Config rule named s3-bucket-versioning-enabled to detect S3 buckets without versioning enabled. Non-compliant buckets must be automatically remediated using the AWS-ConfigureS3BucketVersioning SSM Automation document, with up to 3 attempts spaced 60 seconds apart if an attempt fails. Which remediation configuration satisfies this requirement?</p>", "answers": ["<p>Leave Automatic remediation disabled, and manually run the SSM document from the AWS Config console whenever a bucket is found non-compliant</p>", "<p>Enable Automatic remediation on the remediation action, set MaximumAutomaticAttempts to 3, and set RetryAttemptSeconds to 60</p>", "<p>Create an EventBridge rule matching AWS Config compliance-change events that invokes a Lambda function to run the SSM document once, with no built-in retry logic</p>", "<p>Set MaximumAutomaticAttempts to 1 and rely on the SSM document's internal loop to retry three times every 60 seconds</p>"], "feedbacks": ["<p>Manual execution directly contradicts the requirement for automatic remediation.</p>", "<p>AWS Config remediation configurations natively support Automatic remediation with the parameters MaximumAutomaticAttempts (number of retry attempts) and RetryAttemptSeconds (delay between attempts), fully satisfying the requirement without extra custom logic.</p>", "<p>Building a custom EventBridge-to-Lambda pipeline reimplements functionality AWS Config remediation configurations already provide natively, adding unnecessary complexity and losing built-in retry semantics.</p>", "<p>The AWS-ConfigureS3BucketVersioning document has no internal retry loop; retry behavior must be configured through the Config remediation configuration's MaximumAutomaticAttempts and RetryAttemptSeconds, which should be set to 3 and 60 respectively, not 1.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An application writes structured JSON log entries to CloudWatch Logs containing fields @timestamp, statusCode, and latencyMs. A SysOps administrator needs a CloudWatch Logs Insights query that counts requests grouped by statusCode, only for requests where latencyMs is greater than 1000, sorted by count in descending order. Which query accomplishes this?", "prompt": {"question": "<p>An application writes structured JSON log entries to CloudWatch Logs containing fields @timestamp, statusCode, and latencyMs. A SysOps administrator needs a CloudWatch Logs Insights query that counts requests grouped by statusCode, only for requests where latencyMs is greater than 1000, sorted by count in descending order. Which query accomplishes this?</p>", "answers": ["<p>fields statusCode\\n| stats avg(latencyMs) by statusCode\\n| filter latencyMs &gt; 1000</p>", "<p>fields statusCode, latencyMs\\n| filter latencyMs &gt; 1000\\n| stats count(*) by statusCode\\n| sort count(*) desc</p>", "<p>fields @timestamp, statusCode\\n| filter latencyMs &gt; 1000\\n| stats sum(statusCode)\\n| sort desc</p>", "<p>parse @message \"statusCode\"\\n| filter latencyMs &gt; 1000\\n| group by statusCode\\n| order by count desc</p>"], "feedbacks": ["<p>Applying filter after an aggregation (avg by statusCode) is invalid because latencyMs is no longer a raw per-record field at that point, and the query never counts requests.</p>", "<p>Logs Insights syntax applies filter before aggregation, then uses stats count(*) by &lt;field&gt; to group counts, followed by sort &lt;function&gt; desc to order results — exactly matching the requirement to filter by latency, group by statusCode, and sort by count descending.</p>", "<p>sum(statusCode) is meaningless since statusCode is a categorical value, not something to be summed, and the query does not group results by statusCode at all.</p>", "<p>\"group by\" and \"order by\" are not valid Logs Insights commands (the correct commands are \"stats ... by\" and \"sort\"), and parse requires a glob pattern with '*' to actually extract a field value.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A monitoring team manages an application with two CloudWatch alarms: one for high CPU utilization and one for high application error rate. Both alarms trigger frequently during expected traffic spikes even though the application remains healthy, causing alarm fatigue. The team wants a single alarm that enters ALARM state only when BOTH the CPU and error-rate conditions are true at the same time. What should they implement?", "prompt": {"question": "<p>A monitoring team manages an application with two CloudWatch alarms: one for high CPU utilization and one for high application error rate. Both alarms trigger frequently during expected traffic spikes even though the application remains healthy, causing alarm fatigue. The team wants a single alarm that enters ALARM state only when BOTH the CPU and error-rate conditions are true at the same time. What should they implement?</p>", "answers": ["<p>Increase the number of evaluation periods on both existing alarms to reduce sensitivity</p>", "<p>Combine both metrics into a single metric math expression using the SUM function and alarm on the combined value</p>", "<p>Create a composite alarm with an AlarmRule expression such as ALARM(cpu-alarm) AND ALARM(error-alarm)</p>", "<p>Enable CloudWatch anomaly detection independently on both metrics and turn on alarm action suppression</p>"], "feedbacks": ["<p>Increasing evaluation periods only changes each alarm's individual sensitivity to sustained values; it does not correlate the two separate conditions together.</p>", "<p>SUM combines CPU utilization and error rate into one number, but these metrics have different units and semantics, so a summed value loses the meaning of 'both conditions true' and produces unreliable thresholds.</p>", "<p>Composite alarms use a boolean AlarmRule expression that references the states of other alarms (ALARM(), OK(), INSUFFICIENT_DATA()); combining two alarms with AND logic means the composite alarm only enters ALARM state when both underlying conditions are true simultaneously, directly addressing the noise-reduction goal.</p>", "<p>Anomaly detection changes how each alarm's threshold is derived but does not logically combine two alarms, and alarm action suppression alone (used to mute an alarm during a maintenance window based on another alarm) does not create the requested AND condition.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company wants to automatically remediate EC2 instances that transition to a 'stopped' state unexpectedly (excluding scheduled maintenance stops on instances tagged Maintenance=true) by invoking a Lambda function that restarts the instance and sends a notification. Which EventBridge-based approach correctly identifies only the unexpected stop events?", "prompt": {"question": "<p>A company wants to automatically remediate EC2 instances that transition to a 'stopped' state unexpectedly (excluding scheduled maintenance stops on instances tagged Maintenance=true) by invoking a Lambda function that restarts the instance and sends a notification. Which EventBridge-based approach correctly identifies only the unexpected stop events?</p>", "answers": ["<p>Create a rule with source aws.ec2 and detail-type 'EC2 Instance State-change Notification' matching detail.state = 'stopped'; have the Lambda function query the EC2 DescribeTags API and exit without action if the Maintenance=true tag is present</p>", "<p>Create a rule with source aws.ec2 and detail-type 'EC2 Instance State-change Notification' matching detail.state = 'stopped', and use an input transformer to filter based on the instance's tags before invoking Lambda</p>", "<p>Create a rule with detail-type 'EC2 Instance State-change Notification' whose event pattern references detail.state and the instance's resource tags directly, since state-change notifications include a full tag list</p>", "<p>Create a CloudTrail-based EventBridge rule matching only eventName 'StopInstances', since CloudTrail always includes full resource tags for direct pattern matching, and this reliably captures every stop scenario</p>"], "feedbacks": ["<p>EC2 Instance State-change Notification events do not include resource tag data in the event detail, so tag-based filtering cannot be done through EventBridge pattern matching alone. The Lambda function must call the EC2 API (e.g., DescribeTags) at invocation time to check for the Maintenance tag and decide whether to act — this is the standard and correct pattern.</p>", "<p>An input transformer only reshapes fields already present in the incoming event to build the target's input; it cannot query external data such as tags that aren't included in the event payload.</p>", "<p>State-change notification events do not include a tag list in their detail field, so this option is factually incorrect and the pattern would never match as described.</p>", "<p>Matching solely on the StopInstances API call misses instances that stop due to internal/OS-level shutdown or other non-API causes, so it would fail to catch all 'unexpected stop' scenarios; CloudTrail management events also do not reliably embed full resource tags for direct EventBridge pattern matching.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A monitoring team manages 40 CloudWatch alarms on a fleet of EC2 instances that back a payment-processing service. Every Saturday from 01:00-03:00 UTC, a maintenance job intentionally stops and restarts services, causing several alarms to transition to ALARM and page the on-call engineer. The team wants notifications suppressed only during the maintenance window, wants the underlying alarms to keep evaluating and recording state history for later review, and wants this to work automatically every week without manual scripting before and after each window. Which approach BEST meets these requirements?", "prompt": {"question": "<p>A monitoring team manages 40 CloudWatch alarms on a fleet of EC2 instances that back a payment-processing service. Every Saturday from 01:00-03:00 UTC, a maintenance job intentionally stops and restarts services, causing several alarms to transition to ALARM and page the on-call engineer. The team wants notifications suppressed only during the maintenance window, wants the underlying alarms to keep evaluating and recording state history for later review, and wants this to work automatically every week without manual scripting before and after each window. Which approach BEST meets these requirements?</p>", "answers": ["<p>Create an EventBridge scheduled rule that invokes a Lambda function to call disable-alarm-actions on all 40 alarms at 01:00 UTC and enable-alarm-actions at 03:00 UTC every Saturday</p>", "<p>Set the underlying alarms' 'treat missing data' setting to 'as good' during the maintenance window so the alarm reports OK instead of ALARM</p>", "<p>Delete the SNS topic subscription for the on-call engineer at the start of the maintenance window and recreate it at the end using an AWS Config rule</p>", "<p>Create a CloudWatch composite alarm whose alarm rule is ALARM(underlying-alarm) AND NOT ALARM(scheduled-maintenance-alarm), where the maintenance alarm is driven by a metric that is intentionally in ALARM during the window, and attach the SNS notification action only to the composite alarm</p>"], "feedbacks": ["<p>This requires building and maintaining custom Lambda automation on a schedule, adds operational overhead, and risks alarms staying disabled if the re-enable step fails, which the question explicitly wants to avoid</p>", "<p>Changing 'treat missing data' affects how missing datapoints are treated, not how existing breaching datapoints are evaluated, and it does not suppress notifications only during a specific window without additional automation</p>", "<p>Deleting and recreating SNS subscriptions is disruptive, loses the ability to review alarm state cleanly, and using an AWS Config rule for this purpose is not its intended function—Config evaluates resource compliance, not alarm notification lifecycle</p>", "<p>A composite alarm using an AlarmRule with AND NOT logic against a maintenance-window alarm automatically suppresses the notification action only when the maintenance alarm is in ALARM state, while the underlying alarms continue to evaluate independently and retain full state history in CloudWatch. This requires no per-week manual intervention once configured.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A SysOps administrator enabled VPC Flow Logs to a CloudWatch Logs log group named /vpc/flowlogs. Security wants a CloudWatch Logs Insights query that returns the top 10 source IP addresses generating the highest count of REJECTED traffic in the last 24 hours. Which query is correct?", "prompt": {"question": "<p>A SysOps administrator enabled VPC Flow Logs to a CloudWatch Logs log group named /vpc/flowlogs. Security wants a CloudWatch Logs Insights query that returns the top 10 source IP addresses generating the highest count of REJECTED traffic in the last 24 hours. Which query is correct?</p>", "answers": ["<p>fields srcAddr | filter action == REJECT | stats sum(srcAddr) as rejectCount | sort rejectCount desc | limit 10</p>", "<p>parse @message '* REJECT *' as srcAddr | stats count(srcAddr) | order by count desc | top 10</p>", "<p>fields srcAddr, action | filter action = 'REJECT' | stats count(*) as rejectCount by srcAddr | sort rejectCount desc | limit 10</p>", "<p>fields srcAddr, action | where action = 'REJECT' | group by srcAddr | count() as rejectCount | limit 10</p>"], "feedbacks": ["<p>'action == REJECT' is invalid syntax (Logs Insights uses '=' for equality and requires the literal to be quoted), and sum(srcAddr) is meaningless since srcAddr is a string field, not a numeric value</p>", "<p>'order by' and 'top' are not valid Logs Insights commands; Logs Insights uses 'sort' and 'limit'</p>", "<p>Logs Insights syntax requires 'filter' (not SQL-style 'where'), string literals must be quoted, 'stats count(*) as alias by field' is the correct aggregation form, and 'sort ... desc | limit 10' correctly returns the top 10 results.</p>", "<p>'group by' and a standalone 'count()' line without 'stats' are not valid Logs Insights syntax; aggregation must be expressed through the 'stats' command</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "An AWS Config rule named s3-bucket-public-read-prohibited flags an S3 bucket as NON_COMPLIANT after a developer accidentally applies a public-read ACL. The company wants automatic remediation using the AWS-DisableS3BucketPublicReadWrite SSM Automation document, but wants to avoid remediating on a single transient false positive: the remediation should only execute automatically after the resource has been evaluated as non-compliant twice, waiting 60 seconds between attempts, and it must run using an IAM role with least-privilege permissions rather than the Config service-linked role. Which remediation configuration approach satisfies this requirement?", "prompt": {"question": "<p>An AWS Config rule named s3-bucket-public-read-prohibited flags an S3 bucket as NON_COMPLIANT after a developer accidentally applies a public-read ACL. The company wants automatic remediation using the AWS-DisableS3BucketPublicReadWrite SSM Automation document, but wants to avoid remediating on a single transient false positive: the remediation should only execute automatically after the resource has been evaluated as non-compliant twice, waiting 60 seconds between attempts, and it must run using an IAM role with least-privilege permissions rather than the Config service-linked role. Which remediation configuration approach satisfies this requirement?</p>", "answers": ["<p>Create a remediation configuration for the Config rule specifying the AWS-DisableS3BucketPublicReadWrite document, Automatic=true, MaximumAutomaticAttempts=2, RetryAttemptSeconds=60, and a custom IAM execution role passed via the Parameters and ExecutionControls settings</p>", "<p>Enable AWS Config managed remediation with Automatic remediation set to Off, and require a human to manually trigger the SSM document from the Config console each time</p>", "<p>Attach an SNS notification to the Config rule and configure an EventBridge rule that retries the Lambda-based remediation indefinitely until compliance is achieved</p>", "<p>Set the Config rule's MaximumExecutionFrequency to 2 hours so the rule only evaluates twice a day, reducing the chance of remediating a transient issue</p>"], "feedbacks": ["<p>AWS Config remediation configurations natively support Automatic=true with MaximumAutomaticAttempts and RetryAttemptSeconds to control retry behavior, and allow specifying a custom IAM role for the SSM Automation execution instead of relying on the default Config role, exactly matching the stated requirements.</p>", "<p>Manual remediation defeats the requirement for automatic remediation after repeated non-compliance and adds unnecessary operational overhead</p>", "<p>There is no requirement or supported pattern to build a separate Lambda/EventBridge retry loop when native Config remediation retry settings already provide this capability, and 'indefinitely' contradicts the requirement for a bounded number of attempts</p>", "<p>MaximumExecutionFrequency controls how often periodic Config rules re-evaluate resources, not the remediation retry attempt count or the IAM role used for the SSM document; it does not address the stated requirement</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services company runs an RDS for PostgreSQL primary database in us-east-1. Leadership requires that a single-AZ hardware or network failure be resolved automatically with minimal downtime, and that a full regional disaster be recoverable with an RPO of 5 minutes by promoting a copy in eu-west-1. Which design meets BOTH requirements?", "prompt": {"question": "<p>A financial services company runs an RDS for PostgreSQL primary database in us-east-1. Leadership requires that a single-AZ hardware or network failure be resolved automatically with minimal downtime, and that a full regional disaster be recoverable with an RPO of 5 minutes by promoting a copy in eu-west-1. Which design meets BOTH requirements?</p>", "answers": ["<p>Deploy RDS Multi-AZ only, relying on automatic failover to the standby in the same region for all DR requirements</p>", "<p>Deploy RDS Multi-AZ within the primary region for automatic AZ failover, combined with a cross-region read replica that is promoted manually during a full regional outage</p>", "<p>Deploy a Read Replica in the secondary region only, promoting it manually during any outage, including single-AZ failures</p>", "<p>Take manual DB snapshots every 5 minutes and copy them to the secondary region for both AZ-level and regional failover</p>"], "feedbacks": ["<p>Multi-AZ's standby exists only in the same region, so it provides no protection at all if the entire region becomes unavailable.</p>", "<p>Multi-AZ provides automatic failover to a synchronous standby within the same region in roughly 60-120 seconds, satisfying the AZ-failure requirement, while a cross-region read replica typically lags by seconds to a few minutes and can be manually promoted to meet a 5-minute RPO during a full regional disaster.</p>", "<p>A cross-region read replica requires manual promotion for any failure, including routine single-AZ issues, which does not deliver fast automatic failover for local hardware faults.</p>", "<p>Manual snapshot creation and cross-region copy every 5 minutes is operationally unreliable, offers no automatic failover, and copy propagation delay commonly exceeds the stated RPO window.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An Auto Scaling group launches new EC2 instances behind an ALB target group. Application initialization via user data takes 8 minutes before the instance can pass the target group's health check (interval 30 seconds, unhealthy threshold 2). New instances are being terminated and replaced by the Auto Scaling group before initialization finishes. Which single change resolves this?", "prompt": {"question": "<p>An Auto Scaling group launches new EC2 instances behind an ALB target group. Application initialization via user data takes 8 minutes before the instance can pass the target group's health check (interval 30 seconds, unhealthy threshold 2). New instances are being terminated and replaced by the Auto Scaling group before initialization finishes. Which single change resolves this?</p>", "answers": ["<p>Reduce the ALB health check UnhealthyThresholdCount from its default so failing instances are detected sooner</p>", "<p>Increase the Auto Scaling group's HealthCheckGracePeriod to at least 480 seconds so the ASG ignores health check results until initialization completes</p>", "<p>Decrease the ALB HealthCheckIntervalSeconds to 5 seconds so status updates propagate faster to the ASG</p>", "<p>Add a CloudWatch alarm on StatusCheckFailed_Instance to trigger an ASG replacement policy</p>"], "feedbacks": ["<p>Lowering the unhealthy threshold makes the ASG mark and replace instances even faster during initialization, worsening the churn.</p>", "<p>HealthCheckGracePeriod tells the Auto Scaling group to ignore EC2 and ELB health check results for the configured number of seconds after instance launch, giving the 8-minute initialization process time to complete before the ASG can evaluate and act on health status.</p>", "<p>A shorter health check interval increases the frequency of failed checks during warm-up and does not address the root cause of the ASG acting before the grace period would normally allow.</p>", "<p>StatusCheckFailed_Instance monitors underlying EC2 hardware/network health, not target group application health, and does not resolve premature termination during app warm-up.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company wants Route 53 failover routing to declare a primary endpoint unhealthy and shift traffic to a secondary endpoint only after approximately 90 seconds of continuous failure, using standard global health checker consensus. Which health check configuration achieves this?", "prompt": {"question": "<p>A company wants Route 53 failover routing to declare a primary endpoint unhealthy and shift traffic to a secondary endpoint only after approximately 90 seconds of continuous failure, using standard global health checker consensus. Which health check configuration achieves this?</p>", "answers": ["<p>Fast health check (10-second request interval) with FailureThreshold of 3, yielding roughly 30 seconds to detect failure</p>", "<p>Fast health check (10-second request interval) with FailureThreshold of 5, yielding roughly 50 seconds to detect failure</p>", "<p>Standard health check (30-second request interval) with FailureThreshold of 1, yielding roughly 30 seconds to detect failure</p>", "<p>Standard health check (30-second request interval) with FailureThreshold of 3, yielding roughly 90 seconds to detect failure</p>"], "feedbacks": ["<p>A 10-second interval with threshold 3 detects failure in about 30 seconds, far sooner than the required 90-second window.</p>", "<p>A 10-second interval with threshold 5 detects failure in about 50 seconds, still well short of the required 90-second window.</p>", "<p>A 30-second interval with threshold 1 declares failure after a single failed check (about 30 seconds), which reacts far too quickly and increases the risk of false positives from transient network blips.</p>", "<p>Route 53 health checkers evaluate at the configured request interval and declare an endpoint unhealthy after consecutive failures equal to FailureThreshold, using majority consensus among global checker locations; a 30-second interval multiplied by a threshold of 3 yields the required approximately 90-second detection window.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs critical EC2/EBS workloads in ap-southeast-1 and must be able to launch replacement resources in ap-southeast-2 within 15 minutes of a regional outage, using data no older than 1 hour (RPO). Which solution is the MOST operationally efficient way to meet this requirement?", "prompt": {"question": "<p>A company runs critical EC2/EBS workloads in ap-southeast-1 and must be able to launch replacement resources in ap-southeast-2 within 15 minutes of a regional outage, using data no older than 1 hour (RPO). Which solution is the MOST operationally efficient way to meet this requirement?</p>", "answers": ["<p>Manually create EBS snapshots via the console once daily and copy them to ap-southeast-2 using the Copy Snapshot action right before month-end reporting</p>", "<p>Use Amazon Data Lifecycle Manager (DLM) to create snapshots every 24 hours with no cross-region copy action configured</p>", "<p>Enable S3 Cross-Region Replication on a bucket containing exported AMI metadata, and manually rebuild instances from that metadata after an outage</p>", "<p>Use AWS Backup with a backup plan that includes a cross-region copy rule scheduled hourly, storing recovery points in a backup vault in ap-southeast-2, and restore resources from there during a regional outage</p>"], "feedbacks": ["<p>Manual daily snapshot creation and copy is far too infrequent to meet an hourly RPO and is error-prone and slow to execute during an actual disaster.</p>", "<p>DLM without a cross-region copy action leaves all snapshots only in the source region, providing zero protection against a full regional outage.</p>", "<p>AMI metadata is not a reconstructable backup of EBS data via simple S3 replication; this is not a valid or supported mechanism for restoring EBS-backed resources.</p>", "<p>AWS Backup centralizes policy-based backup scheduling and supports a native cross-region copy rule, enabling automated hourly recovery points in the DR region and a fast, repeatable restore process that meets both the 1-hour RPO and the 15-minute RTO target.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A team configured S3 Cross-Region Replication (CRR) from us-east-1 (source) to us-west-2 (destination) with versioning enabled on both buckets for disaster recovery. After issuing DELETE requests without specifying version IDs on several objects in the source bucket to reduce storage costs, the team observes that destination bucket storage usage does NOT decrease, and prior object versions still appear when listed with version-aware tools. Which explanation is correct?", "prompt": {"question": "<p>A team configured S3 Cross-Region Replication (CRR) from us-east-1 (source) to us-west-2 (destination) with versioning enabled on both buckets for disaster recovery. After issuing DELETE requests without specifying version IDs on several objects in the source bucket to reduce storage costs, the team observes that destination bucket storage usage does NOT decrease, and prior object versions still appear when listed with version-aware tools. Which explanation is correct?</p>", "answers": ["<p>CRR is misconfigured; by default, delete markers should never replicate to the destination bucket, so this behavior indicates a bucket policy error</p>", "<p>DELETE requests issued without a version ID are never replicated by CRR under any configuration, so the destination bucket's data is completely unaffected by deletes in the source</p>", "<p>Replication Time Control (RTC) is disabled, causing only a 15-minute propagation delay for the delete marker, after which storage usage will decrease automatically</p>", "<p>This is expected: with versioning enabled on both buckets, the DELETE request replicates a delete marker to the destination (hiding the current version), but all object versions remain stored in both buckets until a lifecycle rule permanently expires noncurrent versions</p>"], "feedbacks": ["<p>Delete marker replication under versioning-enabled CRR is standard default behavior, not a misconfiguration.</p>", "<p>Delete markers ARE replicated by default in versioned CRR configurations, which directly explains why the current version becomes hidden at the destination.</p>", "<p>RTC affects replication speed guarantees for SLA purposes, not whether or how storage is reclaimed; storage will not decrease automatically regardless of RTC status without an expiration rule.</p>", "<p>By default, S3 CRR replicates delete markers created by non-versioned DELETE requests, which hides the current object version at the destination without removing any underlying version data; destination storage only decreases once noncurrent versions are explicitly expired via a lifecycle rule.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "An Auto Scaling group behind an ALB scales out during traffic spikes. New instances take about 3 minutes to warm up an in-memory JVM cache, causing intermittent 502 errors immediately after instances are marked healthy and begin receiving full traffic. Which single change reduces these 502 errors WITHOUT slowing down failure detection for genuinely unhealthy targets?", "prompt": {"question": "<p>An Auto Scaling group behind an ALB scales out during traffic spikes. New instances take about 3 minutes to warm up an in-memory JVM cache, causing intermittent 502 errors immediately after instances are marked healthy and begin receiving full traffic. Which single change reduces these 502 errors WITHOUT slowing down failure detection for genuinely unhealthy targets?</p>", "answers": ["<p>Increase HealthyThresholdCount to 10 consecutive successful checks before marking a target healthy</p>", "<p>Increase the target group Deregistration Delay (connection draining) to 300 seconds</p>", "<p>Enable Slow Start mode on the target group with a duration that approximates the 3-minute application warm-up period</p>", "<p>Decrease HealthCheckIntervalSeconds to 5 seconds to detect a healthy state more quickly</p>"], "feedbacks": ["<p>Raising the healthy threshold only delays when a target is first marked healthy; once marked healthy it still receives full traffic immediately, so the 502 errors during warm-up still occur.</p>", "<p>Deregistration delay governs how connections drain when a target is being removed from service, not how traffic ramps up for a newly added target.</p>", "<p>Slow Start mode gradually increases the proportion of requests an ALB sends to a newly healthy target over the configured duration (30-900 seconds), preventing an immediate flood of traffic before the cache warm-up completes, and it does not affect how quickly the ALB detects genuinely unhealthy targets.</p>", "<p>A faster health check interval speeds up detection in either direction but does not address the sudden surge of full traffic to a target that is still warming up its cache.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services company runs its primary transactional database on Amazon RDS for PostgreSQL in us-east-1. The company's disaster recovery plan requires that the database be recoverable from a complete regional outage with an RPO of 5 minutes and an RTO of 15 minutes. Which solution meets these requirements?", "prompt": {"question": "<p>A financial services company runs its primary transactional database on Amazon RDS for PostgreSQL in us-east-1. The company's disaster recovery plan requires that the database be recoverable from a complete regional outage with an RPO of 5 minutes and an RTO of 15 minutes. Which solution meets these requirements?</p>", "answers": ["<p>Enable Multi-AZ deployment for the RDS instance in us-east-1 and configure automated backups with a 7-day retention period</p>", "<p>Use AWS Backup to copy automated RDS snapshots from us-east-1 to us-west-2 once every 24 hours, and restore the latest copied snapshot in us-west-2 during a regional outage</p>", "<p>Create a cross-Region read replica of the RDS instance in us-west-2, configure Route 53 failover routing pointing to both endpoints, and promote the replica to a standalone primary during a regional outage</p>", "<p>Configure RDS automated backups with point-in-time recovery in us-east-1 only, and restore to the latest restorable time in the same Region during an outage</p>"], "feedbacks": ["<p>Multi-AZ only provides a synchronous standby in a different AZ within the SAME Region — it does not protect against a full Regional outage at all, so it cannot meet a disaster recovery requirement that assumes us-east-1 is unavailable</p>", "<p>Copying snapshots every 24 hours means up to 24 hours of data could be lost before the outage, far exceeding the 5-minute RPO requirement — snapshot-based cross-Region backup is a valid pattern only for RPOs measured in hours, not minutes</p>", "<p>A cross-Region read replica for RDS PostgreSQL typically has replication lag of only a few seconds to a couple of minutes, meeting the 5-minute RPO. Promoting the replica to a standalone writable instance is a fast, well-defined operation that combined with Route 53 failover routing (health-checked endpoint switch) can realistically complete within a 15-minute RTO. This is the standard pattern AWS documents for cross-Region DR of RDS.</p>", "<p>Point-in-time recovery configured only within us-east-1 provides no protection if the entire Region becomes unavailable — there is no secondary Region copy of the data to restore from</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "Your organization uses AWS Organizations with 60 member accounts across multiple OUs, and new accounts are provisioned weekly via account vending. You need a security baseline CloudFormation stack (CloudTrail, GuardDuty, Config rules) automatically deployed to every account in the 'Workloads' OU, including accounts created in the future, without manually assuming roles into each account. Which StackSets configuration meets this requirement?", "prompt": {"question": "<p>Your organization uses AWS Organizations with 60 member accounts across multiple OUs, and new accounts are provisioned weekly via account vending. You need a security baseline CloudFormation stack (CloudTrail, GuardDuty, Config rules) automatically deployed to every account in the 'Workloads' OU, including accounts created in the future, without manually assuming roles into each account. Which StackSets configuration meets this requirement?</p>", "answers": ["<p>Create a self-managed StackSet and manually create AWSCloudFormationStackSetExecutionRole in each new account as it's provisioned</p>", "<p>Deploy the template using a Lambda-backed custom resource triggered by an Organizations CreateAccount event in each account</p>", "<p>Create a single StackSet stack instance and manually add each new account ID to the deployment targets after provisioning</p>", "<p>Create a service-managed StackSet targeting the 'Workloads' OU with automatic deployment enabled</p>"], "feedbacks": ["<p>Self-managed StackSets require manually creating execution/administration roles in every account, which defeats the requirement to avoid manual per-account work and doesn't auto-target new accounts.</p>", "<p>Building a custom Lambda/event-driven solution reinvents functionality StackSets already provides natively and adds unnecessary operational overhead.</p>", "<p>Manually adding account IDs after each provisioning event is not automatic and fails the requirement for future accounts to be covered without intervention.</p>", "<p>Service-managed permissions let StackSets use AWS Organizations trust to deploy without manual IAM role setup in target accounts. Enabling automatic deployment ensures the stack is automatically deployed to any new account that joins the targeted OU, with no manual intervention.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A CloudFormation stack includes a custom resource of type Custom::ConfigValidator backed by a Lambda function that performs a one-time validation during stack creation. After the stack is created, an engineer runs 'aws cloudformation detect-stack-drift' on the stack. What drift status will CloudFormation report for the custom resource?", "prompt": {"question": "<p>A CloudFormation stack includes a custom resource of type Custom::ConfigValidator backed by a Lambda function that performs a one-time validation during stack creation. After the stack is created, an engineer runs 'aws cloudformation detect-stack-drift' on the stack. What drift status will CloudFormation report for the custom resource?</p>", "answers": ["<p>NOT_CHECKED</p>", "<p>IN_SYNC</p>", "<p>DELETED</p>", "<p>MODIFIED</p>"], "feedbacks": ["<p>Drift detection does not support all resource types. Custom resources (Custom::* / AWS::CloudFormation::CustomResource) are among the types CloudFormation cannot evaluate for drift, so they are always reported as NOT_CHECKED regardless of their actual state.</p>", "<p>IN_SYNC would imply CloudFormation actively compared current state to the template and found no differences, which it cannot do for unsupported resource types.</p>", "<p>DELETED is reported only when a supported resource that CloudFormation is tracking has been removed outside of CloudFormation, not applicable here.</p>", "<p>MODIFIED requires CloudFormation to detect a property-level change, which it cannot evaluate for custom resources.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A SysOps administrator must update a production CloudFormation stack where the change will cause an AWS::RDS::DBInstance to be replaced due to a modified engine version property, resulting in data loss if not handled carefully. Before applying the update, the administrator needs to know exactly which resources will be replaced versus modified in place. Which approach should be used?", "prompt": {"question": "<p>A SysOps administrator must update a production CloudFormation stack where the change will cause an AWS::RDS::DBInstance to be replaced due to a modified engine version property, resulting in data loss if not handled carefully. Before applying the update, the administrator needs to know exactly which resources will be replaced versus modified in place. Which approach should be used?</p>", "answers": ["<p>Enable a stack policy that denies Replace actions on the DB instance</p>", "<p>Run 'aws cloudformation detect-stack-drift' before updating the stack</p>", "<p>Create and review a change set for the stack update before executing it</p>", "<p>Update the stack directly and monitor the CloudFormation events console during execution</p>"], "feedbacks": ["<p>A stack policy can block certain update actions on protected resources, but it does not preview the impact of a change — it only enforces restrictions and would cause the update to fail rather than inform the decision beforehand.</p>", "<p>Drift detection compares the current live configuration to the last known template state; it does not evaluate the impact of a pending update.</p>", "<p>Change sets show a preview of exactly how CloudFormation will modify resources (Add, Modify, Remove) and explicitly flag whether a Modify action requires replacement, allowing the administrator to catch destructive changes like DB instance replacement before applying the update.</p>", "<p>Monitoring events during execution only reveals what happened after the destructive replacement has already begun, which is too late to prevent data loss.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company requires that critical security patches only be installed on production EC2 instances 7 days after release (to allow time for internal review), and that patching only occurs during a defined Sunday 2-4 AM maintenance window. Which configuration satisfies both requirements?", "prompt": {"question": "<p>A company requires that critical security patches only be installed on production EC2 instances 7 days after release (to allow time for internal review), and that patching only occurs during a defined Sunday 2-4 AM maintenance window. Which configuration satisfies both requirements?</p>", "answers": ["<p>Create a custom patch baseline with a 7-day auto-approval delay for the Critical severity classification, and associate it with a Maintenance Window task that runs the AWS-RunPatchBaseline document on the defined schedule</p>", "<p>Create an SSM Association running the AWS-ApplyPatchBaseline document directly, with no maintenance window attached</p>", "<p>Enable EC2 instance 'automatic patching' in the console with a 7-day delay setting</p>", "<p>Use the default AWS-provided patch baseline and schedule a weekly cron job on each instance to run yum/apt update</p>"], "feedbacks": ["<p>Patch Manager patch baselines support an auto-approval delay per severity/classification rule, ensuring patches aren't approved until N days after release. Pairing this baseline with a Maintenance Window task running AWS-RunPatchBaseline on a cron schedule ensures patching happens only within the defined window.</p>", "<p>Running AWS-ApplyPatchBaseline via an Association with no maintenance window means patches would be applied on the association's schedule immediately, not confined to the Sunday 2-4 AM window.</p>", "<p>EC2 does not have a native console feature called 'automatic patching' with a delay setting; this option describes a capability that doesn't exist.</p>", "<p>A local cron job bypasses Patch Manager's approval rules and baseline logic entirely, so the 7-day delay requirement would not be enforced.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A team needs to build custom hardened Linux AMIs on a recurring schedule, automatically run vulnerability scans and application-level tests against each new AMI build, and distribute the validated AMI to three other AWS Regions — all with minimal custom scripting to maintain. Which service should be used to build this pipeline?", "prompt": {"question": "<p>A team needs to build custom hardened Linux AMIs on a recurring schedule, automatically run vulnerability scans and application-level tests against each new AMI build, and distribute the validated AMI to three other AWS Regions — all with minimal custom scripting to maintain. Which service should be used to build this pipeline?</p>", "answers": ["<p>AWS Systems Manager Automation using the AWS-UpdateLinuxAmi automation document only</p>", "<p>A manual process: launch an instance, apply updates via SSH, then call CreateImage and copy the AMI to each region</p>", "<p>EC2 Image Builder with a recipe, test component, and distribution configuration</p>", "<p>AWS CodePipeline with a CodeBuild stage that calls the EC2 CreateImage API</p>"], "feedbacks": ["<p>AWS-UpdateLinuxAmi is a single automation document that patches an AMI, but it does not provide built-in test stages or multi-Region distribution configuration on its own.</p>", "<p>A fully manual process requires significant custom scripting for scheduling, testing, and cross-Region copying, which fails the 'minimal custom scripting' requirement.</p>", "<p>EC2 Image Builder is purpose-built for this exact use case: it defines build recipes, supports test components (including security/vulnerability testing via built-in or custom test steps), and includes a distribution configuration to automatically copy and share the validated AMI to multiple Regions on a schedule — all natively, with minimal custom scripting.</p>", "<p>CodePipeline/CodeBuild could be scripted to call CreateImage, but there is no native testing or distribution framework — the team would have to build and maintain all of that logic themselves, unlike Image Builder's purpose-built components.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "An Elastic Beanstalk environment runs a fixed fleet of 4 instances behind an Application Load Balancer serving production traffic. The application must remain at full capacity throughout every deployment (no reduction in available instances), the team has a strict budget that prohibits temporarily doubling the fleet size, and any bad deployment should be caught on a small subset of instances before it reaches the rest of the fleet. Which Elastic Beanstalk deployment policy should be configured?", "prompt": {"question": "<p>An Elastic Beanstalk environment runs a fixed fleet of 4 instances behind an Application Load Balancer serving production traffic. The application must remain at full capacity throughout every deployment (no reduction in available instances), the team has a strict budget that prohibits temporarily doubling the fleet size, and any bad deployment should be caught on a small subset of instances before it reaches the rest of the fleet. Which Elastic Beanstalk deployment policy should be configured?</p>", "answers": ["<p>Immutable deployment</p>", "<p>All at once deployment</p>", "<p>Rolling deployment</p>", "<p>Rolling with additional batch deployment</p>"], "feedbacks": ["<p>Immutable deployment launches an entirely new fleet of instances (temporarily up to double the original size) before swapping traffic over, which violates the budget constraint against doubling capacity.</p>", "<p>All at once updates every instance simultaneously with no batching, causing full application downtime during deployment and no way to catch issues on a subset first.</p>", "<p>Standard Rolling deployment takes a batch out of service and replaces it within the existing fleet, temporarily reducing total available capacity during each batch — violating the 'no reduction in capacity' requirement.</p>", "<p>Rolling with additional batch launches one extra batch of instances with the new version first, so total capacity never drops below the original fleet size, then performs the rolling update in batches across the rest of the fleet — catching issues in the first small batch before all instances are updated, without doubling the entire fleet's cost.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A CloudFormation stack manages a security group that an engineer manually modified in the console to add an inbound rule during an incident. The SysOps administrator needs to identify exactly which resources and properties have diverged from the stack's template, without deleting or recreating any resources. Which action should be performed FIRST?", "prompt": {"question": "<p>A CloudFormation stack manages a security group that an engineer manually modified in the console to add an inbound rule during an incident. The SysOps administrator needs to identify exactly which resources and properties have diverged from the stack's template, without deleting or recreating any resources. Which action should be performed FIRST?</p>", "answers": ["<p>Create a change set against the existing template and review the proposed changes before executing it</p>", "<p>Enable AWS Config conformance packs to compare the security group against a compliance baseline</p>", "<p>Run aws cloudformation detect-stack-drift on the stack, then review each resource's DriftInformation and StackResourceDriftStatus</p>", "<p>Set the stack's termination protection to enabled, then perform a stack update using the original template</p>"], "feedbacks": ["<p>Change sets show the delta between the current template/parameters and a NEW proposed template — they do not detect out-of-band manual changes made outside CloudFormation, so they won't reveal the console-added rule.</p>", "<p>AWS Config can track configuration changes and compliance over time, but it is a separate service; it is not the CloudFormation mechanism the exam expects for detecting stack drift and does not report against the stack's template definition.</p>", "<p>Drift detection (detect-stack-drift / describe-stack-resource-drifts) is the CloudFormation-native mechanism for comparing actual resource configuration against the stack template and reporting per-resource drift status (IN_SYNC, MODIFIED, DELETED, NOT_CHECKED) without modifying or recreating anything.</p>", "<p>Termination protection only prevents accidental stack deletion; updating the stack with the original template would simply attempt to reconcile resources via a stack update, which is a remediation step, not the first diagnostic step, and could fail or produce unintended results without first knowing what drifted.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company manages 50 AWS accounts under AWS Organizations. The SysOps team must ensure that all Amazon Linux 2 EC2 instances across every member account and Region are patched with the latest security updates on a recurring weekly schedule, using one centrally managed configuration. Which solution meets this requirement with the LEAST ongoing operational overhead?", "prompt": {"question": "<p>A company manages 50 AWS accounts under AWS Organizations. The SysOps team must ensure that all Amazon Linux 2 EC2 instances across every member account and Region are patched with the latest security updates on a recurring weekly schedule, using one centrally managed configuration. Which solution meets this requirement with the LEAST ongoing operational overhead?</p>", "answers": ["<p>Use AWS CloudFormation StackSets to deploy an identical maintenance window and custom patch baseline stack to every member account and Region</p>", "<p>Use AWS Systems Manager Quick Setup to configure a Patch Policy at the organization level, targeting all accounts and Regions with a single patch baseline and schedule</p>", "<p>In the management account, build a custom patch baseline and copy it to each member account with CLI scripts, then manually create a maintenance window in each account</p>", "<p>Enable AWS Config conformance packs organization-wide with a patch-compliance managed rule and configure remediation actions to trigger patching</p>"], "feedbacks": ["<p>StackSets can technically replicate resources across accounts, but the administrator must author, version, and maintain the CloudFormation template for the patch baseline and maintenance window, then manage stack instance operations across accounts/Regions — considerably more ongoing overhead than a managed Quick Setup policy.</p>", "<p>Systems Manager Quick Setup Patch Policies are purpose-built for this scenario: they let an organization management account define one patch baseline, scan/install schedule, and target (all accounts and Regions in the org), and Quick Setup automatically provisions the underlying maintenance windows, IAM roles, and associations in every member account/Region with no per-account setup required.</p>", "<p>Manually copying baselines and creating maintenance windows per account is the highest-overhead option and does not scale to 50 accounts with recurring updates.</p>", "<p>AWS Config conformance packs can report on patch compliance state, but Config is a compliance/detection tool, not a patching orchestration mechanism — it does not natively install patches without being wired into a separate remediation/automation document, adding complexity rather than reducing it.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company in Account A stores objects in an S3 bucket encrypted with a customer managed AWS KMS key. A SysOps administrator needs to grant an IAM role in Account B the ability to decrypt and read these objects, following least privilege. What should be configured?", "prompt": {"question": "<p>A company in Account A stores objects in an S3 bucket encrypted with a customer managed AWS KMS key. A SysOps administrator needs to grant an IAM role in Account B the ability to decrypt and read these objects, following least privilege. What should be configured?</p>", "answers": ["<p>Update the KMS key policy to add the Account B IAM role as a principal allowed to perform kms:Decrypt, and attach an IAM policy in Account B granting kms:Decrypt on that key's ARN</p>", "<p>Add a bucket policy on the S3 bucket in Account A that grants s3:GetObject to the Account B role; no KMS changes are needed because S3 bucket policies control all access</p>", "<p>Use AWS KMS multi-Region keys to replicate the key into Account B so the account can decrypt objects independently</p>", "<p>Make the S3 bucket public and use a bucket policy condition restricting access to Account B's account ID</p>"], "feedbacks": ["<p>Cross-account access to KMS-encrypted objects requires permission on BOTH sides: the KMS key policy must explicitly allow the external principal (KMS key policies are the source of truth for a customer managed key), and the calling account needs an IAM policy granting kms:Decrypt on that key ARN. S3 bucket permissions alone are not sufficient when a customer managed key is involved.</p>", "<p>S3 bucket policy alone does not grant permission to use the KMS key; decryption will still fail with AccessDenied on the KMS action</p>", "<p>Multi-Region keys are for replicating a key as an independent key resource in another Region for the SAME account/application (e.g., disaster recovery or global apps) and do not solve cross-account permission delegation</p>", "<p>Making the bucket public is a major security anti-pattern and still would not resolve the missing KMS decrypt permission</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization needs to be able to prove that CloudTrail log files delivered to S3 have not been tampered with after delivery, across all AWS Regions in the account. Which configuration BEST meets this requirement?", "prompt": {"question": "<p>An organization needs to be able to prove that CloudTrail log files delivered to S3 have not been tampered with after delivery, across all AWS Regions in the account. Which configuration BEST meets this requirement?</p>", "answers": ["<p>Enable AWS Config to record changes to the CloudTrail trail configuration itself</p>", "<p>Enable a multi-Region trail with log file validation enabled, delivering to an S3 bucket that has MFA delete enabled</p>", "<p>Enable a single-Region trail and turn on CloudTrail Insights to detect unusual API activity</p>", "<p>Enable CloudTrail Lake and run periodic SQL queries against the event data store to look for gaps</p>"], "feedbacks": ["<p>AWS Config tracks configuration changes to resources like the trail itself, but it does not validate the integrity of the delivered log file contents</p>", "<p>Log file validation generates a SHA-256/RSA digest file for each delivered log file, cryptographically proving whether the log file has been altered or deleted after delivery. Combining this with a multi-Region trail ensures every Region is covered, and MFA delete on the destination bucket adds protection against unauthorized deletion of the log objects themselves.</p>", "<p>CloudTrail Insights detects unusual API call volume/patterns; it has nothing to do with cryptographic integrity validation of log files</p>", "<p>CloudTrail Lake provides queryable immutable storage for analysis, but it does not provide the digest-based tamper-evidence mechanism that log file validation provides for delivered S3 log objects</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A team needs Amazon RDS database credentials to rotate automatically every 30 days without the team writing custom rotation logic. Which AWS service should they use?", "prompt": {"question": "<p>A team needs Amazon RDS database credentials to rotate automatically every 30 days without the team writing custom rotation logic. Which AWS service should they use?</p>", "answers": ["<p>AWS Systems Manager Parameter Store advanced parameters with an expiration policy</p>", "<p>AWS KMS automatic key rotation enabled on the customer managed key</p>", "<p>AWS Secrets Manager, using its built-in rotation configuration for RDS</p>", "<p>Amazon S3 Lifecycle rules to expire an encrypted object containing the credentials</p>"], "feedbacks": ["<p>Parameter Store expiration policies only notify or delete a parameter at expiry; there is no built-in mechanism to actually rotate the credential value or coordinate with the database</p>", "<p>KMS automatic key rotation only rotates the underlying cryptographic key material for a KMS key annually; it has no relationship to database user credentials</p>", "<p>AWS Secrets Manager provides native, built-in rotation templates/Lambda functions specifically for RDS, Aurora, DocumentDB, and Redshift, allowing rotation on a schedule (e.g., every 30 days) with minimal setup and no custom rotation logic required.</p>", "<p>S3 Lifecycle only manages object storage class transitions/expiration; it cannot rotate a live database credential or coordinate with RDS</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A SysOps administrator must continuously evaluate resource configurations across multiple AWS accounts against the CIS AWS Foundations Benchmark and view aggregated compliance findings in one place. Which solution BEST satisfies this requirement?", "prompt": {"question": "<p>A SysOps administrator must continuously evaluate resource configurations across multiple AWS accounts against the CIS AWS Foundations Benchmark and view aggregated compliance findings in one place. Which solution BEST satisfies this requirement?</p>", "answers": ["<p>Amazon GuardDuty with S3 protection and EKS protection enabled</p>", "<p>AWS Security Hub with the CIS AWS Foundations Benchmark standard enabled and cross-account/cross-Region aggregation configured</p>", "<p>AWS Trusted Advisor security pillar checks reviewed manually in each account</p>", "<p>An AWS Config conformance pack deployed only in the account currently being reviewed</p>"], "feedbacks": ["<p>GuardDuty is a threat detection service analyzing logs for malicious activity; it does not evaluate configuration compliance against the CIS benchmark</p>", "<p>AWS Security Hub is purpose-built to enable industry standards like the CIS AWS Foundations Benchmark, continuously run automated checks, and aggregate findings across multiple accounts and Regions (via Security Hub's cross-Region aggregation and integration with AWS Organizations), giving a single unified compliance dashboard.</p>", "<p>Trusted Advisor gives best-practice checks but does not provide the full automated CIS benchmark evaluation or multi-account aggregated compliance view</p>", "<p>A Config conformance pack deployed in a single account can check CIS-based rules for that account only, but by itself does not aggregate findings across multiple accounts the way Security Hub does</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A cloud security team wants to allow a development team to create their own IAM roles, but no role the developers create should ever be able to exceed S3 read-only access, regardless of what policies they attach. Which configuration achieves this?", "prompt": {"question": "<p>A cloud security team wants to allow a development team to create their own IAM roles, but no role the developers create should ever be able to exceed S3 read-only access, regardless of what policies they attach. Which configuration achieves this?</p>", "answers": ["<p>Attach a Service Control Policy (SCP) in AWS Organizations to the developers' IAM users limiting them to S3 read-only actions</p>", "<p>Configure S3 bucket resource policies to deny all actions except s3:GetObject and s3:ListBucket for the entire account</p>", "<p>Attach a permissions boundary policy limited to S3 read-only actions to the developers, and require that iam:CreateRole calls set the same permissions boundary on any role they create</p>", "<p>Enable IAM Access Analyzer, which will automatically strip overly permissive statements from any policy the developers attach to new roles</p>"], "feedbacks": ["<p>SCPs set the maximum permissions for an entire account or OU in AWS Organizations, but they act as a guardrail at the account level, not as a way to enforce a permissions cap that is inherited automatically by roles the users create — a permissions boundary is the correct scoped tool here</p>", "<p>Restricting the S3 bucket resource policy affects everyone in the account trying to access that bucket, but it does not prevent developers from creating IAM roles with excessive permissions to other resources/services</p>", "<p>A permissions boundary is the correct IAM mechanism for capping the maximum permissions a principal can grant to itself or to entities it creates. By attaching the boundary to the developers and enforcing (via an IAM policy condition on iam:CreateRole) that any role they create must also have that same boundary attached, the effective permissions of any role they create can never exceed the boundary, no matter what permission policies are attached to it.</p>", "<p>IAM Access Analyzer identifies and reports overly permissive or externally accessible policies for review; it does not automatically modify or restrict policies at creation time</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs internal-only applications on private hostnames (e.g., app.internal.example.com) that are never exposed to the public internet, and wants TLS certificates for them managed through AWS Certificate Manager. Which statement is correct?", "prompt": {"question": "<p>A company runs internal-only applications on private hostnames (e.g., app.internal.example.com) that are never exposed to the public internet, and wants TLS certificates for them managed through AWS Certificate Manager. Which statement is correct?</p>", "answers": ["<p>ACM's public certificate authority will automatically issue certificates for these internal hostnames because AWS trusts traffic originating inside a VPC</p>", "<p>A private CA must be created with AWS Certificate Manager Private Certificate Authority (ACM PCA) to issue certificates for these internal hostnames, since ACM's public CA can only issue certificates for domains validated via public DNS or HTTP</p>", "<p>ACM does not support internal applications at all; certificate-based encryption must instead be handled by IAM Identity Center</p>", "<p>Public ACM certificates for internal hostnames renew automatically without domain validation since AWS considers internal traffic pre-trusted</p>"], "feedbacks": ["<p>Public ACM certificates always require domain validation ownership proof through public DNS or HTTP/email; internal hostnames that don't resolve publicly cannot pass this validation</p>", "<p>ACM's standard public certificate authority only issues certificates for domain names that can be validated as owned by the requester via public DNS (CNAME) or email validation, which is not possible for private/internal-only hostnames. AWS Certificate Manager Private Certificate Authority (ACM PCA) lets an organization stand up its own private CA hierarchy to issue and manage certificates for internal hostnames trusted only within the organization's infrastructure.</p>", "<p>ACM does support internal applications, just through the private CA offering rather than the public CA; IAM Identity Center is unrelated (it manages workforce identity/SSO, not TLS certificates)</p>", "<p>There is no such automatic-trust renewal exception for internal traffic; all public ACM certificates require successful domain validation to issue or renew</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company replicates objects across AWS Regions using S3 Cross-Region Replication (CRR). The source bucket is encrypted with SSE-KMS using a customer managed key (CMK-A). Replication is configured, but the S3 console shows a replication status of FAILED for all encrypted objects, with an error indicating access denied to the KMS key. The destination bucket uses a different customer managed key (CMK-B). What should the SysOps administrator do to fix replication of the KMS-encrypted objects?", "prompt": {"question": "<p>A company replicates objects across AWS Regions using S3 Cross-Region Replication (CRR). The source bucket is encrypted with SSE-KMS using a customer managed key (CMK-A). Replication is configured, but the S3 console shows a replication status of FAILED for all encrypted objects, with an error indicating access denied to the KMS key. The destination bucket uses a different customer managed key (CMK-B). What should the SysOps administrator do to fix replication of the KMS-encrypted objects?</p>", "answers": ["<p>Enable S3 Bucket Versioning on the destination bucket only, since versioning must exist on both buckets for KMS objects to replicate</p>", "<p>Update the replication IAM role to include kms:Decrypt permission on CMK-A and kms:Encrypt permission on CMK-B, and specify CMK-B as the destination encryption key in the replication configuration's SourceSelectionCriteria</p>", "<p>Change the source bucket's default encryption from SSE-KMS to SSE-S3 so that KMS permissions are no longer required for replication</p>", "<p>Grant the destination account's root user a resource policy statement on CMK-A allowing kms:* actions, since only root-level access can replicate KMS objects across accounts</p>"], "feedbacks": ["<p>Versioning must be enabled on both source and destination buckets for any CRR to work at all, but this is a prerequisite unrelated to the KMS-specific access denied error described, and it's already assumed to be configured since non-encrypted replication would otherwise succeed.</p>", "<p>S3 CRR does not replicate SSE-KMS encrypted objects by default. You must explicitly enable SourceSelectionCriteria.SseKmsEncryptedObjects.Status in the replication configuration, specify the destination CMK via ReplicaKmsKeyID, and ensure the IAM role used by replication has kms:Decrypt on the source key (to read the object) and kms:Encrypt on the destination key (to re-encrypt it there). Missing either permission or the destination key specification causes a FAILED replication status with an access denied error.</p>", "<p>Removing SSE-KMS encryption is not an acceptable fix — it changes the security posture and violates the requirement to use customer managed keys; the actual issue is a missing IAM/KMS permission, not incompatibility with KMS.</p>", "<p>Granting root-level kms:* access is overly permissive and violates least privilege; replication only requires scoped kms:Decrypt/kms:Encrypt permissions on the IAM role actually performing the replication, not root account access.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has EC2 instances in a private subnet with no internet gateway or NAT gateway attached. A Gateway VPC Endpoint for Amazon S3 was created and associated with the VPC. Instances in one private subnet can reach S3 successfully, but instances in a second private subnet time out when accessing S3. Both subnets have identical security groups and default NACLs. What is the MOST likely cause?", "prompt": {"question": "<p>A company has EC2 instances in a private subnet with no internet gateway or NAT gateway attached. A Gateway VPC Endpoint for Amazon S3 was created and associated with the VPC. Instances in one private subnet can reach S3 successfully, but instances in a second private subnet time out when accessing S3. Both subnets have identical security groups and default NACLs. What is the MOST likely cause?</p>", "answers": ["<p>The S3 bucket policy does not include a condition allowing the second subnet's CIDR range</p>", "<p>Gateway VPC Endpoints only support one subnet per VPC and a second endpoint is required</p>", "<p>The second subnet's default NACL is blocking outbound traffic to the S3 prefix list range</p>", "<p>The route table associated with the second subnet does not have a route to the S3 prefix list via the gateway endpoint</p>"], "feedbacks": ["<p>Bucket policies can restrict by VPC or VPC endpoint ID via aws:SourceVpce, but this wouldn't cause a symmetric issue where one subnet works and another doesn't unless routing itself is broken first</p>", "<p>Gateway endpoints operate at the VPC level and can be associated with multiple route tables covering multiple subnets simultaneously — there is no one-subnet limitation</p>", "<p>Default NACLs allow all inbound and outbound traffic by default, so an unmodified NACL would not selectively block only one subnet's traffic</p>", "<p>A Gateway Endpoint only affects traffic from subnets whose route table has been explicitly associated with the endpoint. When you create the endpoint, you choose which route tables get the automatic pl-xxxxx route entry. If the second subnet uses a different route table that wasn't selected, no route to the endpoint exists and traffic has nowhere to go, causing timeouts.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company uses AWS Transit Gateway to connect a Shared Services VPC, a Production VPC, and a Development VPC. Requirements: Production and Development VPCs must both reach Shared Services, but Production and Development must NOT be able to communicate with each other. Which Transit Gateway configuration meets this requirement with the LEAST operational overhead?", "prompt": {"question": "<p>A company uses AWS Transit Gateway to connect a Shared Services VPC, a Production VPC, and a Development VPC. Requirements: Production and Development VPCs must both reach Shared Services, but Production and Development must NOT be able to communicate with each other. Which Transit Gateway configuration meets this requirement with the LEAST operational overhead?</p>", "answers": ["<p>Create a single Transit Gateway route table, associate all three VPCs, and propagate all routes into it</p>", "<p>Create VPC peering connections between Production-to-SharedServices and Development-to-SharedServices, bypassing Transit Gateway entirely</p>", "<p>Attach an AWS Network Firewall to the Transit Gateway and write stateful rules to block Production-to-Development traffic</p>", "<p>Create two separate Transit Gateway route tables — one associated with Production that only propagates Shared Services routes, and one associated with Development that only propagates Shared Services routes</p>"], "feedbacks": ["<p>A single shared route table with all propagations creates a full mesh, allowing Production and Development to route to each other directly, violating the isolation requirement</p>", "<p>VPC peering does not scale well as VPC count grows, requires managing peering connections and route table entries per pair, and abandons the Transit Gateway hub-and-spoke design already in place</p>", "<p>Network Firewall can enforce this but adds significant cost and operational complexity compared to simply using separate TGW route tables, which is the native, low-overhead mechanism designed for this exact use case</p>", "<p>Transit Gateway supports multiple route tables per attachment. By associating Production and Development with separate route tables that only propagate routes from Shared Services (not from each other), traffic between Production and Development has no route and is dropped, while both can still reach Shared Services.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company uses Amazon Route 53 geoproximity routing to direct traffic to resources in us-east-1 and eu-west-1. Users in France are currently routed to eu-west-1, but the company wants to shift a larger share of European traffic to us-east-1 without moving any resources or changing DNS record types. What should be done?", "prompt": {"question": "<p>A company uses Amazon Route 53 geoproximity routing to direct traffic to resources in us-east-1 and eu-west-1. Users in France are currently routed to eu-west-1, but the company wants to shift a larger share of European traffic to us-east-1 without moving any resources or changing DNS record types. What should be done?</p>", "answers": ["<p>Increase the bias value on the us-east-1 resource record to expand its geographic region</p>", "<p>Change the routing policy from geoproximity to geolocation for the eu-west-1 record</p>", "<p>Lower the TTL on the eu-west-1 record so Route 53 recalculates traffic shares more frequently</p>", "<p>Add a weighted routing policy record for us-east-1 with a higher weight than eu-west-1</p>"], "feedbacks": ["<p>Geoproximity routing lets you set a bias value (-99 to 99) per resource. Increasing the bias for us-east-1 expands the geographic area from which traffic is routed to it, pulling in more traffic from nearby regions like Western Europe — without touching the actual resources or record types.</p>", "<p>Switching to geolocation routing is a routing policy change, not merely a traffic-share adjustment, and geolocation doesn't support gradual bias-based shifting the way geoproximity does</p>", "<p>TTL controls DNS caching duration, not how geoproximity calculates which region serves a given geographic location — it has no effect on traffic distribution logic</p>", "<p>Weighted routing distributes traffic randomly based on assigned weights regardless of geographic location, which doesn't preserve the geoproximity-based behavior the company wants to keep</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has an AWS Direct Connect private VIF as its primary connection to a VPC and a Site-to-Site VPN as a backup path, both using BGP. During normal operation, all traffic must use the Direct Connect path. If Direct Connect fails, traffic must automatically fail over to the VPN. Which configuration achieves this?", "prompt": {"question": "<p>A company has an AWS Direct Connect private VIF as its primary connection to a VPC and a Site-to-Site VPN as a backup path, both using BGP. During normal operation, all traffic must use the Direct Connect path. If Direct Connect fails, traffic must automatically fail over to the VPN. Which configuration achieves this?</p>", "answers": ["<p>Assign a lower MTU to the VPN tunnel interfaces so Direct Connect is always selected first</p>", "<p>Configure a longer AS_PATH prepend on the BGP advertisements sent over the VPN connection so the Direct Connect path is preferred under normal conditions</p>", "<p>Disable route propagation on the VPN attachment and manually insert a static route that only activates during maintenance windows</p>", "<p>Configure equal AS_PATH lengths on both connections and rely on ECMP to balance traffic evenly between Direct Connect and VPN</p>"], "feedbacks": ["<p>MTU size affects packet fragmentation, not BGP path preference or route selection — it has no bearing on which path is chosen</p>", "<p>BGP path selection prefers routes with a shorter AS_PATH. By prepending extra AS numbers on the VPN's advertised routes, the VPN path appears 'longer' and less preferred, so traffic uses Direct Connect whenever it's available. If Direct Connect fails and its routes are withdrawn, the VPN becomes the only advertised path and traffic fails over automatically.</p>", "<p>Manually toggling static routes during maintenance windows is an operational, non-automated process and doesn't provide automatic failover based on real connection health</p>", "<p>Equal-length AS_PATHs with ECMP would load-balance traffic across both paths simultaneously, which violates the requirement that all traffic use Direct Connect exclusively during normal operation</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company hosts static content in a private S3 bucket and serves it exclusively through Amazon CloudFront. The security team requires that all requests to the S3 origin come only from the specific CloudFront distribution, and that the bucket remain fully private with no public access. Which configuration meets this requirement using current AWS best practices?", "prompt": {"question": "<p>A company hosts static content in a private S3 bucket and serves it exclusively through Amazon CloudFront. The security team requires that all requests to the S3 origin come only from the specific CloudFront distribution, and that the bucket remain fully private with no public access. Which configuration meets this requirement using current AWS best practices?</p>", "answers": ["<p>Configure Origin Access Control (OAC) on the CloudFront distribution and update the S3 bucket policy to allow the CloudFront service principal with a condition matching the distribution's ARN</p>", "<p>Enable S3 static website hosting and restrict access using a bucket policy that allows only the CloudFront domain name as the referer</p>", "<p>Make the S3 bucket public but restrict access using signed URLs generated by the application for every object request</p>", "<p>Create an Origin Access Identity (OAI) for the distribution and configure the bucket ACL to grant the OAI full public read access</p>"], "feedbacks": ["<p>Origin Access Control (OAC) is the current AWS-recommended method for securing S3 origins behind CloudFront. It uses SigV4 signing on every request and a bucket policy that grants access to the cloudfront.amazonaws.com service principal, scoped with an aws:SourceArn condition to the specific distribution — keeping the bucket fully private with no public access needed.</p>", "<p>Referer-header checks are trivially spoofable and static website hosting endpoints do not support private bucket access at all — S3 website endpoints require public objects</p>", "<p>Making the bucket public defeats the requirement entirely; signed URLs control application-level access but don't prevent direct public requests to the underlying objects</p>", "<p>OAI is the legacy mechanism, still functional but superseded by OAC for new distributions, and 'granting the OAI full public read access' is a contradiction — OAI access is granted via bucket policy scoped to the OAI's canonical user, not a public ACL</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An EC2 instance in a subnet needs to make outbound HTTPS calls to an external API. The subnet's custom Network ACL has these rules: Outbound — allow TCP 443 to 0.0.0.0/0; Inbound — allow TCP 22 from the corporate CIDR only, deny all else. The instance's security group allows all outbound traffic and has no inbound rules. Outbound connection attempts succeed at the TCP level, but no response data is ever received. What change resolves this?", "prompt": {"question": "<p>An EC2 instance in a subnet needs to make outbound HTTPS calls to an external API. The subnet's custom Network ACL has these rules: Outbound — allow TCP 443 to 0.0.0.0/0; Inbound — allow TCP 22 from the corporate CIDR only, deny all else. The instance's security group allows all outbound traffic and has no inbound rules. Outbound connection attempts succeed at the TCP level, but no response data is ever received. What change resolves this?</p>", "answers": ["<p>Add an inbound NACL rule allowing TCP traffic on the ephemeral port range (1024-65535) from 0.0.0.0/0</p>", "<p>Add an inbound security group rule allowing TCP 443 from 0.0.0.0/0</p>", "<p>Change the outbound NACL rule to allow all protocols and all ports instead of just TCP 443</p>", "<p>Add an outbound security group rule explicitly allowing TCP 443, since security groups deny all outbound traffic by default</p>"], "feedbacks": ["<p>Network ACLs are stateless, so return traffic must be explicitly permitted. The external server responds from port 443 to the instance's ephemeral source port, so the NACL needs an inbound rule allowing traffic on the ephemeral range (commonly 1024-65535) from 0.0.0.0/0. Security groups are stateful and already allow the return traffic automatically since the outbound request was allowed.</p>", "<p>Security groups are stateful, so an inbound rule is not needed for return traffic on an outbound-initiated connection — adding one is unnecessary and doesn't address the actual stateless NACL problem</p>", "<p>The outbound NACL rule already permits port 443 outbound, which is sufficient for the initial request; the issue is the missing inbound rule for the return traffic, not additional outbound permissions</p>", "<p>Security groups allow all outbound traffic by default (the scenario also confirms this explicitly), so this default behavior is not the cause of the problem</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has three VPCs—A, B, and C—each attached to a single Transit Gateway in the same account. VPC A's attachment is associated with Transit Gateway Route Table RT1. Route propagation is enabled for VPC B's attachment into RT1, but not for VPC C's attachment. Instances in VPC A can successfully reach VPC B but time out when reaching VPC C, even though every VPC route table correctly sends traffic destined for 10.0.0.0/8 to the Transit Gateway attachment, and security groups/NACLs allow the traffic in both directions. What should the SysOps administrator do to restore connectivity from VPC A to VPC C with the LEAST operational overhead?", "prompt": {"question": "<p>A company has three VPCs—A, B, and C—each attached to a single Transit Gateway in the same account. VPC A's attachment is associated with Transit Gateway Route Table RT1. Route propagation is enabled for VPC B's attachment into RT1, but not for VPC C's attachment. Instances in VPC A can successfully reach VPC B but time out when reaching VPC C, even though every VPC route table correctly sends traffic destined for 10.0.0.0/8 to the Transit Gateway attachment, and security groups/NACLs allow the traffic in both directions. What should the SysOps administrator do to restore connectivity from VPC A to VPC C with the LEAST operational overhead?</p>", "answers": ["<p>Modify the security groups attached to instances in VPC C to explicitly allow inbound traffic from VPC A's CIDR range</p>", "<p>Create a new VPC peering connection directly between VPC A and VPC C to bypass the Transit Gateway</p>", "<p>Enable route propagation for VPC C's attachment into RT1, or add a static route in RT1 pointing VPC C's CIDR to VPC C's attachment</p>", "<p>Add a route in VPC C's local subnet route tables that sends VPC A's CIDR range through VPC C's internet gateway</p>"], "feedbacks": ["<p>Security groups and NACLs were already confirmed to allow the traffic; the problem is that traffic never reaches VPC C because the Transit Gateway route table lacks a route to it, so modifying security groups changes nothing.</p>", "<p>Creating a direct VPC peering connection works around the problem instead of fixing the actual Transit Gateway route table misconfiguration, adds unnecessary infrastructure, and does not address why routing through the Transit Gateway itself is failing.</p>", "<p>In a Transit Gateway route table, each attachment's routes are learned either through automatic propagation or manual static routes. Since RT1 (associated with VPC A's attachment) never learned VPC C's CIDR — propagation wasn't enabled and no static route exists — RT1 has no path to VPC C, so traffic is dropped at the Transit Gateway regardless of correct VPC-level route tables or security rules. Enabling propagation or adding a static route in RT1 for VPC C's attachment fixes the missing routing entry, which is the actual root cause.</p>", "<p>An internet gateway route is irrelevant here — VPC-to-VPC traffic over Transit Gateway never traverses an IGW, and routing private RFC1918 traffic through an IGW would not work and is a nonsensical fix.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs a private hosted zone in Route 53 for the domain internal.example.com, used by resources in VPC-A. Via AWS Direct Connect, on-premises servers must be able to resolve records in internal.example.com, and resources inside VPC-A must be able to resolve names in the on-premises domain corp.example.com, which is hosted on the company's own DNS servers on-premises. Which solution meets BOTH requirements?", "prompt": {"question": "<p>A company runs a private hosted zone in Route 53 for the domain internal.example.com, used by resources in VPC-A. Via AWS Direct Connect, on-premises servers must be able to resolve records in internal.example.com, and resources inside VPC-A must be able to resolve names in the on-premises domain corp.example.com, which is hosted on the company's own DNS servers on-premises. Which solution meets BOTH requirements?</p>", "answers": ["<p>Create only a Route 53 Resolver inbound endpoint in VPC-A and configure on-premises DNS servers to forward all corp.example.com queries to it</p>", "<p>Create a Route 53 Resolver outbound endpoint in VPC-A with a forwarding rule for corp.example.com pointing to the on-premises DNS servers, and a Route 53 Resolver inbound endpoint in VPC-A that on-premises servers query for internal.example.com</p>", "<p>Migrate internal.example.com to a Route 53 public hosted zone and configure on-premises DNS servers to use conditional forwarding to the public DNS servers</p>", "<p>Create only a Route 53 Resolver outbound endpoint in VPC-A with a forwarding rule for corp.example.com, and rely on the VPC's default DNS resolver (AmazonProvidedDNS) to answer on-premises queries for internal.example.com</p>"], "feedbacks": ["<p>An inbound endpoint alone only allows on-premises servers to query into the VPC; it does nothing to let VPC-A resources resolve corp.example.com on-premises, so the second requirement is unmet.</p>", "<p>Hybrid DNS resolution requires both endpoint types: a Resolver inbound endpoint lets on-premises DNS servers send queries into the VPC to resolve records in the private hosted zone (internal.example.com), while a Resolver outbound endpoint with a forwarding rule lets resources in the VPC send queries for corp.example.com out to the on-premises DNS servers over Direct Connect. Only having both endpoints configured satisfies both directions of resolution described in the scenario.</p>", "<p>Public hosted zones are for internet-resolvable public DNS records; a private hosted zone's records are not resolvable via public DNS, and migrating them to public would expose internal names publicly while still not solving the on-premises-to-VPC lookup requirement correctly.</p>", "<p>The default AmazonProvidedDNS resolver at the VPC+2 address only answers queries from within the VPC using VPC-attached private/public zones; it cannot be queried by on-premises servers directly over Direct Connect, so on-premises resolution of internal.example.com would still fail without an inbound endpoint.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs a fault-tolerant batch analytics job on a diversified EC2 Fleet spanning 15 different instance types and sizes across two Availability Zones. The team wants to run entirely on Spot Instances, minimize hourly cost, but also reduce interruption frequency compared to simply picking whichever pools are cheapest at request time. Which Spot allocation strategy should they configure on the Fleet?", "prompt": {"question": "<p>A company runs a fault-tolerant batch analytics job on a diversified EC2 Fleet spanning 15 different instance types and sizes across two Availability Zones. The team wants to run entirely on Spot Instances, minimize hourly cost, but also reduce interruption frequency compared to simply picking whichever pools are cheapest at request time. Which Spot allocation strategy should they configure on the Fleet?</p>", "answers": ["<p>lowest-price</p>", "<p>diversified</p>", "<p>capacity-optimized</p>", "<p>price-capacity-optimized</p>"], "feedbacks": ["<p>lowest-price only considers price and can concentrate capacity in shallow pools, increasing interruption frequency even though it may look cheapest on paper.</p>", "<p>diversified is not a valid Spot allocation strategy value in this context; it is a description of spreading requests across pools, not an allocation-strategy setting.</p>", "<p>capacity-optimized reduces interruptions well but does not factor in price, so it can select pools that are deeper but more expensive than necessary.</p>", "<p>price-capacity-optimized selects Spot pools that have both sufficient available capacity (reducing interruption risk) and low price, giving the best balance of cost and reliability across a large, diversified fleet. AWS recommends it as the default strategy for most Spot workloads.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs steady-state EC2 usage that totals a consistent 200 hours/day of compute, but the mix of instance families changes every few months as they migrate workloads between compute-optimized and memory-optimized families, and they also run workloads in multiple AWS Regions. They want the largest possible commitment discount while retaining the ability to shift instance family and Region without exchanging or modifying anything. Which purchasing option should they use?", "prompt": {"question": "<p>A company runs steady-state EC2 usage that totals a consistent 200 hours/day of compute, but the mix of instance families changes every few months as they migrate workloads between compute-optimized and memory-optimized families, and they also run workloads in multiple AWS Regions. They want the largest possible commitment discount while retaining the ability to shift instance family and Region without exchanging or modifying anything. Which purchasing option should they use?</p>", "answers": ["<p>Standard Reserved Instances</p>", "<p>Convertible Reserved Instances</p>", "<p>EC2 Instance Savings Plans</p>", "<p>Compute Savings Plans</p>"], "feedbacks": ["<p>Standard RIs are locked to a specific instance family and Region; changing family requires selling on the Reserved Instance Marketplace or letting the term expire, which does not meet the flexibility requirement.</p>", "<p>Convertible RIs allow exchanging for a different configuration, but the exchange is a manual, discrete action performed by the customer — usage does not automatically shift across families and Regions the way Compute Savings Plans do.</p>", "<p>EC2 Instance Savings Plans give a higher discount than Compute Savings Plans but are committed to a specific instance family within a specific Region, which fails the requirement to shift family and Region freely.</p>", "<p>Compute Savings Plans automatically apply to any EC2 instance usage regardless of instance family, size, OS, tenancy, or Region (and even to Fargate and Lambda), making them the only option that gives commitment-discount coverage across changing families and Regions with zero manual exchange.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial trading application requires an EBS volume sustaining 90,000 IOPS with sub-millisecond average latency for its transaction log. Which EBS configuration meets this requirement?", "prompt": {"question": "<p>A financial trading application requires an EBS volume sustaining 90,000 IOPS with sub-millisecond average latency for its transaction log. Which EBS configuration meets this requirement?</p>", "answers": ["<p>io2 Block Express volume</p>", "<p>gp3 volume with provisioned IOPS increased to the maximum</p>", "<p>io1 volume attached to a Nitro-based instance</p>", "<p>io2 volume in a non-Block Express configuration</p>"], "feedbacks": ["<p>io2 Block Express is the only EBS option that scales up to 256,000 IOPS and 4,000 MB/s throughput while delivering sub-millisecond average latency, making it the only choice that satisfies both the 90,000 IOPS requirement and the sub-millisecond latency SLA.</p>", "<p>gp3 volumes cap out at 16,000 IOPS regardless of how much you provision, far below the 90,000 IOPS requirement.</p>", "<p>io1 volumes max out at 64,000 IOPS even on Nitro-based instances, which is insufficient for the 90,000 IOPS requirement.</p>", "<p>Standard io2 (non-Block Express) also caps at 64,000 IOPS and 1,000 MB/s; only the Block Express variant raises the ceiling high enough and guarantees sub-millisecond latency.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization has tagged all of its EC2 instances and RDS databases with a 'CostCenter' key for the past three months, but AWS Cost Explorer still does not offer 'CostCenter' as a filter or group-by dimension. Billing data confirms the tags exist on the resources. What is the MOST likely cause and correct fix?", "prompt": {"question": "<p>An organization has tagged all of its EC2 instances and RDS databases with a 'CostCenter' key for the past three months, but AWS Cost Explorer still does not offer 'CostCenter' as a filter or group-by dimension. Billing data confirms the tags exist on the resources. What is the MOST likely cause and correct fix?</p>", "answers": ["<p>Cost Explorer only supports AWS-generated tags, so a custom tag like 'CostCenter' can never be used for cost grouping</p>", "<p>The tags were applied after resource creation, and tags applied post-launch are permanently excluded from all billing tools</p>", "<p>IAM permissions for the billing service role are insufficient, so Cost Explorer cannot read the tag metadata from the resources</p>", "<p>Cost allocation tags must be manually activated on the Cost allocation tags page in Billing and Cost Management; the team never activated the 'CostCenter' tag</p>"], "feedbacks": ["<p>Cost Explorer fully supports user-defined tags as cost allocation tags once activated; this is a core, commonly tested feature, not a limitation.</p>", "<p>Tags applied after launch are fully usable for cost allocation once activated — timing of tag application relative to launch does not permanently exclude them from billing tools.</p>", "<p>Cost Explorer's ability to read tags is a billing data pipeline feature controlled by tag activation, not an IAM permissions issue on a service role.</p>", "<p>User-defined cost allocation tags must be explicitly activated in the Billing and Cost Management console before they appear in Cost Explorer, Budgets, or the Cost and Usage Report. Activation can take up to 24 hours to reflect in new billing data, but tags applied and never activated will never show up as a filter dimension.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A media company stores application access logs in S3. Access patterns are highly unpredictable: some log files are read dozens of times within a day of creation, others are never accessed again for over six months, and there is no way to know in advance which pattern a given file will follow. The team wants to minimize storage cost automatically without writing custom lifecycle rules and without incurring per-GB retrieval fees when files are unexpectedly accessed again. Which S3 storage class should they use?", "prompt": {"question": "<p>A media company stores application access logs in S3. Access patterns are highly unpredictable: some log files are read dozens of times within a day of creation, others are never accessed again for over six months, and there is no way to know in advance which pattern a given file will follow. The team wants to minimize storage cost automatically without writing custom lifecycle rules and without incurring per-GB retrieval fees when files are unexpectedly accessed again. Which S3 storage class should they use?</p>", "answers": ["<p>S3 Intelligent-Tiering</p>", "<p>S3 Standard-Infrequent Access</p>", "<p>S3 One Zone-Infrequent Access</p>", "<p>S3 Glacier Instant Retrieval</p>"], "feedbacks": ["<p>S3 Intelligent-Tiering automatically moves objects between frequent, infrequent, and (optionally) archive access tiers based on actual access patterns, with no retrieval fees and no need for manual lifecycle policies — exactly matching an unpredictable access pattern where the team cannot predict which objects will be re-accessed.</p>", "<p>S3 Standard-IA charges a per-GB retrieval fee every time an object is accessed, which directly violates the requirement to avoid retrieval fees on unexpectedly accessed files.</p>", "<p>S3 One Zone-IA also charges retrieval fees and additionally stores data in only one Availability Zone, reducing durability guarantees — it does not solve the unpredictability problem either.</p>", "<p>S3 Glacier Instant Retrieval charges retrieval fees and is intended for archival data accessed rarely (roughly once a quarter or less), not data with highly variable, sometimes-frequent access.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}]}, {"name": "CompTIA Network+ Practice Test 1", "cid": 7305515, "duration": 90, "pass_percent": 72, "questions": [{"assessment_type": "multiple-choice", "question_plain": "A network administrator assigns the subnet 192.168.10.0/27 to a department. How many usable host addresses are available in this subnet?", "prompt": {"question": "<p>A network administrator assigns the subnet 192.168.10.0/27 to a department. How many usable host addresses are available in this subnet?</p>", "answers": ["<p>14</p>", "<p>62</p>", "<p>126</p>", "<p>30</p>"], "feedbacks": ["<p>14 usable addresses corresponds to a /28 subnet (16 total addresses minus network/broadcast), not /27.</p>", "<p>62 usable addresses corresponds to a /26 subnet (64 total addresses minus network/broadcast), not /27.</p>", "<p>126 usable addresses corresponds to a /25 subnet (128 total addresses minus network/broadcast), not /27.</p>", "<p>A /27 mask (255.255.255.224) provides 32 total addresses (2^5). Subtracting the network address and broadcast address leaves 30 usable host addresses.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A systems administrator needs to securely transfer files between two Linux servers, ensuring both the connection and the transferred data are encrypted. Which protocol and default port should be used?", "prompt": {"question": "<p>A systems administrator needs to securely transfer files between two Linux servers, ensuring both the connection and the transferred data are encrypted. Which protocol and default port should be used?</p>", "answers": ["<p>SFTP using port 22</p>", "<p>TFTP using port 69</p>", "<p>FTP using port 21</p>", "<p>SMTP using port 25</p>"], "feedbacks": ["<p>SFTP (SSH File Transfer Protocol) runs over SSH on port 22, which encrypts both the control channel and the file data, meeting the encryption requirement.</p>", "<p>TFTP on port 69 is a lightweight, connectionless protocol with no authentication or encryption at all, typically used for booting devices.</p>", "<p>FTP on port 21 transmits both credentials and file data in cleartext, offering no encryption.</p>", "<p>SMTP on port 25 is used for sending email, not for file transfer between servers.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "Which IPv6 address type is automatically assigned to every interface and is used only for communication within the local network segment, never routed beyond it?", "prompt": {"question": "<p>Which IPv6 address type is automatically assigned to every interface and is used only for communication within the local network segment, never routed beyond it?</p>", "answers": ["<p>Link-local address</p>", "<p>Global unicast address</p>", "<p>Multicast address</p>", "<p>Unique local address</p>"], "feedbacks": ["<p>Link-local addresses (fe80::/10) are automatically generated on every IPv6-enabled interface and are confined to the local link; routers never forward packets with a link-local source or destination.</p>", "<p>Global unicast addresses are routable across the internet, the IPv6 equivalent of public IPv4 addresses, so they are not restricted to the local segment.</p>", "<p>Multicast addresses (ff00::/8) are used to deliver a packet to a group of interfaces, not for standard local-only unicast communication.</p>", "<p>Unique local addresses (fc00::/7) are used for private addressing within an organization but can be routed across multiple internal subnets, unlike link-local addresses.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A cloud provider is designing a data center network that must provide predictable, low-latency paths between any two servers, with every leaf switch directly connected to every spine switch. Which topology BEST meets this requirement?", "prompt": {"question": "<p>A cloud provider is designing a data center network that must provide predictable, low-latency paths between any two servers, with every leaf switch directly connected to every spine switch. Which topology BEST meets this requirement?</p>", "answers": ["<p>Three-tier hierarchical topology</p>", "<p>Spine-leaf topology</p>", "<p>Ring topology</p>", "<p>Star topology</p>"], "feedbacks": ["<p>Three-tier hierarchical topology (core, distribution, access) introduces additional hops and less predictable latency for server-to-server traffic compared to spine-leaf.</p>", "<p>Spine-leaf topology connects every leaf switch to every spine switch, creating a non-blocking, predictable-latency fabric ideal for east-west traffic in modern data centers and cloud environments.</p>", "<p>Ring topology relies on a circular connection path that is not used in modern high-performance data centers and creates single points of failure without redundant fabrics.</p>", "<p>Star topology has a single central connection point, creating a bottleneck and lacking the full-mesh redundancy needed between leaf and spine switches.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company wants to migrate its email and collaboration platform to the cloud without managing any underlying servers, operating systems, or application code. Which cloud service model BEST fits this requirement?", "prompt": {"question": "<p>A company wants to migrate its email and collaboration platform to the cloud without managing any underlying servers, operating systems, or application code. Which cloud service model BEST fits this requirement?</p>", "answers": ["<p>Software as a Service (SaaS)</p>", "<p>Infrastructure as a Service (IaaS)</p>", "<p>Platform as a Service (PaaS)</p>", "<p>Community cloud deployment</p>"], "feedbacks": ["<p>SaaS delivers a fully managed, ready-to-use application (such as email and collaboration tools) over the internet, with the provider handling all servers, OS, and application code.</p>", "<p>IaaS provides virtualized compute, storage, and networking, but the customer would still need to install and manage the OS and application themselves.</p>", "<p>PaaS provides a platform for developers to deploy their own application code, requiring the company to manage the application layer rather than just consuming a finished product.</p>", "<p>Community cloud is a deployment model describing who shares the infrastructure, not a service model describing what layer of the stack is managed, so it does not answer the question.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A workstation displays an IP address of 169.254.34.12 with a subnet mask of 255.255.0.0 and cannot communicate with any other devices on the network. What does this address indicate?", "prompt": {"question": "<p>A workstation displays an IP address of 169.254.34.12 with a subnet mask of 255.255.0.0 and cannot communicate with any other devices on the network. What does this address indicate?</p>", "answers": ["<p>The workstation received a properly configured static IP address</p>", "<p>The workstation obtained a valid address from a DHCP relay agent</p>", "<p>The workstation failed to receive a DHCP-assigned address and self-assigned an APIPA address</p>", "<p>The workstation is configured to use IPv6 tunneling</p>"], "feedbacks": ["<p>A properly configured static IP address would not fall in the reserved 169.254.0.0/16 APIPA range; an administrator would not assign this range manually for normal operation.</p>", "<p>A DHCP relay agent forwards DHCP requests to a server on another subnet and would result in a valid address from that server's scope, not an APIPA address.</p>", "<p>Addresses in the 169.254.0.0/16 range are Automatic Private IP Addressing (APIPA) addresses, which a Windows host self-assigns when it cannot reach a DHCP server, indicating a DHCP failure or connectivity issue upstream.</p>", "<p>IPv6 tunneling addresses use entirely different formats (such as 6to4 or Teredo prefixes) and are unrelated to the IPv4 169.254.x.x APIPA range shown here.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A network administrator must design a subnet that accommodates exactly 30 usable host addresses while wasting as few addresses as possible. Which subnet mask should be applied?", "prompt": {"question": "<p>A network administrator must design a subnet that accommodates exactly 30 usable host addresses while wasting as few addresses as possible. Which subnet mask should be applied?</p>", "answers": ["<p>255.255.255.224 (/27)</p>", "<p>255.255.255.192 (/26)</p>", "<p>255.255.255.240 (/28)</p>", "<p>255.255.255.128 (/25)</p>"], "feedbacks": ["<p>A /27 mask (255.255.255.224) provides 32 total addresses, 30 of which are usable after subtracting the network and broadcast addresses — an exact fit for the requirement with minimal waste.</p>", "<p>/26 (255.255.255.192) yields 62 usable hosts, more than double what's needed, wasting address space.</p>", "<p>/28 (255.255.255.240) yields only 14 usable hosts, which does not meet the 30-host requirement.</p>", "<p>/25 (255.255.255.128) yields 126 usable hosts, far more than required and highly wasteful for this subnet.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company wants to transfer files to a remote server using strong encryption while opening only a single firewall port, leveraging existing SSH infrastructure for authentication. Which protocol should be implemented?", "prompt": {"question": "<p>A company wants to transfer files to a remote server using strong encryption while opening only a single firewall port, leveraging existing SSH infrastructure for authentication. Which protocol should be implemented?</p>", "answers": ["<p>FTP</p>", "<p>TFTP</p>", "<p>FTPS</p>", "<p>SFTP</p>"], "feedbacks": ["<p>FTP (port 21 plus dynamic data ports) transmits credentials and data in plaintext and requires multiple ports, failing both the security and single-port requirements.</p>", "<p>TFTP (port 69/UDP) has no authentication or encryption and is used for simple file transfers like booting devices, not secure transfers.</p>", "<p>FTPS uses TLS rather than SSH and typically requires a separate control port (990) plus additional data ports, so it does not meet the single-port, SSH-based requirement.</p>", "<p>SFTP (SSH File Transfer Protocol) runs entirely over a single SSH connection on port 22, providing encryption and authentication without requiring additional data ports.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Which IPv6 address type is automatically configured on every interface, used only for communication with devices on the same local subnet, and is never forwarded by routers?", "prompt": {"question": "<p>Which IPv6 address type is automatically configured on every interface, used only for communication with devices on the same local subnet, and is never forwarded by routers?</p>", "answers": ["<p>Unique local address</p>", "<p>Global unicast address</p>", "<p>Multicast address</p>", "<p>Link-local address</p>"], "feedbacks": ["<p>Unique local addresses (fc00::/7) are the IPv6 equivalent of private addressing and can be routed within an organization's internal network, unlike link-local addresses.</p>", "<p>Global unicast addresses are publicly routable on the internet, the opposite of the local-only scope described.</p>", "<p>Multicast addresses are used to deliver traffic to a group of interfaces, not for standard point-to-point local subnet communication.</p>", "<p>Link-local addresses (fe80::/10) are automatically assigned to every IPv6 interface and are confined to the local link — routers never forward them beyond the local subnet.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A data center architect is designing a network with heavy server-to-server (east-west) traffic that requires predictable, low-latency paths between any two devices. Which topology BEST meets this requirement?", "prompt": {"question": "<p>A data center architect is designing a network with heavy server-to-server (east-west) traffic that requires predictable, low-latency paths between any two devices. Which topology BEST meets this requirement?</p>", "answers": ["<p>Full mesh topology</p>", "<p>Star topology</p>", "<p>Three-tier hierarchical topology</p>", "<p>Spine-leaf topology</p>"], "feedbacks": ["<p>A full mesh topology becomes impractical to cable and manage at data center scale, as the number of links grows exponentially with device count.</p>", "<p>A star topology relies on a single central point of connectivity, creating a bottleneck and single point of failure unsuitable for high east-west traffic.</p>", "<p>Three-tier hierarchical (core-distribution-access) topology is optimized for north-south (client-to-server) traffic and introduces variable, often higher, latency for server-to-server communication.</p>", "<p>Spine-leaf topology connects every leaf switch to every spine switch, guaranteeing that any two leaf-connected devices are always exactly two hops apart, delivering consistent low latency for east-west traffic common in modern data centers.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A network technician installs three switches in a redundant triangle topology to provide fault tolerance. Shortly after, users report a broadcast storm and severe network slowdowns. Which action should the technician take to BEST resolve this issue while preserving redundant links?", "prompt": {"question": "<p>A network technician installs three switches in a redundant triangle topology to provide fault tolerance. Shortly after, users report a broadcast storm and severe network slowdowns. Which action should the technician take to BEST resolve this issue while preserving redundant links?</p>", "answers": ["<p>Enable Spanning Tree Protocol (STP)</p>", "<p>Configure static routes to prevent loops</p>", "<p>Disable trunking on all switch ports</p>", "<p>Enable port mirroring on the uplink ports</p>"], "feedbacks": ["<p>STP detects redundant Layer 2 paths between switches and places one or more ports into a blocking state to prevent a switching loop, while keeping the redundant physical links available as backups if the primary path fails.</p>", "<p>Static routes are a Layer 3 routing concept and have no effect on a Layer 2 switching loop between switches.</p>", "<p>Disabling trunking would break VLAN propagation across switches and does not address the underlying loop; it also removes needed functionality rather than fixing the storm.</p>", "<p>Port mirroring copies traffic for monitoring/analysis purposes and does nothing to prevent or stop a broadcast storm.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A network engineer must connect two buildings located approximately 8 kilometers apart using a 10 Gigabit Ethernet single-mode fiber link. Which transceiver type BEST meets this requirement?", "prompt": {"question": "<p>A network engineer must connect two buildings located approximately 8 kilometers apart using a 10 Gigabit Ethernet single-mode fiber link. Which transceiver type BEST meets this requirement?</p>", "answers": ["<p>SFP+ SR (multimode, ~300m range)</p>", "<p>SFP+ LR (single-mode, up to 10km range)</p>", "<p>SFP+ ZR (single-mode, ~80km range)</p>", "<p>SFP+ ER (single-mode, up to 40km range)</p>"], "feedbacks": ["<p>SFP+ SR is designed for multimode fiber with a maximum range of about 300 meters and cannot reliably span 8km.</p>", "<p>SFP+ LR transceivers are rated for single-mode fiber runs up to 10km, which comfortably covers the 8km distance at the lowest cost and power consumption suitable for the requirement.</p>", "<p>SFP+ ZR supports up to 80km and is significantly more expensive than needed for an 8km link, making it an unnecessary overprovision.</p>", "<p>SFP+ ER supports up to 40km, which also exceeds requirements and costs more than the appropriately-scoped LR transceiver.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A small business is assigned a single public IPv4 address by its ISP but has 40 internal devices that all need simultaneous internet access. Which technology allows all internal devices to share the single public IP address at the same time?", "prompt": {"question": "<p>A small business is assigned a single public IPv4 address by its ISP but has 40 internal devices that all need simultaneous internet access. Which technology allows all internal devices to share the single public IP address at the same time?</p>", "answers": ["<p>Port Address Translation (PAT)</p>", "<p>Static NAT</p>", "<p>Dynamic NAT</p>", "<p>VLAN trunking</p>"], "feedbacks": ["<p>PAT (also called NAT overload) maps multiple internal private IP addresses to a single public IP address by using unique source port numbers to distinguish each session, allowing many devices to share one public address simultaneously.</p>", "<p>Static NAT creates a fixed one-to-one mapping between a single private and single public address, which does not scale to 40 devices sharing one IP.</p>", "<p>Dynamic NAT maps private addresses to a pool of public addresses on a one-to-one basis; without PAT, once the pool is exhausted no further translations occur, and it does not allow many devices to share a single address.</p>", "<p>VLAN trunking carries traffic for multiple VLANs over a single link between switches and has no relationship to address translation or sharing a public IP.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An administrator is configuring a Wi-Fi 6E access point in the 6GHz band and wants to select the maximum channel width supported to achieve the highest possible throughput. Which channel width should be configured?", "prompt": {"question": "<p>An administrator is configuring a Wi-Fi 6E access point in the 6GHz band and wants to select the maximum channel width supported to achieve the highest possible throughput. Which channel width should be configured?</p>", "answers": ["<p>20MHz</p>", "<p>40MHz</p>", "<p>80MHz</p>", "<p>160MHz</p>"], "feedbacks": ["<p>20MHz is the narrowest supported channel width and provides the lowest throughput, not the maximum available.</p>", "<p>40MHz is wider than 20MHz but still well below the maximum channel width supported by Wi-Fi 6E.</p>", "<p>80MHz is supported but is not the maximum channel width available; 160MHz provides greater throughput and is supported in the 6GHz band.</p>", "<p>Wi-Fi 6E in the 6GHz band supports channel widths up to 160MHz, and because the 6GHz spectrum has many more non-overlapping channels available than 2.4GHz or 5GHz, multiple non-overlapping 160MHz channels can be used simultaneously for maximum throughput.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Which statement BEST differentiates static routing from dynamic routing?", "prompt": {"question": "<p>Which statement BEST differentiates static routing from dynamic routing?</p>", "answers": ["<p>Static routes automatically adjust to topology changes while dynamic routes require manual updates</p>", "<p>Static routing requires more CPU overhead than dynamic routing protocols</p>", "<p>Static routes are manually configured and do not adapt to topology changes; dynamic routes use routing protocols to automatically learn and adjust to topology changes</p>", "<p>Dynamic routing only operates over IPv6 networks</p>"], "feedbacks": ["<p>This reverses the definitions — static routes do not adapt automatically, and dynamic routing is the one that adjusts without manual intervention.</p>", "<p>Dynamic routing protocols generally consume more CPU and memory than static routes because they must continuously process updates and recalculate paths; static routing has lower overhead.</p>", "<p>Static routes are entered manually by an administrator and remain fixed until changed by hand, while dynamic routing protocols (such as OSPF, EIGRP, or BGP) exchange routing information between routers and automatically recalculate paths when the topology changes.</p>", "<p>Both static and dynamic routing work with either IPv4 or IPv6; dynamic routing is not restricted to IPv6 only.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company's public-facing web application runs on five backend servers. Monitoring shows that two servers are consistently at 90% CPU utilization while the other three remain nearly idle, even though all servers have identical specifications. Which network appliance should be deployed to resolve this issue?", "prompt": {"question": "<p>A company's public-facing web application runs on five backend servers. Monitoring shows that two servers are consistently at 90% CPU utilization while the other three remain nearly idle, even though all servers have identical specifications. Which network appliance should be deployed to resolve this issue?</p>", "answers": ["<p>Firewall</p>", "<p>Proxy server</p>", "<p>Load balancer</p>", "<p>Wireless access point</p>"], "feedbacks": ["<p>A firewall filters traffic based on security policy and does not distribute traffic loads across multiple servers.</p>", "<p>A proxy server can forward or cache client requests on behalf of servers but is not specifically designed to evenly distribute traffic across multiple identical backend servers the way a dedicated load balancer is.</p>", "<p>A load balancer distributes incoming client requests across all available backend servers based on algorithms such as round-robin or least connections, ensuring even resource utilization and preventing any single server from becoming overloaded.</p>", "<p>A wireless access point provides Wi-Fi connectivity for client devices and has no role in distributing traffic among wired backend servers.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A network administrator connects two access switches together with two separate redundant Ethernet cables to eliminate a single point of failure. Shortly afterward, users report intermittent outages, and switch MAC address tables show the same host addresses flapping between different ports. Which technology should be enabled on the switches to eliminate the resulting loop?", "prompt": {"question": "<p>A network administrator connects two access switches together with two separate redundant Ethernet cables to eliminate a single point of failure. Shortly afterward, users report intermittent outages, and switch MAC address tables show the same host addresses flapping between different ports. Which technology should be enabled on the switches to eliminate the resulting loop?</p>", "answers": ["<p>Spanning Tree Protocol (STP)</p>", "<p>Dynamic NAT</p>", "<p>802.1Q VLAN trunking</p>", "<p>OSPF</p>"], "feedbacks": ["<p>STP (or RSTP) detects the redundant Layer 2 path between the two switches and places one link in a blocking state, preventing the broadcast storm and MAC flapping caused by the loop while keeping the second link available as a backup path.</p>", "<p>NAT translates private to public IP addresses at Layer 3 and has no role in preventing Layer 2 switching loops.</p>", "<p>802.1Q trunking allows multiple VLANs to traverse a single link but does nothing to prevent a physical loop between switches — it can actually make the storm worse by flooding traffic across all tagged VLANs.</p>", "<p>OSPF is a Layer 3 dynamic routing protocol used between routers; it has no mechanism to detect or block a Layer 2 switching loop.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A data center needs to connect two switches located 300 meters apart using 10GBASE-SR over OM3 multimode fiber. Which transceiver type should be installed in both switch ports?", "prompt": {"question": "<p>A data center needs to connect two switches located 300 meters apart using 10GBASE-SR over OM3 multimode fiber. Which transceiver type should be installed in both switch ports?</p>", "answers": ["<p>SFP+ LR</p>", "<p>SFP+ SR</p>", "<p>QSFP+</p>", "<p>RJ45 10GBASE-T module</p>"], "feedbacks": ["<p>SFP+ LR is designed for 10GBASE-LR over single-mode fiber with a much longer reach (up to 10 km), but it is not rated for multimode fiber and is unnecessarily costly for this short distance.</p>", "<p>SFP+ SR (short range) is designed for 10GBASE-SR over multimode fiber and supports distances up to 300 meters on OM3 cable, exactly matching the scenario's requirements.</p>", "<p>QSFP+ modules are built for 40 Gbps Ethernet (or four-lane breakout), not standard 10 Gbps single-lane ports, so it would not fit a 10GbE switch port in this scenario.</p>", "<p>10GBASE-T RJ45 modules run over copper twisted-pair cabling with a maximum reliable distance around 55–100 meters, and the scenario specifies a fiber connection, not copper.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization deploys Wi-Fi 6E access points specifically to reduce co-channel interference caused by legacy Wi-Fi devices. Which frequency band is exclusive to Wi-Fi 6E and unavailable on earlier Wi-Fi standards?", "prompt": {"question": "<p>An organization deploys Wi-Fi 6E access points specifically to reduce co-channel interference caused by legacy Wi-Fi devices. Which frequency band is exclusive to Wi-Fi 6E and unavailable on earlier Wi-Fi standards?</p>", "answers": ["<p>2.4 GHz</p>", "<p>60 GHz</p>", "<p>6 GHz</p>", "<p>5 GHz</p>"], "feedbacks": ["<p>The 2.4 GHz band has been used since 802.11b and is shared by nearly every legacy Wi-Fi device, making it the opposite of interference-free.</p>", "<p>60 GHz is used by the WiGig standard (802.11ad/ay) for very short-range, high-throughput links, not by Wi-Fi 6E.</p>", "<p>Wi-Fi 6E extends the 802.11ax standard into the newly opened 6 GHz band, which was not available to any earlier Wi-Fi standard, giving it significantly more clean, non-overlapping channels and freedom from legacy device interference.</p>", "<p>5 GHz has been available since 802.11a and is used extensively by 802.11n/ac/ax devices, so it is not exclusive to Wi-Fi 6E.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A network administrator needs to identify which applications are consuming the most bandwidth across multiple WAN links over the past 30 days without capturing every packet. Which technology should be used?", "prompt": {"question": "<p>A network administrator needs to identify which applications are consuming the most bandwidth across multiple WAN links over the past 30 days without capturing every packet. Which technology should be used?</p>", "answers": ["<p>SNMP polling of interface counters</p>", "<p>Syslog message collection</p>", "<p>Full packet capture at each WAN link</p>", "<p>NetFlow/IPFIX flow data</p>"], "feedbacks": ["<p>SNMP polling reports device/interface-level statistics like utilization and errors, but does not break traffic down by application or conversation.</p>", "<p>Syslog delivers event and status log messages, not traffic volume or flow statistics.</p>", "<p>Full packet capture at every link for 30 days would generate massive storage and processing overhead and is not scalable for ongoing trend analysis.</p>", "<p>Flow data (NetFlow/IPFIX) exports per-conversation summaries (source, destination, application, bytes) with low overhead, making it ideal for long-term traffic trend and top-talker analysis.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Which SNMP version must be deployed to meet a security requirement for authenticated and encrypted network management traffic?", "prompt": {"question": "<p>Which SNMP version must be deployed to meet a security requirement for authenticated and encrypted network management traffic?</p>", "answers": ["<p>SNMPv1</p>", "<p>SNMPv3</p>", "<p>SNMPv2c</p>", "<p>SNMP configured with trap-only messages</p>"], "feedbacks": ["<p>SNMPv1 uses plaintext community strings with no authentication or encryption.</p>", "<p>SNMPv3 introduces the User-based Security Model (USM), providing authentication (e.g., SHA) and encryption (e.g., AES) of management traffic, which v1 and v2c lack.</p>", "<p>SNMPv2c also relies on plaintext community strings and adds no security enhancements over v1.</p>", "<p>'Trap-only' describes a message type (unsolicited notifications), not an SNMP version, and does not address authentication or encryption requirements.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company requires that if the primary router fails, workstations continue using the same default gateway IP address without any manual reconfiguration. Which technology should be implemented?", "prompt": {"question": "<p>A company requires that if the primary router fails, workstations continue using the same default gateway IP address without any manual reconfiguration. Which technology should be implemented?</p>", "answers": ["<p>Spanning Tree Protocol (STP)</p>", "<p>Virtual Router Redundancy Protocol (VRRP)</p>", "<p>Link Aggregation Control Protocol (LACP)</p>", "<p>Border Gateway Protocol (BGP)</p>"], "feedbacks": ["<p>STP prevents Layer 2 loops in switched networks; it has no role in gateway IP redundancy.</p>", "<p>VRRP is a First Hop Redundancy Protocol (FHRP) that allows multiple routers to share a virtual IP address, so if the active/master router fails, a backup router seamlessly takes over the same gateway IP with no client reconfiguration.</p>", "<p>LACP aggregates multiple physical links into one logical link for bandwidth/redundancy between two devices, not gateway failover.</p>", "<p>BGP is a routing protocol used primarily between autonomous systems (e.g., ISPs); it does not provide a shared virtual gateway IP for end hosts.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization frequently experiences duplicate IP address conflicts and has no visibility into which subnets are nearing exhaustion. Which operational practice should be implemented?", "prompt": {"question": "<p>An organization frequently experiences duplicate IP address conflicts and has no visibility into which subnets are nearing exhaustion. Which operational practice should be implemented?</p>", "answers": ["<p>Implement an IP Address Management (IPAM) solution</p>", "<p>Increase the DHCP lease time on all scopes</p>", "<p>Enable port security on all access switches</p>", "<p>Deploy an additional syslog server</p>"], "feedbacks": ["<p>IPAM centrally tracks IP address allocation, subnet utilization, and reservations, preventing duplicate assignments and providing visibility into approaching exhaustion so subnets can be resized or reclaimed proactively.</p>", "<p>Increasing DHCP lease time does not resolve conflicts or provide visibility, and can worsen exhaustion by holding addresses longer.</p>", "<p>Port security restricts which MAC addresses can use a switch port; it does not track or manage IP address allocation.</p>", "<p>An additional syslog server improves log collection but does not provide IP address tracking or utilization reporting.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "What is the primary purpose of a defined rollback plan within a formal change management process?", "prompt": {"question": "<p>What is the primary purpose of a defined rollback plan within a formal change management process?</p>", "answers": ["<p>To document the approved change for audit purposes</p>", "<p>To calculate the SLA uptime percentage for the affected service</p>", "<p>To provide a tested procedure for reverting a change that causes unexpected issues</p>", "<p>To schedule the date and time of the next maintenance window</p>"], "feedbacks": ["<p>Documenting the approved change for audit is part of the change request record but is a separate deliverable from the rollback procedure.</p>", "<p>SLA uptime calculation is an operational metric unrelated to reverting a specific failed change.</p>", "<p>A rollback plan exists specifically to restore the network to its last known-good state quickly and reliably if an implemented change causes an outage or unintended behavior.</p>", "<p>Scheduling the maintenance window is a separate step in the change process that occurs before implementation, not part of the rollback procedure itself.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A network engineer wants VLAN configurations applied consistently across 50 switches, with the ability to version-control the configuration and redeploy it identically if a device is replaced. Which approach BEST achieves this?", "prompt": {"question": "<p>A network engineer wants VLAN configurations applied consistently across 50 switches, with the ability to version-control the configuration and redeploy it identically if a device is replaced. Which approach BEST achieves this?</p>", "answers": ["<p>Manually configure each switch individually via console access</p>", "<p>Rely on SNMP polling to detect configuration mismatches after they occur</p>", "<p>Use version-controlled configuration templates pushed to devices via automation scripts or APIs</p>", "<p>Use syslog to record configuration changes after they are made</p>"], "feedbacks": ["<p>Manual console configuration on 50 devices is slow, inconsistent, and highly prone to human error.</p>", "<p>SNMP polling can detect that a mismatch exists but does not create, standardize, or apply the correct configuration.</p>", "<p>This is an Infrastructure as Code approach: storing configuration templates in a version control system and deploying them via scripts/APIs ensures consistent, repeatable, and auditable configuration across many devices.</p>", "<p>Syslog only records that a change happened after the fact; it does not ensure the change was applied consistently or provide a way to redeploy it.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services company requires that all SNMP monitoring traffic use encrypted authentication and encrypted message payloads to meet regulatory compliance requirements. Which SNMP version should the administrator implement?", "prompt": {"question": "<p>A financial services company requires that all SNMP monitoring traffic use encrypted authentication and encrypted message payloads to meet regulatory compliance requirements. Which SNMP version should the administrator implement?</p>", "answers": ["<p>SNMPv1</p>", "<p>SNMPv2c</p>", "<p>RMON</p>", "<p>SNMPv3</p>"], "feedbacks": ["<p>SNMPv1 uses plaintext community strings for authentication and provides no encryption, making it unsuitable for regulated environments.</p>", "<p>SNMPv2c improved performance and added bulk retrieval but still uses plaintext community strings with no encryption support.</p>", "<p>RMON is a monitoring extension that defines additional MIB data for traffic analysis; it is not an SNMP version and does not provide authentication or encryption.</p>", "<p>SNMPv3 is the only version that supports both authentication (via hashed credentials, not plaintext community strings) and full message encryption, meeting the compliance requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company's disaster recovery plan calls for a secondary datacenter with partially configured servers and periodically synchronized data, enabling recovery within roughly 24 hours at a lower ongoing cost than a fully redundant facility. Which type of DR site does this describe?", "prompt": {"question": "<p>A company's disaster recovery plan calls for a secondary datacenter with partially configured servers and periodically synchronized data, enabling recovery within roughly 24 hours at a lower ongoing cost than a fully redundant facility. Which type of DR site does this describe?</p>", "answers": ["<p>Warm site</p>", "<p>Cold site</p>", "<p>Cloud site</p>", "<p>Hot site</p>"], "feedbacks": ["<p>A warm site has some hardware and connectivity already in place along with periodically updated data, allowing recovery in hours to about a day, at a cost between a hot site and a cold site.</p>", "<p>A cold site has only space, power, and basic infrastructure with no pre-configured servers or data, requiring days to weeks for recovery, not 24 hours.</p>", "<p>Cloud site is not a standard DR site classification tested on the exam; the standard categories are hot, warm, and cold sites.</p>", "<p>A hot site is fully redundant with real-time or near-real-time data replication, enabling near-immediate failover (minutes), which exceeds the cost and recovery time described in this scenario.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A network engineer wants to programmatically pull current interface configurations from dozens of switches, compare them against an approved baseline, and automatically open a change ticket whenever a deviation is found. Which approach BEST accomplishes this?", "prompt": {"question": "<p>A network engineer wants to programmatically pull current interface configurations from dozens of switches, compare them against an approved baseline, and automatically open a change ticket whenever a deviation is found. Which approach BEST accomplishes this?</p>", "answers": ["<p>Configure each switch to forward syslog messages to a central logging server</p>", "<p>Write a script that uses each device's API to pull configurations and integrates with the ticketing system</p>", "<p>Manually console into each switch on a scheduled basis and record findings in a spreadsheet</p>", "<p>Set SNMP trap thresholds on each switch to alert when CPU or memory usage spikes</p>"], "feedbacks": ["<p>Syslog forwarding centralizes event and error messages but does not retrieve full interface configurations or compare them against a baseline.</p>", "<p>This is a basic network automation task: using a scripting language and device APIs to programmatically retrieve configuration data, compare it to a baseline, and trigger an action (ticket creation) in another system such as a ticketing platform, without manual intervention.</p>", "<p>Manually consoling into each device is the opposite of automation, is not scalable across dozens of devices, and does not integrate with a ticketing system automatically.</p>", "<p>SNMP traps alert on threshold-based performance metrics like CPU or memory usage; they do not retrieve configuration data or perform baseline comparisons.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company's public-facing web servers are being flooded with traffic from thousands of distributed source IP addresses, causing legitimate customers to be unable to reach the site. The internal network team has already confirmed the servers themselves are not misconfigured. Which solution BEST mitigates this attack?", "prompt": {"question": "<p>A company's public-facing web servers are being flooded with traffic from thousands of distributed source IP addresses, causing legitimate customers to be unable to reach the site. The internal network team has already confirmed the servers themselves are not misconfigured. Which solution BEST mitigates this attack?</p>", "answers": ["<p>Increase the RAM and CPU allocation on each web server</p>", "<p>Route traffic through a cloud-based DDoS scrubbing/mitigation service</p>", "<p>Enable Spanning Tree Protocol on the core switches</p>", "<p>Configure port security with a maximum of one MAC address per port</p>"], "feedbacks": ["<p>Adding CPU/RAM addresses server capacity, not the flood of malicious traffic overwhelming bandwidth and connection tables — it doesn't scale against a real DDoS.</p>", "<p>A distributed flood from many source IPs targeting availability is a DDoS attack. Cloud-based scrubbing services absorb and filter volumetric traffic upstream before it reaches the network, which is the standard mitigation for this scale of attack.</p>", "<p>STP prevents Layer 2 loops and has nothing to do with volumetric traffic floods from external hosts.</p>", "<p>Port security limits MAC addresses on a local switchport and is irrelevant to internet-sourced distributed attacks.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A penetration tester demonstrates that a crafted frame with two stacked 802.1Q tags can hop from the native VLAN onto a victim VLAN on a trunk link. Which action BEST prevents this VLAN hopping technique?", "prompt": {"question": "<p>A penetration tester demonstrates that a crafted frame with two stacked 802.1Q tags can hop from the native VLAN onto a victim VLAN on a trunk link. Which action BEST prevents this VLAN hopping technique?</p>", "answers": ["<p>Enable PortFast on all trunk-facing switch interfaces</p>", "<p>Increase the number of VLANs configured on the switch</p>", "<p>Enable Rapid Spanning Tree Protocol network-wide</p>", "<p>Change the native VLAN to an unused VLAN ID and disable Dynamic Trunking Protocol on access ports</p>"], "feedbacks": ["<p>PortFast is meant for end-device access ports to skip STP listening/learning states quickly; it does not address tagging or trunk negotiation.</p>", "<p>Adding more VLANs does nothing to stop the tagging manipulation technique itself.</p>", "<p>RSTP speeds up convergence after topology changes but has no relationship to 802.1Q tag manipulation.</p>", "<p>Double-tagging VLAN hopping relies on the native VLAN being untagged on the trunk and on ports negotiating trunking automatically. Moving the native VLAN off the default/data VLAN and disabling DTP so ports don't auto-negotiate trunk status closes both prerequisites for the attack.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "An administrator discovers an unauthorized device on the network is issuing IP address leases to clients, causing intermittent connectivity issues. Which switch feature should be enabled to prevent unauthorized devices from acting as a DHCP server?", "prompt": {"question": "<p>An administrator discovers an unauthorized device on the network is issuing IP address leases to clients, causing intermittent connectivity issues. Which switch feature should be enabled to prevent unauthorized devices from acting as a DHCP server?</p>", "answers": ["<p>802.1X port-based authentication</p>", "<p>Static port security with sticky MAC addresses</p>", "<p>DHCP snooping</p>", "<p>Access control list applied to the management VLAN</p>"], "feedbacks": ["<p>802.1X authenticates devices before granting network access but doesn't specifically inspect or filter DHCP server traffic.</p>", "<p>Port security restricts which MAC addresses can connect to a port; it doesn't distinguish or block DHCP server behavior from an already-permitted MAC.</p>", "<p>DHCP snooping classifies switch ports as trusted or untrusted and blocks DHCP server responses (OFFER/ACK) from untrusted ports, directly preventing rogue DHCP servers from handing out leases.</p>", "<p>An ACL on the management VLAN controls administrative access to devices, not DHCP traffic on client VLANs.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A network engineer configures port security on an access switchport. When a violation occurs, the engineer wants the port to be completely disabled and require manual administrative intervention (no auto-recovery) before it can pass traffic again. Which violation mode should be configured?", "prompt": {"question": "<p>A network engineer configures port security on an access switchport. When a violation occurs, the engineer wants the port to be completely disabled and require manual administrative intervention (no auto-recovery) before it can pass traffic again. Which violation mode should be configured?</p>", "answers": ["<p>Protect</p>", "<p>Restrict</p>", "<p>Aging</p>", "<p>Shutdown</p>"], "feedbacks": ["<p>Protect mode silently drops traffic from violating MAC addresses but keeps the port up with no logging and no shutdown.</p>", "<p>Restrict mode drops violating traffic and logs the event/increments violation counters, but the port stays up and continues passing traffic from allowed MACs.</p>", "<p>Aging is not a violation mode; it's a port security setting that controls how long secure MAC address entries remain in the table.</p>", "<p>The 'shutdown' violation mode puts the port into an err-disabled state on a violation, dropping all traffic and requiring an administrator to manually re-enable it (or configure err-disable auto-recovery separately).</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Which statement BEST describes the core operating principle of a Zero Trust security model?", "prompt": {"question": "<p>Which statement BEST describes the core operating principle of a Zero Trust security model?</p>", "answers": ["<p>Traffic originating inside the corporate LAN is automatically trusted and requires no further verification</p>", "<p>A single perimeter firewall is sufficient to protect all internal resources</p>", "<p>Every access request is verified and authenticated regardless of whether it originates inside or outside the network perimeter</p>", "<p>VLAN membership alone determines which resources a device is allowed to access</p>"], "feedbacks": ["<p>This describes the traditional perimeter-based trust model that Zero Trust specifically replaces.</p>", "<p>Zero Trust assumes the perimeter can be breached, so relying on a single perimeter firewall contradicts the model's defense-in-depth approach.</p>", "<p>Zero Trust operates on 'never trust, always verify' — every user, device, and request must be continuously authenticated and authorized, regardless of network location, eliminating implicit trust based on network position.</p>", "<p>Zero Trust evaluates identity, device posture, and context per request rather than granting trust based solely on network segment or VLAN.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "Users on a LAN report that their traffic to the default gateway is intermittently being intercepted and read by an unauthorized host that has poisoned the local ARP tables of nearby devices. Which switch-level feature should be implemented to prevent this on-path attack?", "prompt": {"question": "<p>Users on a LAN report that their traffic to the default gateway is intermittently being intercepted and read by an unauthorized host that has poisoned the local ARP tables of nearby devices. Which switch-level feature should be implemented to prevent this on-path attack?</p>", "answers": ["<p>VLAN Trunking Protocol</p>", "<p>Spanning Tree PortFast</p>", "<p>Link Aggregation Control Protocol</p>", "<p>Dynamic ARP Inspection</p>"], "feedbacks": ["<p>VTP synchronizes VLAN database information across switches and has no role in validating ARP traffic.</p>", "<p>PortFast only affects how quickly an access port transitions to forwarding state in STP; it doesn't inspect ARP traffic.</p>", "<p>LACP bundles multiple physical links into a logical one for redundancy/throughput and has no security inspection function.</p>", "<p>ARP poisoning enables on-path (MITM) attacks by associating an attacker's MAC address with the gateway's IP in victims' ARP caches. Dynamic ARP Inspection validates ARP packets against a trusted binding table (typically built from DHCP snooping) and drops forged ARP replies, preventing this attack.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A network administrator discovers that several workstations on a subnet suddenly received incorrect IP addresses, default gateways, and DNS server settings, causing intermittent connectivity loss. Investigation reveals an employee connected a personal wireless router to a switch port, and it is now handing out its own DHCP leases. Which technique should be implemented on the switches to prevent this from recurring?", "prompt": {"question": "<p>A network administrator discovers that several workstations on a subnet suddenly received incorrect IP addresses, default gateways, and DNS server settings, causing intermittent connectivity loss. Investigation reveals an employee connected a personal wireless router to a switch port, and it is now handing out its own DHCP leases. Which technique should be implemented on the switches to prevent this from recurring?</p>", "answers": ["<p>Dynamic ARP Inspection (DAI)</p>", "<p>DHCP snooping</p>", "<p>802.1X port-based authentication</p>", "<p>Port security with sticky MAC addresses</p>"], "feedbacks": ["<p>DAI prevents ARP cache poisoning by validating ARP packets against the DHCP snooping binding table — it addresses spoofed ARP replies, not rogue DHCP servers handing out leases.</p>", "<p>DHCP snooping builds a trusted/untrusted port table so only designated trusted ports (uplinks to the legitimate DHCP server) are allowed to send DHCP offer/ack messages. Untrusted access ports that see a DHCP server response are blocked, directly stopping rogue DHCP servers plugged into user-facing switch ports.</p>", "<p>802.1X authenticates devices/users before granting network access, but it does not inspect or filter DHCP traffic once a device is authenticated, so an authenticated rogue router could still serve DHCP.</p>", "<p>Port security limits which MAC addresses can connect to a port to stop unauthorized devices or MAC flooding, but it does not distinguish or block DHCP server messages specifically — the rogue router's own MAC could still be the only device on that port.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A switch port is configured with port security: maximum of 1 allowed MAC address, sticky learning enabled, and the violation mode set to shutdown. A second device is connected to that port and triggers a violation. What is the immediate result?", "prompt": {"question": "<p>A switch port is configured with port security: maximum of 1 allowed MAC address, sticky learning enabled, and the violation mode set to shutdown. A second device is connected to that port and triggers a violation. What is the immediate result?</p>", "answers": ["<p>The port transitions to an err-disabled state and stops forwarding all traffic until manually re-enabled</p>", "<p>The port drops frames from the new MAC address but remains up and forwarding traffic from the original device</p>", "<p>The port logs the violation via SNMP/syslog but takes no further action</p>", "<p>The port automatically returns to a forwarding state after 300 seconds with no administrator intervention</p>"], "feedbacks": ["<p>The 'shutdown' violation mode is the most severe port security action: on a violation, the interface is placed into an err-disabled (administratively down) state, halting all traffic on that port. It requires manual intervention — either a 'shutdown'/'no shutdown' cycle or configuring errdisable auto-recovery — to bring it back online.</p>", "<p>Dropping only the offending frames while the port stays up describes the 'restrict' violation mode, not 'shutdown'.</p>", "<p>Logging the event without disabling the port describes the 'protect' violation mode (protect doesn't even generate a log by default in some implementations, but it never disables the port).</p>", "<p>Automatic recovery after a timer is not the default shutdown behavior; err-disable auto-recovery is a separate, optional feature that must be explicitly configured — it is not on by default.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An attacker crafts frames with two stacked 802.1Q VLAN tags in an attempt to hop from the native VLAN of a trunk into a VLAN they should not have access to. Which switch configuration practice specifically mitigates this double-tagging VLAN hopping technique?", "prompt": {"question": "<p>An attacker crafts frames with two stacked 802.1Q VLAN tags in an attempt to hop from the native VLAN of a trunk into a VLAN they should not have access to. Which switch configuration practice specifically mitigates this double-tagging VLAN hopping technique?</p>", "answers": ["<p>Enable Dynamic ARP Inspection (DAI) on all access VLANs</p>", "<p>Configure port security with a maximum of one sticky MAC address per port</p>", "<p>Assign the native VLAN on all trunk ports to an unused VLAN ID that is not VLAN 1 and is not used by any access port</p>", "<p>Enable DHCP snooping and build the binding table from trusted uplink ports</p>"], "feedbacks": ["<p>DAI validates ARP packets against DHCP snooping bindings to stop ARP spoofing/on-path attacks; it has no role in VLAN tag processing and does not stop double-tagging.</p>", "<p>Port security controls which MAC addresses may connect to a port to prevent unauthorized devices or MAC flooding; it does not inspect or strip 802.1Q tags, so it does not stop double-tagging attacks.</p>", "<p>Double-tagging VLAN hopping exploits the fact that a switch strips the outer tag matching its native VLAN and forwards the frame with the inner tag intact toward the next switch. Changing the trunk's native VLAN to an unused ID (and never assigning that VLAN to any access port) removes the attack's foothold, because frames arriving untagged no longer land on a VLAN the attacker can leverage.</p>", "<p>DHCP snooping protects against rogue DHCP servers by filtering DHCP messages on untrusted ports; it is unrelated to VLAN tag manipulation and provides no protection against double-tagging.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A technician is troubleshooting a user's inability to access a file server. The technician has already identified the problem and established a theory that a recent firewall rule change is blocking the traffic. According to the CompTIA troubleshooting methodology, what should the technician do NEXT?", "prompt": {"question": "<p>A technician is troubleshooting a user's inability to access a file server. The technician has already identified the problem and established a theory that a recent firewall rule change is blocking the traffic. According to the CompTIA troubleshooting methodology, what should the technician do NEXT?</p>", "answers": ["<p>Document the findings and close the ticket</p>", "<p>Test the theory to determine the cause</p>", "<p>Establish a plan of action to resolve the problem</p>", "<p>Implement the solution and escalate if needed</p>"], "feedbacks": ["<p>Documentation is the final step, performed only after the issue is verified as resolved.</p>", "<p>After establishing a theory of probable cause, the next step in the methodology is to test that theory to confirm it before moving to a plan of action.</p>", "<p>A plan of action is created only after the theory has been tested and confirmed, not before.</p>", "<p>Implementation happens after a plan of action is established, which itself comes after testing the theory.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A user reports that they cannot browse to 'intranet.company.local' by name, but they can successfully ping the server's IP address 10.10.5.20 directly. Which tool should the technician use FIRST to isolate the problem?", "prompt": {"question": "<p>A user reports that they cannot browse to 'intranet.company.local' by name, but they can successfully ping the server's IP address 10.10.5.20 directly. Which tool should the technician use FIRST to isolate the problem?</p>", "answers": ["<p>tracert</p>", "<p>netstat</p>", "<p>nslookup</p>", "<p>tcpdump</p>"], "feedbacks": ["<p>tracert shows the path packets take to a destination but won't diagnose a name resolution failure since the problem occurs before routing.</p>", "<p>netstat displays active connections and listening ports on the local host; it does not test DNS resolution.</p>", "<p>Since the IP is reachable but the hostname fails to resolve, nslookup (or dig) is the correct tool to query the DNS server and confirm whether name resolution is functioning.</p>", "<p>tcpdump captures packet traffic for deep analysis, which is a later-stage tool, not the first step for a suspected DNS issue.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A server administrator suspects that an unauthorized application is listening on an unusual port on a Linux server. Which command should be used to list all active connections along with the process IDs and listening ports?", "prompt": {"question": "<p>A server administrator suspects that an unauthorized application is listening on an unusual port on a Linux server. Which command should be used to list all active connections along with the process IDs and listening ports?</p>", "answers": ["<p>ping -t</p>", "<p>netstat -tulnp</p>", "<p>ipconfig /all</p>", "<p>dig ANY</p>"], "feedbacks": ["<p>ping -t is a continuous ping used to test reachability, not connection/port enumeration, and -t is a Windows switch, not Linux syntax.</p>", "<p>netstat -tulnp (or the modern ss equivalent) lists TCP/UDP listening and established connections along with the associated process, which is exactly what's needed to identify unauthorized listening services.</p>", "<p>ipconfig /all is a Windows command that displays interface configuration, not connections or listening ports, and doesn't exist on Linux.</p>", "<p>dig ANY queries DNS records for a domain; it has nothing to do with listing local network connections.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A technician runs a cable certifier on a newly terminated Cat6 patch cable and receives a 'split pair' warning even though continuity on all 8 pins tests fine. What does this result indicate?", "prompt": {"question": "<p>A technician runs a cable certifier on a newly terminated Cat6 patch cable and receives a 'split pair' warning even though continuity on all 8 pins tests fine. What does this result indicate?</p>", "answers": ["<p>The cable exceeds the maximum length for Cat6</p>", "<p>The connector is using the T568A standard on one end and T568B on the other</p>", "<p>There is a short between pins 1 and 2</p>", "<p>Two wires from different twisted pairs were terminated together instead of their original pair</p>"], "feedbacks": ["<p>Length issues are reported separately as an attenuation or length failure, not as a split pair warning.</p>", "<p>A crossed T568A/B standard on each end intentionally creates a crossover cable and produces a documented wire-map difference, not a split-pair fault.</p>", "<p>A short between pins would fail basic continuity testing, but the scenario states continuity passed on all 8 pins.</p>", "<p>A split pair occurs when wires from two different pairs are punched down together, satisfying pin-to-pin continuity but destroying the twisted-pair cancellation, which a wire map/certifier detects as a split pair fault even though basic continuity passes.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Employees on the 2.4 GHz Wi-Fi network near the office break room report intermittent slow speeds and dropped connections, especially around lunchtime. Other floors on the same SSID do not have this issue. What is the MOST likely cause?", "prompt": {"question": "<p>Employees on the 2.4 GHz Wi-Fi network near the office break room report intermittent slow speeds and dropped connections, especially around lunchtime. Other floors on the same SSID do not have this issue. What is the MOST likely cause?</p>", "answers": ["<p>RF interference from the break room's microwave oven operating on the same frequency band</p>", "<p>An expired DHCP lease pool on the wireless controller</p>", "<p>A duplicate IP address conflict on the wireless VLAN</p>", "<p>The access point's firmware has not been updated recently</p>"], "feedbacks": ["<p>Microwave ovens operate in the 2.4 GHz band and are a well-known source of RF interference, and the symptom pattern—localized to the break room and worse around lunchtime—strongly points to microwave interference.</p>", "<p>An exhausted DHCP pool would cause failures to obtain an IP address entirely, not intermittent slowness localized to one physical area.</p>", "<p>An IP conflict produces connectivity errors and duplicate address warnings network-wide or per-device, not a location- and time-specific slowdown.</p>", "<p>Outdated firmware could cause various issues but wouldn't explain why the symptom is tied specifically to lunchtime and the break room location.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "While troubleshooting a connectivity problem, a technician runs a traceroute and observes 0% packet loss on hops 1-4, then 100% packet loss reported on hop 5 and every hop thereafter, yet the final destination is still reachable and responds to the traceroute. What is the BEST interpretation of this result?", "prompt": {"question": "<p>While troubleshooting a connectivity problem, a technician runs a traceroute and observes 0% packet loss on hops 1-4, then 100% packet loss reported on hop 5 and every hop thereafter, yet the final destination is still reachable and responds to the traceroute. What is the BEST interpretation of this result?</p>", "answers": ["<p>Hop 5 is very likely just deprioritizing or rate-limiting ICMP replies, not necessarily dropping actual traffic</p>", "<p>The final destination is definitely down and unreachable</p>", "<p>There is a routing loop occurring at hop 5</p>", "<p>The network path physically fails at hop 5 and all traffic beyond it is blocked</p>"], "feedbacks": ["<p>Many routers deprioritize or rate-limit ICMP traceroute responses for security or CPU-load reasons, so seeing loss reported starting at one hop and continuing through the rest, while the actual destination still responds, is a classic sign of ICMP deprioritization rather than a real outage.</p>", "<p>The destination is stated to be reachable and responding, directly contradicting the idea that it is down.</p>", "<p>A routing loop would typically show repeating hop addresses or a TTL-exceeded pattern, not simply a wall of 100% loss with a reachable endpoint.</p>", "<p>If the path truly failed at hop 5, the destination itself would not respond at all, but the scenario states it does respond.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A technician runs the following command on a Windows workstation that can reach internal servers but cannot reach any external websites:\n\ntracert 8.8.8.8\n\nThe output shows successful replies for the first two hops (the default gateway and the ISP's first router), followed by \"Request timed out\" for all subsequent hops. Which of the following is the MOST likely cause of this issue?", "prompt": {"question": "<p>A technician runs the following command on a Windows workstation that can reach internal servers but cannot reach any external websites:\n\ntracert 8.8.8.8\n\nThe output shows successful replies for the first two hops (the default gateway and the ISP's first router), followed by \"Request timed out\" for all subsequent hops. Which of the following is the MOST likely cause of this issue?</p>", "answers": ["<p>The workstation's DNS server is misconfigured</p>", "<p>A firewall or router beyond the second hop is blocking or dropping the traffic</p>", "<p>The workstation has an incorrect subnet mask</p>", "<p>The default gateway address is incorrect</p>"], "feedbacks": ["<p>If DNS were the issue, tracert to a literal IP address (8.8.8.8) would still succeed since no name resolution is required here.</p>", "<p>Because the first two hops respond successfully, local configuration (gateway, subnet mask) is confirmed correct, and traffic is leaving the local network. Timeouts beginning at a consistent hop further out indicate that a device at or beyond that hop (commonly a firewall dropping ICMP or blocking traffic) is not returning replies, which is a classic tracert-based diagnosis of a routing/filtering problem beyond the local network.</p>", "<p>An incorrect subnet mask would typically prevent the workstation from reaching even the default gateway or local subnet devices, but hop 1 succeeded, ruling this out.</p>", "<p>If the default gateway were incorrect, hop 1 would fail immediately; since it succeeded, the gateway address is correct.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "Several users on a floor report that their computers received IP addresses in the 169.254.0.0/16 range and cannot access any network resources. According to the CompTIA troubleshooting methodology, after identifying the symptom, which action should the technician take FIRST to establish a theory of probable cause?", "prompt": {"question": "<p>Several users on a floor report that their computers received IP addresses in the 169.254.0.0/16 range and cannot access any network resources. According to the CompTIA troubleshooting methodology, after identifying the symptom, which action should the technician take FIRST to establish a theory of probable cause?</p>", "answers": ["<p>Replace the network cables for all affected workstations</p>", "<p>Reinstall the TCP/IP stack on each affected workstation</p>", "<p>Check whether the DHCP server's scope has available leases remaining</p>", "<p>Assign static IP addresses to all affected workstations</p>"], "feedbacks": ["<p>Replacing cables addresses a physical layer issue, but the symptom (APIPA on multiple machines) points to a DHCP problem, not a cabling problem, and this action skips proper theory establishment.</p>", "<p>Reinstalling the TCP/IP stack is a workstation-level fix that does not address a shared symptom affecting multiple devices and is not an appropriate first diagnostic step.</p>", "<p>A 169.254.x.x address is an APIPA address, which a Windows client automatically assigns itself when it cannot contact a DHCP server. The most likely and easily verifiable cause affecting multiple clients simultaneously is DHCP scope exhaustion or DHCP service failure, so checking the DHCP server's available lease pool is the correct first step in establishing a theory of probable cause before jumping to more disruptive or unrelated fixes.</p>", "<p>Assigning static IPs is a temporary workaround, not a root-cause fix, and does not follow the methodology of first establishing why DHCP failed.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}]}, {"name": "CompTIA Network+ Practice Test 2", "cid": 7305515, "duration": 90, "pass_percent": 72, "questions": [{"assessment_type": "multiple-choice", "question_plain": "A network administrator has been given the network 192.168.10.0/24 and must divide it into at least 6 subnets while ensuring each subnet supports a minimum of 25 usable host addresses. Which subnet mask satisfies BOTH requirements with the least wasted address space?", "prompt": {"question": "<p>A network administrator has been given the network 192.168.10.0/24 and must divide it into at least 6 subnets while ensuring each subnet supports a minimum of 25 usable host addresses. Which subnet mask satisfies BOTH requirements with the least wasted address space?</p>", "answers": ["<p>255.255.255.192 (/26)</p>", "<p>255.255.255.240 (/28)</p>", "<p>255.255.255.224 (/27)</p>", "<p>255.255.255.128 (/25)</p>"], "feedbacks": ["<p>/26 only creates 4 subnets (2^2), which fails the requirement of at least 6 subnets even though it provides 62 hosts each.</p>", "<p>/28 provides 16 subnets but only 14 usable hosts per subnet (2^4-2), which fails the minimum 25-host requirement.</p>", "<p>A /27 mask borrows 3 bits from the host portion, creating 8 subnets (2^3), each with 30 usable hosts (2^5-2). This meets the requirement of at least 6 subnets and at least 25 hosts per subnet with minimal waste.</p>", "<p>/25 only creates 2 subnets, far short of the 6-subnet requirement, even though it provides 126 hosts each.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "An interface on a workstation is automatically assigned an IPv6 address that always begins with the prefix FE80::/10. This address is usable only for communication with devices on the same local network segment and is not routable beyond that segment. Which IPv6 address type is being described?", "prompt": {"question": "<p>An interface on a workstation is automatically assigned an IPv6 address that always begins with the prefix FE80::/10. This address is usable only for communication with devices on the same local network segment and is not routable beyond that segment. Which IPv6 address type is being described?</p>", "answers": ["<p>Unique local address</p>", "<p>Global unicast address</p>", "<p>Link-local address</p>", "<p>Multicast address</p>"], "feedbacks": ["<p>Unique local addresses (FC00::/7) are the IPv6 equivalent of private addressing and are routable within an organization across multiple subnets, unlike link-local.</p>", "<p>Global unicast addresses (2000::/3) are publicly routable on the internet, the opposite of the local-segment-only scope described.</p>", "<p>Link-local addresses always use the FE80::/10 prefix, are automatically configured on every IPv6-enabled interface, and are confined to the local link — they are never forwarded by routers.</p>", "<p>Multicast addresses (FF00::/8) are used to deliver a single packet to multiple destination interfaces, not for standard single-segment host communication.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A mail administrator needs to configure a client so that users can access their mailbox over an encrypted connection while keeping messages synchronized across multiple devices, meaning messages remain on the server rather than being downloaded and removed. Which port should be configured on the client?", "prompt": {"question": "<p>A mail administrator needs to configure a client so that users can access their mailbox over an encrypted connection while keeping messages synchronized across multiple devices, meaning messages remain on the server rather than being downloaded and removed. Which port should be configured on the client?</p>", "answers": ["<p>110</p>", "<p>143</p>", "<p>995</p>", "<p>993</p>"], "feedbacks": ["<p>Port 110 is unencrypted POP3, which typically downloads and removes messages from the server, breaking multi-device sync — and it lacks encryption.</p>", "<p>Port 143 is standard IMAP, which supports sync but is unencrypted, failing the encryption requirement in the scenario.</p>", "<p>Port 995 is POP3 over SSL (POP3S) — encrypted, but POP3's model of downloading mail to a single client does not support the multi-device synchronization requirement.</p>", "<p>Port 993 is IMAP over SSL/TLS (IMAPS). IMAP keeps mail synchronized on the server and reflects read/unread status and folder structure across multiple devices, and port 993 provides this over an encrypted channel.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company is designing a new data center fabric and requires low-latency, any-to-any connectivity between servers where the number of hops and latency remain consistent no matter which two leaf switches the communicating servers are attached to. Which topology BEST meets this requirement?", "prompt": {"question": "<p>A company is designing a new data center fabric and requires low-latency, any-to-any connectivity between servers where the number of hops and latency remain consistent no matter which two leaf switches the communicating servers are attached to. Which topology BEST meets this requirement?</p>", "answers": ["<p>Three-tier hierarchical</p>", "<p>Star topology</p>", "<p>Spine-leaf</p>", "<p>Full mesh WAN</p>"], "feedbacks": ["<p>Three-tier hierarchical designs route traffic through core, aggregation, and access layers, which can create variable and higher latency depending on the path taken between access switches.</p>", "<p>Star topology centers all connections on a single hub device, creating a single point of failure and not describing a scalable data-center fabric pattern.</p>", "<p>In a spine-leaf architecture, every leaf switch connects directly to every spine switch, so any server-to-server path always crosses exactly one spine, guaranteeing predictable, consistent low latency regardless of which leaf switches are involved.</p>", "<p>Full mesh WAN connects every node directly to every other node, which does not scale in a data center with many servers due to the exponential growth in required links.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "In a Software-Defined Networking (SDN) architecture, which component is responsible for making network-wide forwarding decisions and programming flow tables into switches using a southbound API such as OpenFlow?", "prompt": {"question": "<p>In a Software-Defined Networking (SDN) architecture, which component is responsible for making network-wide forwarding decisions and programming flow tables into switches using a southbound API such as OpenFlow?</p>", "answers": ["<p>Control plane</p>", "<p>Data plane</p>", "<p>Application plane</p>", "<p>Management plane</p>"], "feedbacks": ["<p>The SDN controller operates in the control plane, maintaining a centralized view of the network and pushing forwarding rules down to switches (the data plane) through a southbound API like OpenFlow.</p>", "<p>The data plane consists of the switches and routers that simply forward packets according to the flow tables they receive — it does not make forwarding decisions itself.</p>", "<p>The application plane sits above the control plane and hosts network applications (e.g., load balancers, firewalls) that communicate with the controller via northbound APIs, not southbound programming of devices.</p>", "<p>The management plane handles device configuration, monitoring, and administration tasks, not real-time forwarding decisions communicated to switch hardware.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company is migrating a large, latency-sensitive on-premises database workload to a hybrid cloud model and needs a private, dedicated connection between its data center and its cloud VPC that avoids the public internet entirely and offers consistent, high bandwidth. Which solution BEST meets this requirement?", "prompt": {"question": "<p>A company is migrating a large, latency-sensitive on-premises database workload to a hybrid cloud model and needs a private, dedicated connection between its data center and its cloud VPC that avoids the public internet entirely and offers consistent, high bandwidth. Which solution BEST meets this requirement?</p>", "answers": ["<p>Site-to-site VPN over the public internet</p>", "<p>Client-to-site VPN</p>", "<p>Public internet connection secured with TLS</p>", "<p>Dedicated cloud interconnect (private direct connection)</p>"], "feedbacks": ["<p>A site-to-site VPN encrypts traffic but still traverses the public internet, introducing variable latency and bandwidth constraints unsuitable for the stated requirement of avoiding the internet entirely.</p>", "<p>Client-to-site VPN is designed for individual remote users connecting into a network, not for site-to-site data center to cloud connectivity of an entire workload.</p>", "<p>Using the public internet with TLS still routes traffic across shared, unpredictable internet paths and does not meet the requirement of a private, dedicated connection avoiding the public internet.</p>", "<p>A dedicated cloud interconnect (such as a direct connect or express-route style private circuit) provides a private, dedicated physical or logical link between the on-premises network and the cloud VPC, bypassing the public internet and delivering predictable bandwidth and latency for demanding workloads.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A network administrator is subnetting 192.168.10.0/24 using VLSM to support four departments. Sales requires 100 usable hosts, IT requires 50, HR requires 25, and Guest requires 10. Which subnet mask should be assigned to the Sales subnet to satisfy the requirement while minimizing wasted addresses?", "prompt": {"question": "<p>A network administrator is subnetting 192.168.10.0/24 using VLSM to support four departments. Sales requires 100 usable hosts, IT requires 50, HR requires 25, and Guest requires 10. Which subnet mask should be assigned to the Sales subnet to satisfy the requirement while minimizing wasted addresses?</p>", "answers": ["<p>255.255.255.128</p>", "<p>255.255.255.192</p>", "<p>255.255.255.0</p>", "<p>255.255.255.224</p>"], "feedbacks": ["<p>255.255.255.128 is a /25, giving 2^7-2 = 126 usable hosts, which comfortably covers the 100-host requirement while wasting only 26 addresses compared to larger blocks.</p>", "<p>255.255.255.192 (/26) provides only 2^6-2 = 62 usable hosts, which is insufficient for 100 hosts.</p>", "<p>255.255.255.0 (/24) provides 254 usable hosts but wastes 154 addresses that could be used for the other three subnets in a VLSM scheme.</p>", "<p>255.255.255.224 (/27) provides only 30 usable hosts, far short of the 100-host requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A network engineer must configure a firewall rule to allow secure, encrypted file transfers between two Linux servers using a single TCP connection that relies on SSH for both authentication and encryption. Which port should be opened?", "prompt": {"question": "<p>A network engineer must configure a firewall rule to allow secure, encrypted file transfers between two Linux servers using a single TCP connection that relies on SSH for both authentication and encryption. Which port should be opened?</p>", "answers": ["<p>TCP 20/21</p>", "<p>TCP 22</p>", "<p>TCP 989/990</p>", "<p>UDP 69</p>"], "feedbacks": ["<p>TCP 20/21 are used by traditional FTP, which transmits credentials and data in cleartext and uses separate control and data connections, not SSH.</p>", "<p>SFTP (SSH File Transfer Protocol) operates over a single TCP connection on port 22, using the SSH protocol for both authentication and encryption of the entire session.</p>", "<p>TCP 989/990 are used by FTPS, which relies on SSL/TLS rather than SSH for encryption.</p>", "<p>UDP 69 is used by TFTP, a connectionless, unauthenticated protocol with no encryption, commonly used for simple file transfers like firmware updates.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "During troubleshooting, a technician runs ipconfig on a Windows host and observes the address FE80::4A3F:2B1C:9E21:88AA assigned to the network adapter. What does this address type indicate?", "prompt": {"question": "<p>During troubleshooting, a technician runs ipconfig on a Windows host and observes the address FE80::4A3F:2B1C:9E21:88AA assigned to the network adapter. What does this address type indicate?</p>", "answers": ["<p>A globally routable unicast address reachable from the internet</p>", "<p>A unique local address used for private routing between multiple internal networks</p>", "<p>A multicast address used to reach all nodes on the local subnet</p>", "<p>An automatically generated link-local address used only for communication on the local network segment</p>"], "feedbacks": ["<p>Globally routable unicast addresses begin with the 2000::/3 range, not FE80::/10, and are reachable across the internet.</p>", "<p>Unique local addresses fall in the FC00::/7 range (commonly FD00::/8) and are used for private inter-site routing, not the FE80 link-local range.</p>", "<p>IPv6 multicast addresses always begin with FF00::/8, not FE80::/10, and are used to reach a defined group of nodes, not just local link communication.</p>", "<p>Addresses in the FE80::/10 range are IPv6 link-local addresses, automatically assigned to every interface for communication within the local link only; they are never routed off the local segment.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A cloud provider is designing a new data center network fabric that must support non-blocking, predictable low-latency communication between any two servers, regardless of their physical rack location, with every leaf switch connected directly to every spine switch. Which topology best fits this requirement?", "prompt": {"question": "<p>A cloud provider is designing a new data center network fabric that must support non-blocking, predictable low-latency communication between any two servers, regardless of their physical rack location, with every leaf switch connected directly to every spine switch. Which topology best fits this requirement?</p>", "answers": ["<p>Three-tier hierarchical topology</p>", "<p>Full-mesh topology</p>", "<p>Spine-leaf topology</p>", "<p>Star topology</p>"], "feedbacks": ["<p>Three-tier hierarchical topology (core-distribution-access) introduces additional hops and is optimized for north-south traffic, not the uniform low-latency east-west pattern described.</p>", "<p>Full-mesh topology, while providing direct links between every device, becomes impractical to cable and scale at data center switch counts, unlike the structured spine-leaf design.</p>", "<p>Spine-leaf topology connects every leaf switch to every spine switch, ensuring any server-to-server path traverses at most one spine hop, delivering predictable, low-latency, non-blocking east-west traffic ideal for modern data centers.</p>", "<p>Star topology centralizes all connections through a single hub or switch, creating a bottleneck and single point of failure, which contradicts the non-blocking, distributed requirement described.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A network has four switches participating in STP: SW1 (priority 32768, MAC 00:11:22:33:44:55), SW2 (priority 24576, MAC 00:99:88:77:66:55), SW3 (priority 32768, MAC 00:00:11:11:22:22), and SW4 (priority 4096, MAC 00:AA:BB:CC:DD:EE). Which switch will be elected the root bridge?", "prompt": {"question": "<p>A network has four switches participating in STP: SW1 (priority 32768, MAC 00:11:22:33:44:55), SW2 (priority 24576, MAC 00:99:88:77:66:55), SW3 (priority 32768, MAC 00:00:11:11:22:22), and SW4 (priority 4096, MAC 00:AA:BB:CC:DD:EE). Which switch will be elected the root bridge?</p>", "answers": ["<p>SW1, because its MAC address is numerically first among the 32768-priority switches</p>", "<p>SW4, because it has the lowest bridge priority value</p>", "<p>SW3, because it has the lowest MAC address of all four switches</p>", "<p>SW2, because its priority is lower than SW1 and SW3</p>"], "feedbacks": ["<p>MAC address only matters as a tiebreaker when priorities are equal; SW1's priority (32768) is higher than SW4's, so MAC is irrelevant here.</p>", "<p>The root bridge is the switch with the lowest Bridge ID, which is priority compared first, then MAC address as a tiebreaker. SW4's priority of 4096 is the lowest of all four values, so it wins regardless of its MAC address.</p>", "<p>SW3 shares the same priority as SW1 but both are higher than SW4's priority, so MAC comparison between them never determines the root bridge in this scenario.</p>", "<p>SW2's priority (24576) is lower than SW1/SW3 but still higher than SW4's 4096, so SW2 cannot be root.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A service provider needs to exchange routing information with multiple independent autonomous systems belonging to other organizations across the internet, requiring policy-based path selection rather than pure metric-based shortest path. Which routing protocol is designed for this use case?", "prompt": {"question": "<p>A service provider needs to exchange routing information with multiple independent autonomous systems belonging to other organizations across the internet, requiring policy-based path selection rather than pure metric-based shortest path. Which routing protocol is designed for this use case?</p>", "answers": ["<p>EIGRP</p>", "<p>BGP</p>", "<p>OSPF</p>", "<p>RIP</p>"], "feedbacks": ["<p>EIGRP is a Cisco-proprietary interior gateway protocol intended for routing within a single organization's autonomous system, not between independent organizations.</p>", "<p>BGP is a path-vector, exterior gateway protocol built specifically for inter-AS routing on the internet, supporting policy-based decisions (AS-path, local preference, communities) rather than simple metrics.</p>", "<p>OSPF is a link-state interior gateway protocol designed for routing within a single AS using cost metrics, not for policy-based routing between separate organizations.</p>", "<p>RIP is a legacy distance-vector interior protocol limited to 15 hops and unsuitable for large-scale, policy-driven internet routing.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "Two switches are connected via an 802.1Q trunk. Switch A is configured with native VLAN 1 on the trunk port, while Switch B is configured with native VLAN 99 on the same trunk port. Untagged frames sent from Switch A are unexpectedly appearing in VLAN 99 on Switch B. What configuration issue is occurring?", "prompt": {"question": "<p>Two switches are connected via an 802.1Q trunk. Switch A is configured with native VLAN 1 on the trunk port, while Switch B is configured with native VLAN 99 on the same trunk port. Untagged frames sent from Switch A are unexpectedly appearing in VLAN 99 on Switch B. What configuration issue is occurring?</p>", "answers": ["<p>Trunk encapsulation mismatch between ISL and 802.1Q</p>", "<p>An incorrect allowed VLAN list is pruning traffic on the trunk</p>", "<p>Port security has placed one of the trunk ports into err-disabled state</p>", "<p>A native VLAN mismatch, which causes untagged traffic to cross between the differently-numbered native VLANs</p>"], "feedbacks": ["<p>Both switches are using 802.1Q (implied by native VLAN terminology, which doesn't apply to ISL); an encapsulation mismatch would typically bring the trunk down entirely rather than leak traffic between specific VLANs.</p>", "<p>An allowed VLAN list mismatch would block or prune specific VLANs from crossing the trunk, not cause untagged frames to reappear in a different VLAN.</p>", "<p>Err-disabled state from port security would drop the trunk link entirely, not selectively move untagged traffic into another VLAN.</p>", "<p>Each switch strips the tag from frames destined to its own configured native VLAN before sending untagged, and the receiving switch assumes untagged frames belong to its own native VLAN. When the native VLAN numbers differ, untagged frames effectively leak from one VLAN into another, which is exactly the described symptom and a known VLAN-hopping risk.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company uses PAT to allow 300 internal hosts to share a single public IP address for internet access. During peak usage, users experience intermittent connection failures, and the engineer confirms the NAT translation table is near capacity. Which explanation and remediation BEST addresses this issue?", "prompt": {"question": "<p>A company uses PAT to allow 300 internal hosts to share a single public IP address for internet access. During peak usage, users experience intermittent connection failures, and the engineer confirms the NAT translation table is near capacity. Which explanation and remediation BEST addresses this issue?</p>", "answers": ["<p>PAT is limited to roughly 65,536 concurrent translations per public IP address due to the 16-bit source port field; add additional public IP addresses to the NAT pool to increase available translations</p>", "<p>PAT requires a static one-to-one mapping per host; convert the configuration to static NAT for each user</p>", "<p>PAT only translates TCP traffic; add a firewall rule to permit UDP traffic through the same public IP</p>", "<p>NAT tables on all networking devices are hard-limited to 256 entries; a firmware upgrade is required to increase this ceiling</p>"], "feedbacks": ["<p>PAT distinguishes translations using the source port number, a 16-bit field, capping concurrent sessions at roughly 65,536 per public IP. Adding more public IP addresses to the NAT pool multiplies available port space, resolving exhaustion during peak load.</p>", "<p>Static NAT provides one-to-one mappings and would require one public IP per host, defeating the purpose of PAT and not addressing the root port-limitation issue at scale.</p>", "<p>PAT translates both TCP and UDP (and other protocols using port-like identifiers); the failure described is due to table exhaustion, not protocol restriction.</p>", "<p>NAT/PAT table size limits are vendor- and platform-dependent based on memory and licensing, not a universal 256-entry hard limit, and firmware alone won't solve fundamental port-space exhaustion from a single IP.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization needs a 10GbE link between two buildings located 300 meters apart, connected via single-mode fiber. Which transceiver should be installed to support this distance and cable type?", "prompt": {"question": "<p>An organization needs a 10GbE link between two buildings located 300 meters apart, connected via single-mode fiber. Which transceiver should be installed to support this distance and cable type?</p>", "answers": ["<p>SFP+ 10GBASE-SR</p>", "<p>SFP+ 10GBASE-T</p>", "<p>QSFP+ 40GBASE-SR4</p>", "<p>SFP+ 10GBASE-LR</p>"], "feedbacks": ["<p>10GBASE-SR is designed for multimode fiber and typically supports only up to about 400 meters (with OM4) but is not rated for single-mode fiber, making it incompatible here.</p>", "<p>10GBASE-T operates over copper twisted-pair cabling up to 100 meters, not fiber, and cannot meet the 300-meter fiber requirement.</p>", "<p>QSFP+ 40GBASE-SR4 is a 40 Gbps multimode fiber standard using MPO connectors, mismatched both in speed and fiber type for this 10GbE single-mode requirement.</p>", "<p>10GBASE-LR is designed for single-mode fiber and supports distances up to approximately 10 kilometers, comfortably covering the 300-meter run described.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Which statement accurately describes Wi-Fi 6E as defined in the 802.11ax amendment extension?", "prompt": {"question": "<p>Which statement accurately describes Wi-Fi 6E as defined in the 802.11ax amendment extension?</p>", "answers": ["<p>Wi-Fi 6E is fully backward compatible, allowing all existing 802.11n and 802.11ac devices to automatically use the new 6 GHz channels</p>", "<p>Wi-Fi 6E's primary improvement over standard Wi-Fi 6 is the addition of MU-MIMO, which was not previously available</p>", "<p>Wi-Fi 6E extends usable range significantly further than 2.4 GHz due to the 6 GHz band's superior propagation characteristics</p>", "<p>Wi-Fi 6E adds access to the 6 GHz band, but only devices with 6E-capable radios can use it, and it provides no backward compatibility for legacy 2.4/5 GHz-only devices on that band</p>"], "feedbacks": ["<p>Legacy 802.11n/ac devices lack 6 GHz radios entirely and cannot access 6E networks; they can only connect via the 2.4/5 GHz bands if the AP also supports those.</p>", "<p>MU-MIMO was already introduced with 802.11ac/ax standards prior to 6E; the defining feature of 6E specifically is 6 GHz band access, not MU-MIMO.</p>", "<p>Higher frequencies like 6 GHz have shorter range and worse wall penetration than 2.4 GHz, not superior propagation; 6E trades range for more available spectrum and less interference.</p>", "<p>Wi-Fi 6E extends Wi-Fi 6 into the new 6 GHz spectrum, offering more non-overlapping channels and wider channel widths (up to 160 MHz), but only client devices with radios explicitly supporting 6 GHz can connect there; legacy devices simply cannot see or use that band.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A network engineer is troubleshooting an access-layer switch that supports end-user desktop connections. Users occasionally connect small unmanaged switches to their desks, and one such incident caused a Layer 2 loop that took down the VLAN for several minutes. The engineer wants the affected ports to still transition immediately to the forwarding state for normal PC connections, but any port that receives a BPDU from an unauthorized device must be automatically shut down. Which configuration BEST meets this requirement?", "prompt": {"question": "<p>A network engineer is troubleshooting an access-layer switch that supports end-user desktop connections. Users occasionally connect small unmanaged switches to their desks, and one such incident caused a Layer 2 loop that took down the VLAN for several minutes. The engineer wants the affected ports to still transition immediately to the forwarding state for normal PC connections, but any port that receives a BPDU from an unauthorized device must be automatically shut down. Which configuration BEST meets this requirement?</p>", "answers": ["<p>Enable Root Guard on the port</p>", "<p>Enable BPDU Guard along with PortFast on the port</p>", "<p>Enable Loop Guard on the port</p>", "<p>Disable Spanning Tree Protocol on the port</p>"], "feedbacks": ["<p>Root Guard prevents a port from becoming the root port/root bridge by blocking superior BPDUs from that direction, but it doesn't stop or shut down a rogue switch causing a loop on an access port the way BPDU Guard does — it's meant for uplink/designated ports toward the intended root.</p>", "<p>PortFast allows an access port to skip the listening/learning states and go straight to forwarding for fast end-device connectivity, while BPDU Guard automatically err-disables that port the instant it receives a BPDU — which only happens if a switch (not an end device) is plugged in, effectively catching the rogue switch scenario.</p>", "<p>Loop Guard protects against loops caused by unidirectional link failures on non-designated ports (typically on trunk links between switches), not against a user plugging in an unmanaged switch on an access port.</p>", "<p>Disabling STP entirely removes all loop protection, making the network far more vulnerable to sustained broadcast storms — the opposite of what's needed.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A network engineer is designing a high-density Wi-Fi 6E deployment for a large conference hall with hundreds of simultaneous client devices. Which of the following BEST describes the primary advantage the 6 GHz band provides for this deployment compared to using 5 GHz alone?", "prompt": {"question": "<p>A network engineer is designing a high-density Wi-Fi 6E deployment for a large conference hall with hundreds of simultaneous client devices. Which of the following BEST describes the primary advantage the 6 GHz band provides for this deployment compared to using 5 GHz alone?</p>", "answers": ["<p>Backward compatibility with 2.4 GHz and 5 GHz legacy devices</p>", "<p>Longer transmission range due to a lower operating frequency</p>", "<p>Additional non-overlapping 80 MHz and 160 MHz channels unavailable in the 5 GHz band</p>", "<p>Native support for WEP to maintain compatibility with legacy IoT devices</p>"], "feedbacks": ["<p>6 GHz is a new band with no legacy device support — Wi-Fi 6E requires new radios/clients; there is no backward compatibility with older 2.4/5 GHz-only devices on this band.</p>", "<p>6 GHz is a higher frequency than 5 GHz, not lower, and higher frequencies have shorter range and worse wall penetration, not longer range.</p>", "<p>The 6 GHz band adds a large amount of new, uncongested spectrum, enabling many more non-overlapping wide channels (including multiple 160 MHz channels) than 5 GHz can offer, which is critical for reducing co-channel interference in high-density environments.</p>", "<p>Wi-Fi 6E mandates WPA3 (and WPA3-only in many implementations) for security in the 6 GHz band; WEP is deprecated, insecure, and not used for 6E connectivity.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A data center technician needs to connect two switches located 280 meters apart using multimode fiber, running at 10 Gbps. Which transceiver type should be selected?", "prompt": {"question": "<p>A data center technician needs to connect two switches located 280 meters apart using multimode fiber, running at 10 Gbps. Which transceiver type should be selected?</p>", "answers": ["<p>10GBASE-LR single-mode transceiver, rated for up to 10 km</p>", "<p>10GBASE-ER single-mode transceiver, rated for up to 40 km</p>", "<p>10GBASE-SR multimode transceiver, rated for up to 300 m</p>", "<p>10GBASE-ZR single-mode transceiver, rated for up to 80 km</p>"], "feedbacks": ["<p>10GBASE-LR is designed for single-mode fiber at 1310 nm; using it over multimode fiber is not standard practice and it doesn't match the multimode fiber type given.</p>", "<p>10GBASE-ER is a long-range single-mode transceiver intended for up to 40 km links between facilities, which is unnecessary and incompatible with the multimode fiber described here.</p>", "<p>10GBASE-SR is designed specifically for multimode fiber and 850 nm optics, supporting distances up to roughly 300 m over OM3/OM4 cabling, which fits both the fiber type (multimode) and the required 280 m distance.</p>", "<p>10GBASE-ZR is an extended-reach single-mode transceiver for very long metro/WAN links up to 80 km, over-engineered and incompatible with multimode fiber for this short in-building run.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A security policy now requires that all SNMP management traffic be both authenticated and encrypted between network devices and the monitoring server. Which configuration meets this requirement?", "prompt": {"question": "<p>A security policy now requires that all SNMP management traffic be both authenticated and encrypted between network devices and the monitoring server. Which configuration meets this requirement?</p>", "answers": ["<p>SNMPv2c with a complex community string</p>", "<p>SNMPv3 configured with authPriv security level using SHA and AES</p>", "<p>SNMPv1 with the community string changed from 'public' to 'private'</p>", "<p>SNMPv2c tunneled manually through a separate VPN appliance</p>"], "feedbacks": ["<p>SNMPv2c community strings are sent in cleartext regardless of complexity — no encryption exists in v2c.</p>", "<p>SNMPv3 with authPriv provides both authentication (SHA) and encryption (AES) natively, which is the exam's standard answer for secure SNMP monitoring.</p>", "<p>SNMPv1 has no encryption capability at all; changing the community string does not add authentication or privacy.</p>", "<p>Adding a separate VPN appliance is unnecessary overhead and not the built-in solution the exam expects when SNMPv3 already provides this natively.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A core switch's maintenance log shows two uptime segments: 3,000 hours followed by a 6-hour repair, then another 3,000 hours followed by another 6-hour repair. Based on this data, what is the switch's MTTR?", "prompt": {"question": "<p>A core switch's maintenance log shows two uptime segments: 3,000 hours followed by a 6-hour repair, then another 3,000 hours followed by another 6-hour repair. Based on this data, what is the switch's MTTR?</p>", "answers": ["<p>3,000 hours</p>", "<p>1,500 hours</p>", "<p>6 hours</p>", "<p>12 hours</p>"], "feedbacks": ["<p>3,000 hours is the MTBF (average uptime between failures), not the repair time.</p>", "<p>1,500 hours is half of one uptime segment and has no meaning in this calculation.</p>", "<p>MTTR (Mean Time To Repair) is the average repair time across failure events: (6 + 6) / 2 = 6 hours.</p>", "<p>12 hours is the total repair time across both events, not the average (mean) repair time.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "An engineer must monitor traffic on a 100Gbps core backbone link to identify top talkers, but the monitoring solution must not add significant processing overhead to the router at that traffic volume. Which approach BEST meets this requirement?", "prompt": {"question": "<p>An engineer must monitor traffic on a 100Gbps core backbone link to identify top talkers, but the monitoring solution must not add significant processing overhead to the router at that traffic volume. Which approach BEST meets this requirement?</p>", "answers": ["<p>Full packet capture using an inline network tap</p>", "<p>SNMP interface counter polling every 5 seconds</p>", "<p>Unsampled NetFlow export on every packet</p>", "<p>sFlow sampling</p>"], "feedbacks": ["<p>Full packet capture at 100Gbps generates massive storage and processing demands and is impractical for continuous monitoring.</p>", "<p>SNMP polling only provides aggregate interface counters (bytes/errors), not per-conversation top-talker detail.</p>", "<p>Unsampled NetFlow at high link speeds consumes significant router CPU and memory generating flow records for every packet, which is the exact overhead the scenario says to avoid.</p>", "<p>sFlow is specifically designed for high-speed links because it samples packets at a statistical rate, providing flow visibility with minimal processing and export overhead compared to full flow accounting.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company requires a disaster recovery solution with real-time data replication and a Recovery Time Objective (RTO) under 15 minutes. Which DR site type should be implemented?", "prompt": {"question": "<p>A company requires a disaster recovery solution with real-time data replication and a Recovery Time Objective (RTO) under 15 minutes. Which DR site type should be implemented?</p>", "answers": ["<p>Hot site</p>", "<p>Warm site</p>", "<p>Cold site</p>", "<p>Cloud-based backup storage only</p>"], "feedbacks": ["<p>A hot site maintains fully configured, running infrastructure with real-time or near-real-time data replication, enabling failover in minutes — meeting the sub-15-minute RTO.</p>", "<p>A warm site has partially configured hardware with periodic (not real-time) data syncing, typically requiring hours to become operational.</p>", "<p>A cold site provides only space, power, and cooling with no pre-installed equipment or data, requiring days to weeks to bring online.</p>", "<p>Cloud backup storage alone provides data retention but no running infrastructure to fail over to, so it cannot meet an aggressive RTO by itself.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An administrator wants syslog to flag messages indicating conditions where immediate action is required, distinct from critical or error-level messages. Which numeric syslog severity level represents this classification?", "prompt": {"question": "<p>An administrator wants syslog to flag messages indicating conditions where immediate action is required, distinct from critical or error-level messages. Which numeric syslog severity level represents this classification?</p>", "answers": ["<p>1</p>", "<p>0</p>", "<p>3</p>", "<p>2</p>"], "feedbacks": ["<p>Severity level 1 is defined as 'Alert' — action must be taken immediately — per the standard syslog severity scale tested on the exam.</p>", "<p>Level 0 is 'Emergency,' meaning the system is unusable, which is more severe than 'immediate action required' and is a distinct category.</p>", "<p>Level 3 is 'Error,' indicating an error condition but not necessarily requiring immediate action.</p>", "<p>Level 2 is 'Critical,' a serious condition, but the exam distinguishes it from Level 1 'Alert,' which specifically denotes the immediate-action classification.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A network team wants to define switch and router configurations as version-controlled text files that are applied automatically via scripts, ensuring consistent and repeatable deployments across the environment. Which concept does this describe?", "prompt": {"question": "<p>A network team wants to define switch and router configurations as version-controlled text files that are applied automatically via scripts, ensuring consistent and repeatable deployments across the environment. Which concept does this describe?</p>", "answers": ["<p>Infrastructure as Code (IaC)</p>", "<p>Zero-touch provisioning without version control</p>", "<p>SNMP-based configuration polling</p>", "<p>Manual change management ticketing</p>"], "feedbacks": ["<p>Infrastructure as Code (IaC) defines device configurations as version-controlled files applied through automation, ensuring repeatability and consistency — exactly as described.</p>", "<p>Zero-touch provisioning without version control automates initial device setup but lacks the versioned, text-based configuration management described in the scenario.</p>", "<p>SNMP is used for monitoring and limited configuration changes via SET operations, not for defining or version-controlling full device configurations.</p>", "<p>Manual change management ticketing relies on human-driven approval and manual application of changes, which is the opposite of automated, code-driven deployment.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A network administrator manages a WAN of older Cisco routers with limited CPU headroom. The security team requests visibility into which applications are consuming the most bandwidth on each WAN link, without adding inline appliances or significantly increasing router CPU utilization. Which monitoring approach BEST meets this requirement?", "prompt": {"question": "<p>A network administrator manages a WAN of older Cisco routers with limited CPU headroom. The security team requests visibility into which applications are consuming the most bandwidth on each WAN link, without adding inline appliances or significantly increasing router CPU utilization. Which monitoring approach BEST meets this requirement?</p>", "answers": ["<p>Enable full packet capture on each router's WAN interface</p>", "<p>Poll interface octet counters via SNMP every 60 seconds</p>", "<p>Configure routers to send syslog messages for every packet forwarded</p>", "<p>Enable sampled NetFlow export on the WAN interfaces</p>"], "feedbacks": ["<p>Full packet capture requires copying and inspecting every packet's payload, which is CPU- and storage-intensive and would overwhelm an older router's limited resources.</p>", "<p>SNMP interface counters only report total bytes/packets per interface — they show link utilization but cannot identify which applications or conversations are consuming the bandwidth.</p>", "<p>Syslog reports discrete system/event messages (e.g., interface up/down, ACL denies); it is not designed to log per-packet or per-flow traffic data and would generate an unmanageable volume of messages.</p>", "<p>Sampled NetFlow exports flow records (source/destination IP, port, protocol, byte counts) using hardware-assisted flow caching, giving per-application/per-conversation visibility while sampling (e.g., 1-in-1000 packets) keeps CPU overhead low on older routers — exactly the tradeoff the scenario requires.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company's SLA requires that, in the event of a database server failure, no more than 4 hours of data may be lost. The current backup job performs a full backup at midnight and replicates it to an offsite location at 6:00 AM. Which change to the backup process is REQUIRED to meet this SLA's data-loss requirement?", "prompt": {"question": "<p>A company's SLA requires that, in the event of a database server failure, no more than 4 hours of data may be lost. The current backup job performs a full backup at midnight and replicates it to an offsite location at 6:00 AM. Which change to the backup process is REQUIRED to meet this SLA's data-loss requirement?</p>", "answers": ["<p>Add a second standby database server configured for automatic failover</p>", "<p>Reduce the RTO by provisioning faster replication hardware</p>", "<p>Increase backup frequency so that backups occur at least every 4 hours</p>", "<p>Change the offsite replication schedule from 6:00 AM to 5:00 AM</p>"], "feedbacks": ["<p>Adding a standby server with automatic failover improves availability and reduces downtime (addresses RTO), but does not by itself reduce how much data could be lost between backups.</p>", "<p>Reducing the RTO addresses how quickly service is restored, which is a separate metric from RPO (data loss); faster replication hardware doesn't change the backup interval.</p>", "<p>The requirement described (maximum acceptable data loss) is the Recovery Point Objective (RPO). With a single nightly backup, up to 24 hours of data could be lost. To guarantee no more than 4 hours of data loss, backups must be taken at least every 4 hours, directly shrinking the RPO to meet the SLA.</p>", "<p>Adjusting the offsite replication time only shifts when the existing nightly backup is copied — it doesn't change how often data is actually captured, so up to 24 hours could still be lost.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization is implementing infrastructure-as-code to push VLAN configurations to 200 switches. The automation script must be safe to re-run multiple times — for example, after a partial failure — without creating duplicate VLAN entries or leaving switches in an inconsistent state. Which characteristic MUST the automation script have?", "prompt": {"question": "<p>An organization is implementing infrastructure-as-code to push VLAN configurations to 200 switches. The automation script must be safe to re-run multiple times — for example, after a partial failure — without creating duplicate VLAN entries or leaving switches in an inconsistent state. Which characteristic MUST the automation script have?</p>", "answers": ["<p>Load balancing</p>", "<p>Idempotency</p>", "<p>High availability</p>", "<p>Change management approval</p>"], "feedbacks": ["<p>Load balancing distributes traffic or workload across multiple resources; it has nothing to do with whether a configuration script can be safely re-executed.</p>", "<p>Idempotency means applying the same configuration operation multiple times produces the same end state as applying it once — the script checks current state and only makes changes needed, avoiding duplicate entries or errors on re-run. This is a core principle of infrastructure-as-code and API-driven automation covered in the Network Operations domain.</p>", "<p>High availability refers to system uptime and redundancy design, not to the behavior of a script when run more than once against the same target.</p>", "<p>Change management approval is an organizational process for authorizing changes before they are made; it does not address the technical requirement that re-running the script not cause duplicate or inconsistent configurations.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An attacker connects a laptop to an access switch port and crafts frames with two 802.1Q tags: the outer tag matches the port's native VLAN and the inner tag matches a restricted VLAN. The first switch strips the outer tag (since it matches native VLAN) and forwards the frame with the inner tag intact to the trunk, allowing the frame to land on the restricted VLAN on a downstream switch. Which single mitigation BEST prevents this specific attack?", "prompt": {"question": "<p>An attacker connects a laptop to an access switch port and crafts frames with two 802.1Q tags: the outer tag matches the port's native VLAN and the inner tag matches a restricted VLAN. The first switch strips the outer tag (since it matches native VLAN) and forwards the frame with the inner tag intact to the trunk, allowing the frame to land on the restricted VLAN on a downstream switch. Which single mitigation BEST prevents this specific attack?</p>", "answers": ["<p>Change the native VLAN on trunk ports to an unused VLAN ID not assigned to any access port</p>", "<p>Enable BPDU guard on all access ports</p>", "<p>Enable DHCP snooping on all VLANs</p>", "<p>Configure port security with a maximum of one MAC address per port</p>"], "feedbacks": ["<p>Double-tagging VLAN hopping relies on the outer tag matching the native (untagged) VLAN of the trunk so it gets stripped. Moving the native VLAN to an unused, dedicated VLAN ID removes the exploitable overlap between native VLAN and any access VLAN, defeating the technique.</p>", "<p>BPDU guard protects against rogue switches sending spanning-tree BPDUs on access ports; it does nothing to stop 802.1Q double-tagging.</p>", "<p>DHCP snooping prevents rogue DHCP servers and builds a binding table for DAI; it is unrelated to VLAN tag manipulation.</p>", "<p>Limiting MAC addresses per port with port security stops MAC flooding/unauthorized device attachment, not the crafted double-tagged frame itself.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A network engineer configures port security on an access switch with a maximum of 2 MAC addresses per port. Security policy requires that when a violation occurs, the port must immediately go into an err-disabled state requiring manual administrator intervention to recover, and an SNMP trap must be generated. Which violation mode satisfies this requirement?", "prompt": {"question": "<p>A network engineer configures port security on an access switch with a maximum of 2 MAC addresses per port. Security policy requires that when a violation occurs, the port must immediately go into an err-disabled state requiring manual administrator intervention to recover, and an SNMP trap must be generated. Which violation mode satisfies this requirement?</p>", "answers": ["<p>restrict</p>", "<p>protect</p>", "<p>shutdown</p>", "<p>sticky</p>"], "feedbacks": ["<p>'restrict' drops offending traffic and increments a violation counter with a log/trap, but keeps the port up and operational rather than disabling it.</p>", "<p>'protect' silently drops traffic from unauthorized MAC addresses with no logging, trap, or notification at all, and the port stays up.</p>", "<p>The 'shutdown' violation mode (the Cisco default) disables the port completely (err-disabled), generates a syslog message and SNMP trap, and requires an administrator to manually re-enable the port (or configure err-disable recovery). This matches the requirement for administrator intervention and alerting.</p>", "<p>'sticky' is not a violation mode; it is a MAC address learning method (sticky secure MAC addresses) that can be combined with any violation mode.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A rogue employee connects an unauthorized wireless router to a wired switch port in a break room. The rogue device begins issuing IP leases to nearby wired clients, causing intermittent connectivity failures across the floor as clients receive conflicting gateway information. Which switch feature, once properly configured, would have prevented this outcome?", "prompt": {"question": "<p>A rogue employee connects an unauthorized wireless router to a wired switch port in a break room. The rogue device begins issuing IP leases to nearby wired clients, causing intermittent connectivity failures across the floor as clients receive conflicting gateway information. Which switch feature, once properly configured, would have prevented this outcome?</p>", "answers": ["<p>Dynamic ARP Inspection (DAI)</p>", "<p>802.1X port-based authentication</p>", "<p>DHCP snooping with the rogue device's port set as untrusted</p>", "<p>Private VLANs (PVLANs)</p>"], "feedbacks": ["<p>DAI validates ARP packets against the DHCP snooping binding table to stop ARP spoofing/MITM; it does not by itself block a rogue DHCP server's OFFER/ACK messages.</p>", "<p>802.1X authenticates devices before granting network access and could indirectly help, but it doesn't specifically target rogue DHCP traffic and is a much larger deployment than the targeted fix described.</p>", "<p>DHCP snooping distinguishes trusted ports (facing legitimate DHCP servers) from untrusted ports (facing end users). DHCP server messages (OFFER, ACK) arriving on an untrusted port are dropped, which stops a rogue DHCP server plugged into an access port from handing out leases.</p>", "<p>PVLANs isolate hosts within the same VLAN from each other at Layer 2, but they don't inspect or block DHCP server messages specifically.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company requires an IPsec VPN tunnel that provides confidentiality (payload encryption) in addition to data integrity and origin authentication for all traffic crossing the tunnel. Which IPsec component must be used to meet this requirement?", "prompt": {"question": "<p>A company requires an IPsec VPN tunnel that provides confidentiality (payload encryption) in addition to data integrity and origin authentication for all traffic crossing the tunnel. Which IPsec component must be used to meet this requirement?</p>", "answers": ["<p>Authentication Header (AH)</p>", "<p>Encapsulating Security Payload (ESP)</p>", "<p>Internet Key Exchange (IKE) Phase 1 only</p>", "<p>Security Association (SA) in transport mode only</p>"], "feedbacks": ["<p>AH provides integrity and origin authentication for the packet (including parts of the IP header) but does NOT provide encryption/confidentiality of the payload.</p>", "<p>ESP provides encryption (confidentiality) of the payload along with optional integrity and authentication, making it the only listed option capable of meeting all three stated requirements including encryption.</p>", "<p>IKE Phase 1 establishes the secure channel used to negotiate IPsec SAs (key exchange/authentication of peers); it is not the component that encrypts the actual data traffic.</p>", "<p>Transport mode vs. tunnel mode describes how much of the packet is protected/encapsulated, not which protocol (AH vs ESP) is used; transport mode alone does not guarantee encryption is applied.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "In an 802.1X deployment, a switch port is configured to require authentication before granting network access to a connected laptop. The laptop runs client software that supplies credentials, and a backend server validates those credentials using RADIUS before the switch unblocks the port. Which role does the SWITCH play in this 802.1X exchange?", "prompt": {"question": "<p>In an 802.1X deployment, a switch port is configured to require authentication before granting network access to a connected laptop. The laptop runs client software that supplies credentials, and a backend server validates those credentials using RADIUS before the switch unblocks the port. Which role does the SWITCH play in this 802.1X exchange?</p>", "answers": ["<p>Supplicant</p>", "<p>Authentication server</p>", "<p>RADIUS client acting as the supplicant</p>", "<p>Authenticator</p>"], "feedbacks": ["<p>The supplicant is the client device (laptop) requesting network access and providing credentials, not the switch.</p>", "<p>The authentication server is the backend RADIUS server that validates credentials and returns an accept/reject decision to the authenticator; the switch itself does not validate credentials.</p>", "<p>The switch is commonly a RADIUS client in that it communicates with the RADIUS server, but its 802.1X role name is specifically 'authenticator,' not 'supplicant acting as RADIUS client,' which conflates two separate roles.</p>", "<p>In 802.1X, the switch (or wireless AP) is the authenticator: it controls the physical/logical port state, relays credentials between the supplicant and the authentication server, and only unblocks the port after receiving approval from the authentication server.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Users on a corporate campus report intermittent disconnections from the legitimate SSID, followed by automatic reconnection to a network with the identical SSID and a stronger signal, after which their traffic seems to be intercepted. Wireless spectrum analysis reveals a second access point broadcasting the same SSID and BSSID characteristics as the legitimate AP but with different backend connectivity. Which control specifically detects and helps mitigate this type of attack going forward?", "prompt": {"question": "<p>Users on a corporate campus report intermittent disconnections from the legitimate SSID, followed by automatic reconnection to a network with the identical SSID and a stronger signal, after which their traffic seems to be intercepted. Wireless spectrum analysis reveals a second access point broadcasting the same SSID and BSSID characteristics as the legitimate AP but with different backend connectivity. Which control specifically detects and helps mitigate this type of attack going forward?</p>", "answers": ["<p>Wireless Intrusion Prevention System (WIPS)</p>", "<p>WPA3-Personal with SAE</p>", "<p>MAC address filtering on the legitimate AP</p>", "<p>Disabling SSID broadcast on the legitimate AP</p>"], "feedbacks": ["<p>This scenario describes an evil twin / rogue AP attack combined with deauthentication to force clients to associate with the attacker's AP. A WIPS continuously monitors RF spectrum for rogue/duplicate APs and unauthorized BSSIDs, can alert administrators, and can actively contain rogue APs, making it the purpose-built control for detecting and mitigating this attack.</p>", "<p>WPA3-Personal with SAE strengthens the handshake against offline password cracking and improves protection against some attacks, but it does not detect or prevent a rogue AP from impersonating the legitimate SSID/BSSID.</p>", "<p>MAC filtering on the legitimate AP controls which clients can associate with that AP; it does nothing to detect or stop a separate rogue AP elsewhere from spoofing the SSID.</p>", "<p>Disabling SSID broadcast only hides the SSID from casual discovery on the legitimate AP; the SSID is still easily learned from client probe requests, and this does nothing to detect or block the rogue AP itself.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A network technician discovers that an attacker connected a rogue switch to an access port and successfully negotiated a trunk link with the production switch, then used double-tagging to send traffic into VLANs the attacker should not have access to. Which action BEST prevents this specific attack in the future?", "prompt": {"question": "<p>A network technician discovers that an attacker connected a rogue switch to an access port and successfully negotiated a trunk link with the production switch, then used double-tagging to send traffic into VLANs the attacker should not have access to. Which action BEST prevents this specific attack in the future?</p>", "answers": ["<p>Enable BPDU guard on all access ports</p>", "<p>Configure DHCP snooping on all VLANs</p>", "<p>Enable port security with a maximum of one MAC address per port</p>", "<p>Disable Dynamic Trunking Protocol on all access ports and manually set them to access mode</p>"], "feedbacks": ["<p>BPDU guard protects against rogue switches participating in STP topology changes, not against trunk negotiation or VLAN hopping.</p>", "<p>DHCP snooping mitigates rogue DHCP servers and is a prerequisite for DAI, but it does nothing to stop trunk negotiation or double-tagging attacks.</p>", "<p>Port security limits the number/identity of MAC addresses on a port to prevent MAC flooding or unauthorized devices, but a single authorized-looking device can still negotiate a trunk if DTP is left enabled.</p>", "<p>VLAN hopping via switch spoofing exploits DTP, which auto-negotiates trunk links. Explicitly setting access ports to 'switchport mode access' and disabling DTP (switchport nonegotiate) prevents the port from ever becoming a trunk, closing off double-tagging and switch-spoofing attacks.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A security engineer wants to prevent an attacker from poisoning ARP caches on a segment by mapping their own MAC address to the default gateway's IP address, redirecting traffic for an on-path attack. DHCP snooping is already enabled. Which additional feature should be configured to stop this specific attack?", "prompt": {"question": "<p>A security engineer wants to prevent an attacker from poisoning ARP caches on a segment by mapping their own MAC address to the default gateway's IP address, redirecting traffic for an on-path attack. DHCP snooping is already enabled. Which additional feature should be configured to stop this specific attack?</p>", "answers": ["<p>Dynamic ARP Inspection</p>", "<p>802.1X port-based authentication</p>", "<p>Private VLANs</p>", "<p>Storm control</p>"], "feedbacks": ["<p>Dynamic ARP Inspection (DAI) validates ARP packets against the DHCP snooping binding table (IP-to-MAC mappings), dropping ARP replies that don't match a legitimate binding. This directly stops ARP spoofing/poisoning used in on-path attacks, and it requires DHCP snooping to already be enabled, which matches the scenario.</p>", "<p>802.1X authenticates devices before granting network access, but it does not inspect or validate ARP traffic on the segment once a device is already connected and authenticated.</p>", "<p>Private VLANs restrict Layer 2 communication between hosts in the same VLAN, but they don't validate ARP-to-IP bindings and won't stop spoofing between allowed hosts.</p>", "<p>Storm control mitigates broadcast, multicast, or unicast traffic storms (e.g., from loops or flooding attacks) but has no mechanism for validating ARP-to-IP-to-MAC bindings.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company is configuring a site-to-site VPN between two branch office gateways. The requirement is that the entire original IP packet, including the original source and destination IP headers, must be encrypted and encapsulated inside a new IP header for transit across the internet. Which IPsec mode meets this requirement?", "prompt": {"question": "<p>A company is configuring a site-to-site VPN between two branch office gateways. The requirement is that the entire original IP packet, including the original source and destination IP headers, must be encrypted and encapsulated inside a new IP header for transit across the internet. Which IPsec mode meets this requirement?</p>", "answers": ["<p>Aggressive mode</p>", "<p>Tunnel mode</p>", "<p>Main mode</p>", "<p>Transport mode</p>"], "feedbacks": ["<p>Transport mode only encrypts the payload of the original IP packet and leaves the original IP header intact/unencrypted, which is used for end-to-end host communication, not gateway-to-gateway tunneling where header concealment is required.</p>", "<p>IPsec Tunnel mode encrypts and encapsulates the entire original IP packet (header and payload) inside a new IP packet with a new header, which is why it's used for gateway-to-gateway (site-to-site) VPNs where the original internal addressing must be hidden from the transit network.</p>", "<p>Aggressive mode is a faster but less secure IKE Phase 1 negotiation method used during key exchange setup; it does not describe how the actual data packet is encapsulated.</p>", "<p>Main mode is the more secure IKE Phase 1 negotiation method for establishing the security association; like aggressive mode, it relates to key exchange, not to whether the original packet header is encapsulated.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A fiber link between two buildings has been experiencing intermittent high error rates. A technician suspects a micro-bend or a partial break somewhere along the 2 km run and needs to pinpoint the exact distance to the fault from the near end. Which tool should be used?", "prompt": {"question": "<p>A fiber link between two buildings has been experiencing intermittent high error rates. A technician suspects a micro-bend or a partial break somewhere along the 2 km run and needs to pinpoint the exact distance to the fault from the near end. Which tool should be used?</p>", "answers": ["<p>Tone generator and probe</p>", "<p>OTDR (Optical Time Domain Reflectometer)</p>", "<p>Cable certifier</p>", "<p>Loopback adapter</p>"], "feedbacks": ["<p>A tone generator and probe is used to trace copper cable paths through walls, not to measure fiber fault distance.</p>", "<p>An OTDR sends light pulses down the fiber and measures reflected/backscattered light to calculate the exact distance to breaks, bends, or connector faults — essential for locating faults on long fiber runs.</p>", "<p>A cable certifier verifies that copper (or fiber) cabling meets a performance standard (e.g., Cat6A) but doesn't precisely locate a fault distance the way an OTDR does.</p>", "<p>A loopback adapter tests whether a port or NIC can send/receive on itself; it doesn't help locate a fault along a cable run.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "Hosts on VLAN 20 can successfully ping hosts on VLAN 10, and packet captures on VLAN 10 confirm the ICMP echo requests arrive and echo replies are sent. However, VLAN 20 hosts report the pings time out. A stateful firewall sits between the VLANs, and each VLAN's traffic takes a different physical path to and from the firewall. What is the MOST likely cause?", "prompt": {"question": "<p>Hosts on VLAN 20 can successfully ping hosts on VLAN 10, and packet captures on VLAN 10 confirm the ICMP echo requests arrive and echo replies are sent. However, VLAN 20 hosts report the pings time out. A stateful firewall sits between the VLANs, and each VLAN's traffic takes a different physical path to and from the firewall. What is the MOST likely cause?</p>", "answers": ["<p>An exhausted DHCP scope on VLAN 10</p>", "<p>Asymmetric routing causing the stateful firewall to drop the return traffic</p>", "<p>A duplicate IP address on VLAN 20</p>", "<p>An incorrect subnet mask configured on VLAN 20 hosts</p>"], "feedbacks": ["<p>A DHCP scope exhaustion would prevent hosts from getting addresses at all, not cause selective ping timeouts once already connected.</p>", "<p>Because each direction of traffic follows a different path, the stateful firewall only sees the reply and never saw the matching outbound request in its session table, so it treats the reply as unsolicited and drops it — a classic asymmetric routing problem.</p>", "<p>A duplicate IP would typically cause intermittent connectivity for both hosts sharing the address and OS-level IP conflict warnings, not this one-directional symmetric drop pattern.</p>", "<p>An incorrect subnet mask would generally break communication in both directions or cause hosts to misroute locally, not produce this asymmetric firewall-drop signature confirmed by the packet capture.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A server connected to a switch port configured for 1000 Mbps/Full duplex is experiencing intermittent slow throughput. The engineer wants definitive proof that a duplex mismatch (one side running full duplex while the other runs half duplex) is the root cause. Which approach will BEST confirm this?", "prompt": {"question": "<p>A server connected to a switch port configured for 1000 Mbps/Full duplex is experiencing intermittent slow throughput. The engineer wants definitive proof that a duplex mismatch (one side running full duplex while the other runs half duplex) is the root cause. Which approach will BEST confirm this?</p>", "answers": ["<p>Run nslookup against the server's hostname</p>", "<p>Capture traffic with a protocol analyzer and look for late collisions and CRC/FCS errors</p>", "<p>Check ipconfig /all on the server for its assigned IP</p>", "<p>Ping the server with an increased packet size (-l 9000)</p>"], "feedbacks": ["<p>nslookup only resolves DNS names to IP addresses and has nothing to do with Layer 1/2 duplex issues.</p>", "<p>Late collisions and CRC/FCS errors captured in a protocol analyzer trace are the hallmark symptom of a duplex mismatch — one side is transmitting while the other is also transmitting because it doesn't believe collision detection is needed, corrupting frames.</p>", "<p>ipconfig /all shows local IP/MAC/DNS configuration but doesn't reveal duplex negotiation problems on the wire.</p>", "<p>A large ping packet test can reveal fragmentation/MTU issues, but it won't specifically confirm collision-related duplex mismatch symptoms.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A network originally provisioned with a DHCP scope of 192.168.1.100–192.168.1.150 supported 50 devices. The office has since grown to 300 devices, and new devices are now receiving 169.254.x.x addresses while existing devices keep working. What is the BEST long-term solution?", "prompt": {"question": "<p>A network originally provisioned with a DHCP scope of 192.168.1.100–192.168.1.150 supported 50 devices. The office has since grown to 300 devices, and new devices are now receiving 169.254.x.x addresses while existing devices keep working. What is the BEST long-term solution?</p>", "answers": ["<p>Increase the size of the DHCP scope to accommodate more addresses</p>", "<p>Reduce the DHCP lease time to 5 minutes</p>", "<p>Configure a DHCP relay agent on the router</p>", "<p>Enable DNS round robin on the DHCP server</p>"], "feedbacks": ["<p>The 169.254.x.x (APIPA) addresses indicate the scope is fully exhausted; expanding the scope (or adding a supplemental scope/subnet) permanently resolves the shortage for a network that has genuinely outgrown its original address pool.</p>", "<p>Drastically shortening the lease time only marginally speeds up address recycling and can cause excessive renewal traffic — it's a band-aid, not a fix for a scope that's permanently too small for 300 devices.</p>", "<p>A DHCP relay agent forwards broadcast DHCP requests across subnets/VLANs to a remote DHCP server — it doesn't create more addresses in an exhausted scope.</p>", "<p>DNS round robin distributes DNS responses across multiple IPs for load balancing; it has nothing to do with DHCP address allocation.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "In a high-density Wi-Fi 6 deployment with many closely spaced access points, users report high latency and excessive retransmissions even though RSSI readings show strong signal everywhere. What is the MOST likely cause, and what tool should be used to confirm it?", "prompt": {"question": "<p>In a high-density Wi-Fi 6 deployment with many closely spaced access points, users report high latency and excessive retransmissions even though RSSI readings show strong signal everywhere. What is the MOST likely cause, and what tool should be used to confirm it?</p>", "answers": ["<p>Co-channel interference from overlapping APs on the same channel; confirm using a Wi-Fi analyzer to review channel utilization</p>", "<p>Weak signal strength; confirm using a spectrum analyzer</p>", "<p>Faulty patch cable to the AP; confirm using a cable tester</p>", "<p>DNS server misconfiguration; confirm using nslookup</p>"], "feedbacks": ["<p>Strong RSSI with high latency/retransmissions in a dense deployment is the classic signature of co-channel interference (multiple APs sharing the same channel causing contention); a Wi-Fi analyzer showing channel utilization and overlapping BSSIDs on the same channel confirms this.</p>", "<p>RSSI is already reported as strong, ruling out weak signal as the cause; a spectrum analyzer is used to detect non-802.11 RF interference (microwaves, Bluetooth), not channel contention between APs.</p>", "<p>A faulty cable would typically cause a single AP or link to drop entirely, not a widespread latency issue affecting many wireless users across a dense deployment.</p>", "<p>DNS misconfiguration would cause name resolution failures, not RF-layer symptoms like retransmissions and latency tied to signal/channel conditions.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "While troubleshooting a name resolution issue, a technician runs 'dig www.example.com' against a public DNS server and receives a response containing 'flags: qr rd ra;' (notably missing the 'aa' flag) along with a populated ANSWER SECTION. What does the absence of the 'aa' flag indicate?", "prompt": {"question": "<p>While troubleshooting a name resolution issue, a technician runs 'dig www.example.com' against a public DNS server and receives a response containing 'flags: qr rd ra;' (notably missing the 'aa' flag) along with a populated ANSWER SECTION. What does the absence of the 'aa' flag indicate?</p>", "answers": ["<p>DNSSEC validation has failed for the domain</p>", "<p>The query failed and no record was returned</p>", "<p>The response is from a server that is authoritative for example.com</p>", "<p>The response is a non-authoritative (cached) answer from a recursive resolver</p>"], "feedbacks": ["<p>DNSSEC validation status is indicated by the 'ad' (authenticated data) flag, not by the absence of 'aa'; nothing here suggests a DNSSEC failure.</p>", "<p>The ANSWER SECTION being populated confirms the query succeeded and a record was returned — it did not fail.</p>", "<p>If the server were authoritative for the zone, the 'aa' flag would be present in the response flags; its absence rules this out.</p>", "<p>The 'aa' (authoritative answer) flag is set only when the responding server is authoritative for the queried zone. Its absence, combined with 'ra' (recursion available) and a populated answer, indicates a recursive resolver is returning a cached, non-authoritative answer on behalf of the authoritative server.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A server connected to a switch experiences degraded throughput only under heavy load, though the link light stays solid green. Interface counters on the switch port show a rising number of late collisions and FCS errors, while the connected port on the far end (the server NIC) has duplex hard-set to 100Mbps/Full and the switch port is left on auto-negotiate. Which is the MOST likely cause?", "prompt": {"question": "<p>A server connected to a switch experiences degraded throughput only under heavy load, though the link light stays solid green. Interface counters on the switch port show a rising number of late collisions and FCS errors, while the connected port on the far end (the server NIC) has duplex hard-set to 100Mbps/Full and the switch port is left on auto-negotiate. Which is the MOST likely cause?</p>", "answers": ["<p>A switching loop causing a broadcast storm on the segment</p>", "<p>VLAN mismatch between the server port and the switch trunk</p>", "<p>Duplex mismatch between the server NIC and the switch port</p>", "<p>The cable run exceeds the TIA/EIA maximum length limit</p>"], "feedbacks": ["<p>A broadcast storm would spike CPU utilization network-wide and flood all ports with traffic, not just degrade one link with late collisions tied to load.</p>", "<p>A VLAN mismatch causes hosts to lose connectivity to the wrong network entirely (or no connectivity), not intermittent performance degradation with FCS/late-collision counters.</p>", "<p>When one side is hard-set to full duplex and the other is left on auto-negotiate, auto-negotiation on the switch side falls back to half-duplex. The full-duplex side transmits without deferring for collisions, producing late collisions and FCS errors that appear specifically under load — the textbook fingerprint of a duplex mismatch.</p>", "<p>Exceeding cable length limits produces continuous CRC/runt errors regardless of traffic load, not late collisions correlated specifically with heavy utilization.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A technician is troubleshooting a single-mode fiber run between two buildings after users report intermittent link drops. The technician needs to pinpoint the exact distance to a suspected micro-fracture or bad splice in the fiber. Which tool should be used?", "prompt": {"question": "<p>A technician is troubleshooting a single-mode fiber run between two buildings after users report intermittent link drops. The technician needs to pinpoint the exact distance to a suspected micro-fracture or bad splice in the fiber. Which tool should be used?</p>", "answers": ["<p>Optical time domain reflectometer (OTDR)</p>", "<p>Visual fault locator</p>", "<p>Optical power meter</p>", "<p>Copper cable certifier with TDR</p>"], "feedbacks": ["<p>An OTDR sends light pulses down the fiber and measures the timing and intensity of reflected light (backscatter) to map the exact distance to faults, splices, bends, or breaks — the fiber equivalent of a copper TDR.</p>", "<p>A visual fault locator shines visible laser light into the fiber to help a technician visually spot a break by eye over short distances, but it does not give a precise numeric distance measurement to the fault.</p>", "<p>An optical power meter measures signal loss (attenuation) end-to-end in dB, confirming there is a problem, but it cannot localize where along the run the fault is located.</p>", "<p>A copper cable certifier with TDR functionality works on twisted-pair copper cabling by measuring electrical reflections; it cannot test fiber-optic cable at all.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}]}];

  const csrf = (document.cookie.match(/csrftoken=([^;]+)/)||[])[1];
  const H = {'Content-Type':'application/json','X-Csrftoken':csrf,'Accept':'application/json'};
  const sleep = ms => new Promise(r=>setTimeout(r,ms));
  const log = (...a)=>console.log('[PT-LOADER]',...a);
  let totalOK=0, totalFail=0;
  for (const t of TESTS){
    log('Creating quiz:', t.name, 'in course', t.cid);
    const cr = await fetch(`/api-2.0/courses/${t.cid}/quizzes/`,{method:'POST',headers:H,body:JSON.stringify({title:t.name,type:'practice-test',description:t.name,duration:t.duration,pass_percent:t.pass_percent})});
    if(!cr.ok){ log('  ERROR creating quiz', cr.status, await cr.text()); continue; }
    const quiz = await cr.json();
    log('  quiz id', quiz.id, '- inserting', t.questions.length, 'questions');
    let ok=0, fail=0;
    for (let i=0;i<t.questions.length;i++){
      const body = t.questions[i];
      let done=false;
      for (let attempt=0; attempt<3 && !done; attempt++){
        try{
          const r = await fetch(`/api-2.0/quizzes/${quiz.id}/assessments/`,{method:'POST',headers:H,body:JSON.stringify(body)});
          if(r.ok){ ok++; done=true; }
          else { if(attempt===2){ fail++; log('   Q'+(i+1)+' failed', r.status, (await r.text()).slice(0,120)); } await sleep(400); }
        }catch(e){ if(attempt===2){ fail++; log('   Q'+(i+1)+' error', String(e)); } await sleep(400); }
      }
      await sleep(120);
    }
    log('  DONE', t.name, '-> inserted', ok, 'failed', fail);
    totalOK+=ok; totalFail+=fail;
  }
  log('ALL DONE. Inserted', totalOK, 'questions total, failed', totalFail, '. Reload the Curriculum page to see the practice tests; then Publish each.');
})();
